window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[10]=[{"i":25465,"n":"כאביסא, אברהם מאלגיר","f":"שלמה","bt":"תרי","dt":"תרף - בערך","b":"רב באל אסנאם(=אורליאנויל)-אלגיר. ברשימת המסייעים בהדפסת \"בית שלמה\" ירושלים תרנה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":25466,"n":"כאהון","k":"ראה: נהון","b":"רב בטיטואן-ת\"ר","s":"אוצר הרבנים 10735"},{"i":25467,"n":"כאסכי, עזרא מחלב","dt":"תרכט - יז חשון","b":"רב בחלב-תריב אחיו של ר שלום.","s":"ארזי הלבנון"},{"i":25468,"n":"כאסכי, שלום מחלב","f":"חלפון","k":"בעל שלום לעם","dt":"תרלב - ה אלול","b":"דיין מחכמי חלב בזמן ר אברהם ענתבי ור חיים מרדכי לבטון בעל \"נכח השלחן\", עם ר חיים מרדכי לבטון ור שלמה נחמד. חתנו ר הלל דוד סתהון בעל \"ארוכה ומרפא\".","s":"ארזי הלבנון"},{"i":25469,"n":"כארזשעלר, זאב מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו.","s":"אוצר כתבי עת-לוין"},{"i":25470,"n":"כאשכיל, משה","f":"יוסף","b":"מחכמי עכו, במחצית השניה של המאה הי\"א.","s":"גליס"},{"i":25471,"n":"כביארה, חזקיה","b":"מחכמי צפת שעבר לחברון, בשנת שעה פנה לעזרת קהלות אלגיר בבקשת עזרה לחברון. מכתב ממנו לאחרים קנשינו באלגיר פורסם על ש. אסף ב\"קובץ על יד\" ג. ומבקש את עזרתם שהוצעה לו לפני שנים רבות עוד בהיותו בצפת.","s":"גליס; ארזי הלבנון"},{"i":25472,"n":"כגן, אברהם מתתיה הכהן מארה\"ב","f":"שמואל אריה","bt":"תרנב-ז","bp":"שנדובה","b":"נכד(-אבי אמו) ר יואל אליעזר פונק משניאדובא. תלמיד ישיבת לומזה, נוברדוק, מאלטש אצל ר דוד דינובסקי. בריינסק, ביהמ\"ד בברלין אצל ר חיים הלר, ונסמך ממנו ומאת ר י\"ל גורדון מלומזה. בעל תואר באוניברסיטה של ברלין. היגר לארה\"ב-תרפח וכיהן כרב בקורונה-לונג איילנד. חבר אגודת הרבנים באמריקה.","s":"אנשי שם-אמריקה; אנשי השם בארהב-איזנשטט"},{"i":25473,"n":"כגן, בועז מארה\"ב","f":"משה אליהו מרגולה","b":"רב בארה\"ב.","s":"ליטא"},{"i":25474,"n":"כגן, יהודה אריה ליב הכהן מארה\"","f":"שלמה אביגדור","k":"בעל הליכות יהודה","bt":"תרסד","bp":"יאנוב-פלך גרודנא","dt":"תשג - יח טבת","b":"נכד ר מאיר יוסף קטקין מיאנובה בעל \"פנים מאירות\". תלמיד ישיבות מיר, ראדין, סלובודקא, קלעם. נסמך מאת: ר חיים עוזר גרודזינסקי, ר צבי הירש קאמאי ממיר, ר אליעזר יהודה פינקל ממיר, ר חיים הליר, רמ\"א עמיאל מתל אביב. חתן ר יצחק קוסובסקי מיוהנסבורג בעל \"שבת ומועד\", וגיסו של ר חיים עוזר גרודזינסקי. רב בלאזדיי, רב באנטוורפן-תרצא, ליאון, שיקגו-תשג. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תלפיות\" - נ\"י תשד. אחיו (נקראו גרשטין: ר יעקב (אריה?) מלאזדיי הי\"ד, ר חיים ברוך הי\"ד מסמיאטיש, ר אלעזר הי\"ד מירושלים.","s":"אוצר הרבנים 3397,7389; אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":25475,"n":"כגן, יהודה ליב מצנסטחוב","b":"רב בית כנסת בצנסטחוב-תרצה.","s":"מתוך קטלוג"},{"i":25476,"n":"כגן, משה אליהו מראגולה ונ\"י","b":"הגיע מראגולה-ליטא לניו יורק וכיהן כרב בניו יורק. בנו ר בועז רב בארה\"ב.","s":"ליטא"},{"i":25477,"n":"כגן, שלמה אביגדור הכהן","b":"חתן ר יוסף קטקין מיאנוב בעל \"פנים מאירות\". רב בירושלים-תרס. בניו - ר יהודה ליב כגן מארה\"ב, ר יעקב מלאזדיי הי\"ד, ר חיים ברוך מסמיאטיץ הי\"ד, ר אלעזר מירושלים הי\"ד.","s":"אוצר הרבנים 18672; אנשי שם-אמריקה"},{"i":25478,"n":"כגן, שמואל אריה משניאדובה","dt":"תש..","b":"חתן ר יואל אליעזר פונק משניאדובה-פלך לומזה. מחכמי שניאדובה. נספה בשואה. בנו - ר אברהם מתתיה מארה\"ב.","s":"אנשי שם-אמריקה"},{"i":25479,"n":"כדורי, יצחק דיבה=זאב מירושלים","f":"כדורי","r":"ראש ישיבת נחלת יצחק","bt":"תרנד - בערך","bp":"בגדד","dt":"תשסו - כט טבת","dp":"ירושלים","b":"תלמיד הבן איש חי בבגדד, עלה לירושלים-תרפג. חתן ר יחקאל נקאש. מגדולי המקובלים בירושלים.","s":"ארזי הלבנון; אפריון שלמה גליון 54, ישראלי גליון 682","bk":[["דברי יצחק - שו\"ת",""],["פתחי עולם - קמעות סגולות ותפלות",""],["פתחי עולם",""],["קדושת יצחק",""]]},{"i":25480,"n":"כדורי, ששון מבגדד","bt":"תרן","dt":"תשלא - כט אייר","dp":"בגדד","b":"מחכמי בגדד, תלמיד ר עבדאללה סומך. חכם באשי-תרפז, ודיין עם ר אברהם אצלן ור סלמן חוגי.","s":"ארזי הלבנון"},{"i":25481,"n":"כהן בצלאל בן ישראל משה","f":"ישראל משה בן בנציון","k":"בעל ראשית בכורים","r":"מו\"צ בוילנא","bt":"תקפ","bp":"וילנא","dt":"תרלח - י ניסן","b":"חתן ר אהרן משולח או ארציק רוזנטל - נישא בגיל 11 וחזר על הקידושין בהיותו בן 13. ובזיוו\"ש חתן הגביר ר יצחק א\"ש (זוערינצער), ובזיוו\"ש חתן הגביר ר צבי הירש באייארין. מו\"צ בווילנה-תרד על מקום ר יוסף שישקס, והיה מנהיגה הרוחני של הקהילה. חיבר גם \"מראה כהן\", \"תוספות בכורים\" ובו הכשיר את אתרוגי קורפו - לאחר שנסע לקורפו לראותם בעיניו והיה מחלוקת בספר \"תוכחת מגולה\" והשיב ב\"להוכיח במישור\" ו\"דברי מלואים\" ועוד. יצא כנגד \"סדרי טהרה\" והוא מסכת כלים החדשה לר גרשון חנוך מראדזין ונגד עשרה מגדולי הרבנים שהסכימו על הספר - כנגדו נכתב בשם בדוי אגרת ב\"המגיד\" וחתם שמחה שלמה יונגער לעווע.","s":"אוצר הרבנים 4014; ליטא; עיר וילנא ח\"א; מוריה 23-א-ב; פין-כנסת ישראל; ברוורמן-אנשי שם; היברובוקס; פרוייקט השו\"ת; שלחן ערוך מהדורת מכון ירושלם בתחילתו; פרוייקט השו\"ת על ספרו מעשה רב על הרמב\"ם","bk":[["מראה כהן [עהש\"ס]",""],["מראה כהן",""],["מראה כהן [על הגמרא]","מפרשי ש\"ס - אחרונים"],["מעשה רב",""],["ראשית בכורים",""],["מעשה רב – רמב\"ם",""],["מראה כהן – שו\"ע",""],["ראשית ביכורים - שו\"ת",""],["מראה כהן [על המשנה]","מפרשי ש\"ס - אחרונים"],["מראה כהן [על מסכתות קטנות]","מפרשי ש\"ס - אחרונים"],["מראה כהן","מפרשי שו\"ע"],["מעשה רב","מפרשי רמב\"ם"]]},{"i":25482,"n":"כהן יעקב בן אברהם מג’רבה","r":"רב בג'רבא אלחארה אלכבירה (הרובע הגדול","bt":"תריב","dt":"תרע \\ תרעב","s":"ריש ספר בכור יעקב, ומבוא ספר ויחי יעקב עמוד א; ריש הספר, ומבוא ספר ויחי יעקב עמוד א; מבוא הספר עמוד א, וריש ספר בכור יעקב; היברובוקס","bk":[["אהבת יעקב - לבושים וחלוקא דרבנן לכמה מסכתות וסדר ההדרן, ודיני מחברי ספרים",""],["בכור יעקב - דרושים לשבתות ומועדים עם דינים ומוסרים",""],["גן יעקב - חידושי תנ\"ך ומדרשים ומערכות על סדר א\"ב",""],["דברי יעקב - פסקים ושו\"ת לאורח חיים ויורה דעה",""],["הליכות יעקב - פסקים ושו\"ת לאבן העזר וחושן משפט",""],["ויחי יעקב – ש\"ס",""],["זכות יעקב - כללי הש\"ס וחידושי אגדות הש\"ס על סדר א\"ב",""],["חיי יעקב – נשים נזיקין",""],["טוב יעקב (כת\"י)",""],["יד יעקב – קדשים טהרות",""],["כוכב יעקב - תענית",""],["לקט יעקב",""],["מאין יבא - תנ\"ך",""],["מעיל יעקב - מעילה",""],["בכור יעקב",""],["גן יעקב",""],["מעיל יעקב",""]]},{"i":25483,"n":"כהן מאיר בן שמואל","bt":"1902","dt":"ה'תשלח 1978","s":"היברובוקס","bk":[["חלקת מאיר",""]]},{"i":25484,"n":"כהן סאסי","bt":"1912","dt":"ה'תשסד 2004","s":"היברובוקס","bk":[["פרוכת המסך",""]]},{"i":25485,"n":"כהן פורט-מנדולין, מנחם","dt":"שסב - י כסלו","b":"מרביץ תורה בויניציאה","s":"אוצר הרבנים 13277"},{"i":25486,"n":"כהן צדוק בן יעקב מלובלין","f":"יעקב מקרייזבורג","k":"בעל פרי צדיק","r":"מלובלין","bt":"תקפג","bp":"קריזבורג-ליטא","dt":"תרס - ט אלול","b":"חתן הגביר ר שמואל הירש הכהן מואלדובקא, ובזיוו\"ש חתן הגביר ר ישראל יעקב מטשכוב, ובזיוו\"ש חתן ר אפרים פישל הכהן משטקטשין-חתן ר משה מללוב. נתפרסם כעילוי בילדותו וגדל אצל דודו ר יוסף הכהן מקריניק ונקרא \"העילוי מקריניק\". קיבל \"היתר מאה רבנים\". תלמיד ר מרדכי יוסף מאיזביצא, ואחריו ר יהודה ליב איגר מלובלין. רב בלובלין-תרג, ואדמור-תרמח על מקום רבו מלובלין. חיבר גם \"אוצר המלך\", ועוד. מתולדותיו ב\"תולדות הכהן מלובלין\", ו\"מלאכי עליון\". נפטר ללא ילדים ונקבר לצד רבו בלובלין. בנו חורגו - ר משה ליינמן מטשמילוב.","s":"אוצר הרבנים 17568; אלפסי; שביעי גליון 870 עמוד 27, זכרו תורת משה גליון תרכח; שביעי גליון 870 עמוד 27; יומא דהילולא; היברובוקס","bk":[["אוצר המלך","מפרשי רמב\"ם"],["רבי צדוק הכהן מלובלין",""],["אוצר המלך – רמב\"ם ושו\"ת",""],["אור זרוע לצדיק – ה' ענינים",""],["דברי סופרים -",""],["דובר צדק",""],["ישראל קדושים",""],["לבושי צדקה – לבוש ושו\"ת",""],["מחשבות חרוץ",""],["משיב צדיק – סוכה בשמ\"ע",""],["פוקד עקרים",""],["פרי צדיק – עה\"ת",""],["צדקת הצדיק",""],["קומץ המנחה",""],["תפארת צב\"י – יו\"ד",""],["תקנת השבין – תיקוני תשובה",""],["ספר הזכרונות – איזה מצוות",""],["רסיסי לילה \\ דברי חלומות",""],["שיחת מלאכי השרת\\שדים",""],["פרי צדיק",""],["אור זרוע לצדיק",""],["הזכרונות",""],["לבושי צדקה",""],["מחשבת צדיק",""],["משיב צדק",""],["רסיסי לילה",""],["שיחת מלאכי השרת",""],["תפארת צב\"י",""],["תפארת צב\"י חלק א",""],["תפארת צב\"י חלק ב",""],["תקנת השבין",""],["אור זרוע לצדיק [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["דברי חלומות [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["דברי סופרים [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["דובר צדק [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["ישראל קדושים [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["לבושי צדקה [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["ליקוטי מאמרים [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["מחשבות חרוץ [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["משיב הטענה [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["משיב צדק [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["ספר הזכרונות [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["עוללות מספרי ר' צדוק הכהן מלובלין","חסידות"],["פוקד עקרים [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["פרי צדיק [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["צדקת הצדיק [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["קומץ המנחה [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["קונטרס ספר הזכרונות [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["רסיסי לילה [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["שיחת מלאכי השרת [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["שיחת שדים [ספרי ר' צדוק הכהן מלובלין]","חסידות"],["תקנת השבין [ספרי ר' צדוק הכהן מלובלין]","חסידות"]],"e":"תקפ\"ג-תר\"ס"},{"i":25487,"n":"כהן צדוק מפריס","bt":"1839","dt":"ה'תרסה 1905","s":"היברובוקס","bk":[["דברי צדוק הכהן",""],["העבדות",""]]},{"i":25488,"n":"כהן צדק גאון פומפודיתא","f":"יוסף","b":"גאון ישיבת פומפודיתא-ד'תרעז (917) על מקום ר יהודה בן שמואל גאון - זקנו של ר שרירא גאון. נבחר ע\"י הנשיא דוד בן זכאי, אך חכמי הישיבה בחרו בר מבשר כהנא לגאון, והיתה מחלוקת בישיבה כחמש שנים, עד שהוסכם שישמשו שניהם - כל אחד בישיבה אחרת. לאחר פטירת ר מבשר הוכר ר כהן צדק כגאון. היה בזמן ר סעדיה גאון בסורא (והיה מחלוקת ביניהם).","s":"ארזי הלבנון"},{"i":25489,"n":"כהן צדק יוסף בן אהרן","f":"אהרן","k":"בעל ישועות מלכי","bt":"תקפז","bp":"למברג","dt":"תרסד","dp":"לונדון","b":"בעל דפוס בלמברג, השתתף בכתבי עת רבים וכתב הקדמות לספרים. הו\"ל \"מגד ירחים\" למברג תרטז, \"אוצר חכמה\" - למברג תרך, \"היהודי הנצחי\" למברג תרכה, \"אור תורה\" פפד\"מ ולמברג תרכד. עבר לקראקא-תרכו, היה דרשן בפפדמ, פריז והולנד. רב בלונדון. חיבר \"ישועות מלכי\" למברג תריד, ועוד.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 8363; אוצר כתבי עת-לוין; בובר-לבוב; היברובוקס","bk":[["אור חדש",""],["אלף אלפין",""],["מוסר השכל",""],["נוה תהלה",""],["קדש הלולים",""],["שבת אחים",""],["שם ושארית",""],["תוספת קדושה",""],["תורה והמצוה",""]]},{"i":25490,"n":"כהן צדק מסורא","f":"איבומאי","b":"גאון סורא- 848, במשך כעשר שנים, על מקום ר משרשיא (משה) כהנא. תשובות ממנו בקובץ תשובות הגאונים - רובם בעברית (ולא בארמית) ורבות מהן בענין ברכות ונוסח התפלה. חיבר סדר ליל פסח. בין הכרעותיו -לומר אהבה רבה בשחרית ואהבת עולם בערבית.","s":"ארזי הלבנון"},{"i":25491,"n":"כהן צדק, אביגדור מוינה","k":"מגדולי הראשונים","b":"רב בוינה-שנת ל'","s":"אוצר הרבנים 21"},{"i":25492,"n":"כהן צדק, אהרן מלבוב","f":"משלם מלמברג","dt":"תקצח","b":"תלמיד הקצות והחוות דעת. מחכמי למברג ויברוב. חתן דודו ר יהודה ליב מבוליחוב. דברי תורה ממנו בתוך המשניות שהוציא אביו עם פירוש \"עיקר תוי\"ט\".","s":"וונדר-גליציה ח\"ג"},{"i":25493,"n":"כהן צדק, אליהו מברעזוב","f":"יצחק איזיק","dt":"תקצה","dp":"דינוב","b":"רב בברזוב.","s":"וונדר-גליציה ח\"ג"},{"i":25494,"n":"כהן צדק, בצלאל מלמברג","f":"משלם","bt":"תקם","dt":"תרח","b":"רב בלמברג על מקום אביו. חתן ר שמואל פילכנפלד מפוזנא.","s":"וונדר-גליציה ח\"ג"},{"i":25495,"n":"כהן צדק, דוד מלונדון","f":"יוסף מלמברג","k":"בעל תולדות הברון רוט","b":"רב בלונדון. עורך לצד אביו של \"אור תורה\" - לבוב, פרסם מאמרים בכתבי עת, הו\"ל \"המבשר\", \"הנשר\". חיבר \"תולדות הברון רוטשילד\", תולדות הרב ד\"ר אשער\".","s":"אוצר הרבנים 4853; אוצר כתבי עת-לוין; אהלי שם"},{"i":25496,"n":"כהן צדק, יהודה ליב","f":"בצלאל","k":"בעל בית יהודה אחרון","bt":"תקפח","dt":"תרמט","b":"רב בסאל. חיבר \"בית יהודה אחרון\" ושאגת ארי\" - בכתב יד.","s":"וונדר-גליציה ח\"ג"},{"i":25497,"n":"כהן צדק, יהודה ליב מבוליחוב","f":"יואל","bt":"תקכא","dt":"תקסב","dp":"מונקטש","b":"חתן ר מאיר חיות מטיסמניץ. רב בבוליחוב (בגיל 16), סטרי-תקמה. מדברי תורתו בספר אחיו \"פתחי נדה\".","s":"וונדר-גליציה ח\"ג"},{"i":25498,"n":"כהן צדק, יואל מאטיניא","f":"יצחק איזיק","bt":"תפ","dt":"תקל","b":"חתן דודו ר דב בר מצורטקוב. רב באטיניא, סטניסלב (נספה בדרך לרבנותו שם).","s":"וונדר-גליציה ח\"ג"},{"i":25499,"n":"כהן צדק, משלם מזורובנה וקוריץ","f":"יואל מאנטוני וסטניסל","k":"בעל עיקר תוי\"ט","bt":"תקיח","dt":"תקע - טו תשרי","dp":"לבוב","b":"חתן ר איציק מבוליחוב בן יחיאל מיכל באב\"ד מבילקמין. רב בזורובנא, קוריץ-תקמח על מקום אחיו בעל \"ברית כהנת עולם\", בוליחוב-תקלו, למברג תקנו. חתן ר יצחק באב\"ד מבוליחוב. חיבר \"פתחי נדה\" למברג תקנז, ועוד. הסכים על \"נחל אשכול\", חדושי מהר\"ם שי\"ף, \"נוית ברמה\"-למברג תקסא, \"שנות אליהו\" ועוד. רב בזוריינא, קוריץ על מקום אחיו ר יצחק איזיק בעל \"ברית כהנת עולם\",, בוליחוב,ראב\"ד בלבוב-תקנו. הו\"ל את כתבי אחיו עם הקדמות והוספות ממנו.","s":"אוצר הרבנים 15695; אוסטרהא קעו; וונדר-גליציה ח\"ג; מצבות קדש-לבוב; בובר-לבוב"},{"i":25500,"n":"כהן שבי, עזרא מירושלים","b":"מחכמי ירושלים-רע.","s":"רוזניס-תורכיה-א"},{"i":25501,"n":"כהן, אברהם ביג משלוניקי","b":"רופא צבאי בשלוניקי-תרס.","s":"זכרון שלוניקי-187"},{"i":25502,"n":"כהן, אברהם דב בער הכהן ממצרים","f":"ישראל מרדכי","b":"רב במצרים, ירושלים-תרלז.","s":"מתוך קטלוג"},{"i":25503,"n":"כהן, אברהם מצייקישוק","dt":"תרנד","b":"רב בצייקישוק.","s":"ליטא"},{"i":25504,"n":"כהן, אדולף מפרשבורג","b":"מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג.","s":"פרשבורג-וינגרטן"},{"i":25505,"n":"כהן, אהרן מירושלים","k":"בעל בית אהרן","b":"עלה לארץ תרפה, ר\"מ בישיבת חברון בירושלים. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא.","s":"אוצר הרבנים 1603; אוצר כתבי עת-לוין"},{"i":25506,"n":"כהן, אהרן מנדל הכהן מקהיר","f":"נתן","k":"בעל אבל מצרים","bt":"תרכו","bp":"טבריה","dt":"תרפח","dp":"חיפה","b":"רב קהילת האשכנזים בקהיר-תרנז, ומחדש הסמיכה?, בשנת תרסא החל לפרסם קובץ \"כנסת הגדולה\", בתרפז הגיע לחיפה. כינס אסיפת רבנים בקראקא-תרסג לצורך חידוש הסמיכה. חיבר ספר \"אבל מצרים\" קהיר תרסט, \"כלילת חתנים\" קהיר תרע ועוד","s":"גליס; אוצר הרבנים 1836; דור וחכמיו-א\"ש-ו; אהלי שם; אצ\"ד ח\"ג"},{"i":25507,"n":"כהן, אלחנן הכהן (סלנטר)","f":"יהודה ליב","k":"עורך תשובות לשואל","bt":"תרכט-לד","bp":"קופישוק","dt":"תרצו - כה תשרי","dp":"דוינסק","b":"תלמיד ר מאיר אטלס. חתן ר מרדכי אליאשברג. רב באסווטיאן(=פושויטין)-ליד יאנושק, ארמשט, סומי, דוינסק-תרפו על מקם ר מאיר שמחה בעל \"אור שמח\". הו\"ל \"תשובות לשואל\" לר אהרן שאול מאירוב מדוינסק עם חדושים והערות ממנו. הניח חבורים בכת\"י. בנו ר בנימין יהונתן. לפי יהדות ליטא נספה בשואה-תשא.","s":"אוצר הרבנים 2010; אובצינסקי-קורלנד; ליטא"},{"i":25508,"n":"כהן, אליהו","dt":"תרפד - כ טבת","dp":"ג'רבא","b":"מחכמי ג'רבא וטריפולי","s":"ארזי הלבנון"},{"i":25509,"n":"כהן, אליעזר מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג.","s":"אוצר כתבי עת-לוין"},{"i":25510,"n":"כהן, אפרים מירושלים","f":"אריה ליב","b":"מנהל ביהמ\"ד למורים \"עזרה\" ונשיא לשכת \"בני ברית\" בירושלים."},{"i":25511,"n":"כהן, בן ציון","k":"בעל שפת אמת","bt":"תשד","bp":"ג'רבא","dt":"תשנו","dp":"ירושלים","b":"חיבר \"שפת אמת\"","s":"ארזי הלבנון","bk":[["שפתי כהן",""]]},{"i":25512,"n":"כהן, בנימין יונתן מדוינסק","f":"אלחנן מדוינסק","bt":"תרנב","bp":"פאשביץ","dt":"תשא-ג","b":"תלמיד ר שבתי קרמר מחרקוב, ישיבת פוניבז, מיר בהזמנת המשגיח ר ירוחם והיה מתלמידיו הקרובים. רב בשאבילן(=שאבלין)-קרולנד, דוינסק על מקום אביו (והיה רבה האחרון של העיר). נספה בשואה.","s":"אוצר הרבנים 3874,3704"},{"i":25513,"n":"כהן, בצלאל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\".","s":"אוצר כתבי עת-לוין"},{"i":25514,"n":"כהן, ברוך","bt":"תרכא","dt":"תרצג - ו תמוז","b":"רב בבריאנסק(ארה\"ב),עלה לא\"י-תרפ\"ג","s":"אוצר הרבנים 4100"},{"i":25515,"n":"כהן, ברוך יצחק מאנגליה","f":"חיים זוסמן מאנגליה","bt":"תרם","b":"נכד-אבי אמו ר יעקב ריינוביץ מלונדון. תלמיד ביהמ\"ד לרבנים בלונדון, ר\"א חייקין. רב בשפילד-תרסז","s":"אוצר הרבנים 4214; אהלי שם"},{"i":25516,"n":"כהן, גרשון ממינסק","f":"אהרן","bt":"תקעט","dt":"תרן - כג טבת","dp":"מינסק","b":"עסקן מחכמי מינסק-תרמד בזמן הגדול ממינסק.","s":"הגדול ממינסק"},{"i":25517,"n":"כהן, דאני מגרבה","f":"אפרים","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"אוצר כתבי עת-לוין"},{"i":25518,"n":"כהן, דוד","b":"חמיו של בעל \"משמרות כהונה\"","s":"ארזי הלבנון"},{"i":25519,"n":"כהן, דוד הנזיר מירושלים","b":"תלמיד הרב קוק. מחכמי ירושלים. נזיר."},{"i":25520,"n":"כהן, דוד מוילנא וירושלים","f":"אהרן","k":"בעל עיר דוד","b":"מחכמי וילנא, עלה לירושלים. חיבר 'זכרון כבוד לעיר דוד'."},{"i":25521,"n":"כהן, דוד מוינה","b":"רב ופרופ', ציר בחצר המלך פרנץ יוזף. חתנו - ר הלל הלוי וייס מארה\"ב.","s":"אנשי שם-אמריקה"},{"i":25522,"n":"כהן, דוד מליטא","f":"ישראל יעקב","bt":"1901","bp":"יאנובה","dt":"1941","b":"מורה בת\"ת. צייר חובב, נסע לברלין ופריס ובשבו לליטא חזר ללמד והמשיך לצייר מחיי סביבתו הדתית. נספה בשואה.","s":"ליטא"},{"i":25523,"n":"כהן, וילהלם מפרשבורג","b":"מנהל ביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה.","s":"פרשבורג-וינגרטן"},{"i":25524,"n":"כהן, זאב אריה מוילנא","k":"בעל מסבות הפעל","b":"מדקדק, מאושר מטעם הממשלה להשכלת העם. חיבר גם \"מסבות השם\" וילנא תרנב - יחד עם דוד אליעזר ברנויץ.."},{"i":25525,"n":"כהן, זאב צבי מברלין","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח.","s":"אוצר כתבי עת-לוין"},{"i":25526,"n":"כהן, זלמן מנירנברג","k":"מהרז\"ך. בעל סדר גטין","b":"מגדולי הפוסקים בחכמי אשכנז,מרביץ תורה בנירנברג-קפ\"א","s":"אוצר הרבנים 5633"},{"i":25527,"n":"כהן, חי מג'רבה","k":"בעל כה לחי","dt":"תרעד","b":"מגדולי חכמי ורבני ג'רבא,אב\"ד ורב ראשי בנפצא,חיבר \"כה לחי\"","s":"ארזי הלבנון"},{"i":25528,"n":"כהן, חיים אורי מוילנא","f":"בצלאל מוילנא","k":"בעל דברי חיים","bt":"תריז","bp":"וילנא","b":"אחיינו של ר שלמה הכהן אב\"ד וילנא. תלמיד ישיבת איישישוק. נסמך מאת ר אליהו אליעזר גרודזנסקי, ור ראובן מדדנברג. דיין בוילנא-תרלו. חיבר גם \"מנחם ציון\" - הספד על ר יצחק אלחנן, \"בונה ירושלים\" - הספד על ר עזריאל הילסדהימר ור\"ש מוהליבר, \"אבן שלמה\" - הספד על דודו ר שלמה הכהן מוילנא.","s":"ליטא"},{"i":25529,"n":"כהן, חיים זוסמן זאב ממנצסטר","dt":"תרסט - בערך","b":"חתן ר יעקב ריינוביץ מולקוביסק ולונדון. מו\"צ בקריסילין, רב במנצסטר-תרע, דיין בלונדון. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה, \"בית ועד לחכמים\" - לונדון תרסב. בנו - ר צבי-רב בלונדון.","s":"אוצר הרבנים 6315; אוצר כתבי עת-לוין; אהלי שם"},{"i":25530,"n":"כהן, חיים יהודה מקרוטשוב","bt":"תריח","b":"רב בקרוטשוב-תר\"נ","s":"אוצר הרבנים 6342"},{"i":25531,"n":"כהן, חיים מגרבה","f":"וזיפה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":25532,"n":"כהן, חיים מתונס","k":"בעל שערי חיים","b":"מחכמי גאבס(טוניסיה),חיבר \"שערי חיים\"(בתוך ספרו של סבו ואביו \"כרם חמדה\")","s":"ארזי הלבנון"},{"i":25533,"n":"כהן, חנניה ס\"ט","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א.","s":"אוצר כתבי עת-לוין"},{"i":25534,"n":"כהן, טוביה","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","s":"אוצר כתבי עת-לוין"},{"i":25535,"n":"כהן, יהודה ליב","k":"בעל \"אידישע פאלקס לי","bt":"1881","bp":"וילנא","dt":"1937","b":"היגר לארה\"ב-1904. חוקר פולקלור של יהודי ליטא פולין ורומניה. קיבץ שירי עם יהודיים על ניגוניהם. חיבר גם \"יידישע פאלקס מעשיות\" נ\"י-וילנא 1931, ועוד.","s":"ליטא"},{"i":25536,"n":"כהן, יהושע","f":"יהודה","k":"בעל בנין העם","bt":"תרנג","bp":"לאריסה-יון","b":"מורה בכי\"ח בבגדאד, התכונן לצאת לצנעא אך לא הספיק, מאזאנאן-מרוקו, עבר לפאריס, חזר לארץ-תרפו, בשליחות בבולגריה-תרפח, ציק הקק\"ל במרוקו וספרד. פרסם מאמרים שונים.","s":"גאון-יהודי המזרח"},{"i":25537,"n":"כהן, יהושע מירושלים","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":25538,"n":"כהן, יואל בר","k":"בעל כבוד מלכים","bt":"1816","bp":"וולוזין","dt":"1871","dp":"וילנא","b":"חיבר גם \"חיי אסף\" - משלי אזופוס עם מבוא. פירוש לילקוט \"היכל רענן\" ועוד.","s":"ליטא"},{"i":25539,"n":"כהן, יונה מראויטש","f":"בנימין","bt":"תרכא","b":"רב ברוויץ(=ראויטש)-תרמד.","s":"אוצר הרבנים 7985; אהלי שם"},{"i":25540,"n":"כהן, יוסף חי מתונס","f":"רפאל שלום","bt":"תרלט","bp":"ספאקס-תונס","dt":"תרצז - יא ניסן","dp":"ירושלים","b":"עלה לירושלים, מלמד בביהמ\"ד לרבנים של חברת \"העזרה\", מלמד תרבות צרפת, אספן בולים. בשליחות במרוקו, בגדאד, מצרים.","s":"גאון-יהודי המזרח"},{"i":25541,"n":"כהן, יוסף מג'ירמוק","f":"סימן טוב ערב","bt":"תרלא","bp":"ג'ירמוק-תורכיה","b":"תלמיד חכמי חלב, ואצל ר יצחק בן אברהם אזולאי, מו\"ץ על מקום רבו (בחלב או בג'ירמוק)-תרמו, עלה לירושלים- וכיהן כרב עדת עולי ג'ירמוק, סויריק, ודיארביקיר בירושלים. דיין-תרפג אצל ר דוד פאפו, יחד עם ר שמואל פארדו.","s":"גאון-יהודי המזרח"},{"i":25542,"n":"כהן, יוסף מגרבה","f":"יהודה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":25543,"n":"כהן, יוסף מטבריה וטריפולי","f":"נחום","bt":"תרך","dt":"תרץ - בערך","dp":"בנגזי-לוב","b":"מחכמי טבריה, עבר לבנגזי-לוב. נזכר אצל ר יוסף חיים ילוז.","s":"מלכי חי\"ל-מרציאנו"},{"i":25544,"n":"כהן, יוסף משלוניקי","b":"ממיסדי ה\"מזרחי\" בשלוניקי-תרעט.","s":"זכרון שלוניקי-217"},{"i":25545,"n":"כהן, יעקב אליהו משלוניקי","b":"מנהל בביה\"ס ת\"ת בשלוניקי-לפני השואה.","s":"זכרון שלוניקי-137"},{"i":25546,"n":"כהן, יעקב מזגערזש","k":"בעל ספר שירים","bt":"תרם","bp":"זעגרזש","b":"משורר. פרסם שירים ב\"המליץ\", ועוד.","s":"דור וחכמיו-א\"ש-ו"},{"i":25547,"n":"כהן, יעקב מפלורינה-יוון","b":"ראש הקהלה בפלורינה-יוון בזמן השואה.","s":"זכרון שלוניקי-262"},{"i":25548,"n":"כהן, יצחק מטוקום","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","s":"אוצר כתבי עת-לוין"},{"i":25549,"n":"כהן, יצחק מיון וירושלים","f":"יהודה","bt":"תרלד","bp":"לאריסה-יון","b":"עלה לירושלים, סייע ליהודי יון שגורשו לתורכיה, הקים שכונות בירושלים יחד עם חברו ישראל חכמשוילי.","s":"גאון-יהודי המזרח"},{"i":25550,"n":"כהן, יצחק משה מדרום אפריקה","bt":"תרלו","b":"תלמיד ביהמ\"ד לרבנים בלונדון, בעל תואר ד\"ר. רב בבולאוואיא(=בולאביו)-דרום אפריקה-תרס. סייעו בידו: ר משה רבינוביץ-תלמיד ישיבת וולוזין, ר זיידל רבינוביץ.","s":"אוצר הרבנים 11444; אהלי שם"},{"i":25551,"n":"כהן, ישראל איסר מלייפציג","bt":"1858","bp":"נובהרדוק","dt":"1924","b":"עבר ללייפציג. מורה ב\"מכון היהודי\" של פרופ' דליטש. חוקר תלמודי בעל השפעה על תיאלוגים פרוטסטנטים שלמדו בלייפציג. תרגם לאידיש ספרי ירמיהו ותהלים. נזכר אצל פרופ' דלמן בהקדמתו לדקדוק העברי-ארמי, ואצל פרופ' לצרוס ב\"מוסר היהדות\", וע\"י פרופ' ר קיטל ב\"מבוא הרומי\" למהדורת התנ\"ך שלו, ע\"י פרופ' שנדרמן בהקדמתו ל\"התיאולוגיה היהודית\" לפ. ובר.","s":"ליטא"},{"i":25552,"n":"כהן, ישראל מקאביליאק וירושלים","dp":"ירושלים","b":"רב בקאביליאק-תרמ. עלה לירושלים.","s":"אוצר הרבנים 11945; אהלי שם"},{"i":25553,"n":"כהן, לוי יצחק","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג.","s":"אוצר כתבי עת-לוין"},{"i":25554,"n":"כהן, ליב מפרשבורג","f":"מנדל מפרשבורג","b":"בנו של מזכיר קהלת פרשבורג בזמן הכת\"ס. חיבר \"כתב יושר דברי אמת\" כנגד ר עקיבא יוסף שלזינגר שיצא כנגד הכת\"ס בענין המטיף - ר פייש פישמן - שדרש בגרמנית ובגלל המגדל שעל ביהכ\"נ. כנגדו יצאה חוברת \"תשובה מאהבה\" מר יהושע ברוך ריינץ מבאלקני, ומרבנים נוספים.","s":"פרשבורג-וינגרטן"},{"i":25555,"n":"כהן, ליבר מניו יורק","b":"פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד.","s":"אוצר כתבי עת-לוין"},{"i":25556,"n":"כהן, ליפמן דובער מזוראויץ","f":"שמעון משה","bt":"תרה","b":"רב בזזוראוויץ-פלך מוהילוב-תרנה.","s":"אוצר הרבנים 12698; אהלי שם"},{"i":25557,"n":"כהן, מאיר גצל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי.","s":"אוצר כתבי עת-לוין"},{"i":25558,"n":"כהן, מאיר מירושלים וארה\"ב","f":"ישראל","bt":"תרעב","bp":"ירושלים","b":"תלמיד ישיבת מאה שערים בירושלים, ישיבת חברון, נסמך מאת: ר איסר זלמן מלצר, ר יעקב משה חרלפ, ר יוסף גרשון הורביץ, ר יצחק יעקב וכטפויגל, רמ\"א עמיאל. חתן ר מנחם מרדכי פרנקל-תאומים מפילדלפיה. רב בפילדלפיה. חבר אגודת הרבנים באמריקה.","s":"אנשי שם-אמריקה"},{"i":25559,"n":"כהן, מנדל מפרשבורג","b":"מזכיר קהלת פרשבורג-תרכג. בנו ר ליב בעל \"כתב יושר דברי אמת\".","s":"פרשבורג-וינגרטן"},{"i":25560,"n":"כהן, מרדכי דוד","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\".","s":"אוצר כתבי עת-לוין"},{"i":25561,"n":"כהן, מרדכי מרודאמין","dt":"תשג","b":"רב ברודאמין","s":"אוצר הרבנים 13865"},{"i":25562,"n":"כהן, משה זאב מפלוטל","f":"שאול","bt":"תרמז","b":"רב בפלאטל(=פלוטל)-פלך קובנא-תרעא.","s":"אוצר הרבנים 15373; אהלי שם"},{"i":25563,"n":"כהן, משה מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\".","s":"אוצר כתבי עת-לוין"},{"i":25564,"n":"כהן, משה מוריס משלוניקי","k":"בעל איל אוניקו קאמינ","b":"סופר ועתונאי ציוני. חיבר בלאדינו \"איל אוניקו קאמינו(=הדרך היחידה) - סופיה תרפב.","s":"גאון-יהודי המזרח"},{"i":25565,"n":"כהן, משה מליטא וארץ ישראל","f":"אברהם יצחק","bt":"1879","bp":"פלשצניץ-פלך מינסק","dt":"1952","dp":"ירושלים","b":"בנו של רבה של קארליץ. מזכיר \"המזרחי\" אצל הרב ריינס. מורה לעברית בישיבת לידא, מזכיר ועד הפליטים במינסק בזמן מלחה\"ע ה-I. עורך \"אונזער פריינד\" בוילנא, \"אידישע שטימע\" בקובנא-1923, \"הד ליטא\", ועוד. עלה לארץ-תרצה.","s":"ליטא"},{"i":25566,"n":"כהן, משה נחמיה מדוואהרט","dt":"תריג - טז סיון","b":"תלמיד ר שמחה בונם מפשיסחא, ר יצחק מוארקי. רב בדווארט-תר.","s":"אוצר הרבנים 15593; אלפסי"},{"i":25567,"n":"כהן, מתתיה מנחם מיון","k":"בעל ממך - בכת\"י","bt":"תריד","bp":"יאנינה-יון","dt":"תרפט - יג כסלו","dp":"אזמיר","b":"מחכמי אזמיר. חיבר ספר מ'מ'ך' בכת\"י - בידי בנו אלברט כהן מירושלים.","s":"גאון-יהודי המזרח"},{"i":25568,"n":"כהן, נסים מגרבה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":25569,"n":"כהן, נפתלי","bt":"תרלב","dt":"תרצט - כג תמוז","b":"מרביץ תורה,רב בברגפרפך,מרבורג,ר\"מ בפולדא,עלה לא\"י","s":"אוצר הרבנים 16125"},{"i":25570,"n":"כהן, עמנואל","bt":"1864","bp":"טוקום-קורלנד","dt":"1941","dp":"ירושלים","b":"רופא ועסקן ציוני. התישב בוילנא-1892 והיה בועד ובבי ציון. השתתף בקבלת הפנים להרצל בוילנא. יו\"ר חברת \"מפיצי השכלה\". פעל להצלת יהודים בזמן פרעות הפולנים-1919 (הציל גם את ל. יפה). עלה לארץ-1923 והיה רופא בהדסה.","s":"ליטא"},{"i":25571,"n":"כהן, עקיבא יוסף מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":25572,"n":"כהן, פנחס מאנסבך","dp":"תשא","b":"רב באנסבך-תרנז-תרעז, מראשי ומיסדי אגודת ישראל בגרמניה, נשיא אגודת ישראל העולמית. עלה לארץ. עליו ב\"תקופות ואישים\" מאת שבתי שינפלד.","s":"אוצר הרבנים 16922"},{"i":25573,"n":"כהן, פנחס מפרשבורג","b":"מראשי אגודת ישראל בפרשבורג-תרף. ממתנגדי הציונות. עלה לארץ.","s":"פרשבורג-וינגרטן"},{"i":25574,"n":"כהן, צבי הירש ממונטריאול","f":"חיים בן יהודה","bt":"תרכב-ה","bp":"בודוביץ-ליד וילקוביסק","dt":"תשי","b":"נכד ר יהודה בודיזעצער. תלמיד ישיבות וילנא, וולוזין. רב ועסקן בליטא, היגר לקנדה-תרן וכיהן כרב במונטריאול. נסמך מאת: ר יעקב דוד מסלוצק-הרידב\"ז. פעל בנושא החינוך היהודי בעירו. בזמן מלחה\"ע ה-I פעל לסידור יתומים יהודים מאוקראינה במשפחות יהודיות בקנדה, והשתתף בעזרה למהגרים. ראש ועד הרבנים במונטריאול-תשב, חבר אגודת הרבנים באמריקה וממיסדיה, ותנועת המזרחי פעל לעזרת יהודי אירופה וסייע לקלוט יתומים מאוקראינה בקנדה. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב.","s":"ליטא; אהלי שם; אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":25575,"n":"כהן, צבי הירש מפיורדא","f":"משה","k":"בעל אמרי צבי","bt":"תרלח","dt":"תרפא","dp":"ארץ ישראל","b":"רב פיורדא, חתנו של ר יעקב כהנא רבה של מאלטש, עלה לארץ ישראל. חיבר \"אמרי צבי\" וילנא תרנח.","s":"גליס; אוצר הרבנים 17310"},{"i":25576,"n":"כהן, צבי מלונדון","f":"חיים זוסמן מלונדון","bt":"תרכט","b":"נכד-אבי אמו ר יעקב מוולוקוביסק ולונדון. תלמיד ביהמ\"ד לרבנים בלונדון. חתן ר יהודה לובצקי מפאריס. רב במערטיר טירוויל-וילס אנגליה-תרנ, נוטינגהם, לונדון. חיבר ספר דרשות - בכת\"י?","s":"אוצר הרבנים 17312; אהלי שם"},{"i":25577,"n":"כהן, קולמן מפרשבורג","b":"שירת כקצין בצבא האוסטרי בזמן מלחה\"ע ה-I, ממארגני ההגנה היהודית בפרשבורג - בזמן הפרעות בסיום מלחה\"ע ה-I.","s":"פרשבורג-וינגרטן"},{"i":25578,"n":"כהן, ראובן","dt":"תשג","s":"אוצר הרבנים 17707"},{"i":25579,"n":"כהן, ראובן ליאון מארה\"ב","f":"אליעזר","bt":"1887","bp":"קובנא","b":"היגר בילדותו לארה\"ב ולמד ביולוגיה. היה ממפתחי \"מבחן כהן\" - בדיקת דם לגילוי מחלת העגבת.","s":"ליטא"},{"i":25580,"n":"כהן, רחמים מג'רבה","k":"בעל יתדות החצר","bp":"ג'רבא","dt":"תשיח","b":"מחכמי ג'רבא. ספרו נדפס בתוך \"נטע רבעי\" תשלג. פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":25581,"n":"כהן, רפאל מגרבה","f":"כלאלו","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":25582,"n":"כהן, רפאל מריגא","dt":"תשג","b":"רב בריגא. פרסם מאמרים בתלמיד ישיבת חב\"ד באוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","s":"אוצר הרבנים 17802; אוצר כתבי עת-לוין"},{"i":25583,"n":"כהן, שלמה מבני ברק","b":"עורך \"השער\" - בני ברק תשח.","s":"אוצר כתבי עת-לוין"},{"i":25584,"n":"כהן, שלמה מפאריס","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":25585,"n":"כהן, שלמה משלוניקי","b":"רופא צבאי בשלוניקי-תרס.","s":"זכרון שלוניקי-187"},{"i":25586,"n":"כהן, שלמה ראובן מאודסה","k":"בעל תפילות הרמב\"ם","bt":"1889","bp":"אוראן-ליטא","b":"תלמיד ישיבות וילנא, קאלם, לידא ואודסה. רופא והסטוריון. מורה לעברית באודסה (אצל אוסישקין, זבוטינסקי, הרב טשרנוביץ, ועוד). רופא בקרים ובקווקז. פרסם מאמרים על נושאים תורניים וציוניים. היגר לארה\"ב-1922. חיבר גם \"תרומת היהודים למדע\", \"גורמי מחלות לפי ספרות התלמוד\".","s":"ליטא"},{"i":25587,"n":"כהן, שמואל דובער","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","s":"אוצר כתבי עת-לוין"},{"i":25588,"n":"כהן, שמעון מצורביץ","b":"חתן ר אריה ליב האפט מקאנאטפ. מו\"ץ בצוראוויץ.","s":"אהלי שם"},{"i":25589,"n":"כהן-בורשטין, מאיר משאטאווע ונ\"","f":"שמואל-מעדני שמואל","bt":"תרסב","bp":"שאטאווע","b":"תלמיד ר שלמה פולצוק, נסמך ממנו ומאת: ר ישראל גוטמן מקמניץ-פודולסק, רמ\"ז מרגליות, ר בנימין ארונוביץ, ר דב רעוועל. רב בשאטאווא על מקום אביו-תרעז, היגר לארה\"ב וכיהן כרב באסבורי פרק-ניו ג'רסי-תרף. פרסם מאמרים ב\"הפרדס\". חבר אגודת הרבנים באמריקה, תנועת המזרחי.","s":"אנשי שם-אמריקה"},{"i":25590,"n":"כהן-ביסטריץ מאיר","bt":"1820","dt":"ה'תרנב 1892","s":"היברובוקס","bk":[["ביעור טיט היון",""]]},{"i":25591,"n":"כהן-קון, אברהם (אלברט) מצרפת","f":"שמשון","bt":"תקעד-ה","bp":"פרשבורג","dt":"תרלו - ד ניסן","dp":"ירושלים","b":"למד בביה\"ס של המשכילים בפרשבורג, תלמיד ר אליעזר הורביץ בוינה, למד באוניברסטיה בוינה, מחנך בבית רוטשילד בפאריס, גבאי צדקה של בית רוטשילד עלה לירושלים-תריד בשליחות משפחת רוטשילד, והיה נציגם בירושלים. שליחו של הברון רוטשילד בשלוניקי, לבדוק הקמת בתי ספר מודרנים בעיר, פעל גם למען יהודי מרוקו. אודותיו ב\"זעליג הויזדארף\".","s":"פרשבורג-וינגרטן; פין-כנסת ישראל; זכרון שלוניקי-127; פרומקין-תח\"י; טולדנו-נר המערב"},{"i":25592,"n":"כהנא יצחק זאב","bt":"1904","dt":"ה'תשכג 1963","s":"היברובוקס","bk":[["לתקנת עגונות",""],["ספר העגונות",""],["שמיטת כספים",""]]},{"i":25593,"n":"כהנא לוי יצחק","bt":"1889","dt":"ה'תשי 1950","s":"היברובוקס","bk":[["משאת בית הלוי",""]]},{"i":25594,"n":"כהנא נחמן בן חיים אריה","f":"חיים אריה-דברי גאוני","k":"בעל ארחות חיים","r":"אבד\"ק ספינקא","bt":"תרכה","bp":"סיגט","dt":"תרסד - כח תמוז","b":"חתן ר יוסף מאיר וייס האדמור מספינקא. רב בספינקא-תרמד והיה מחלוקת על כך מצד בעל \"קדושת יו\"ט\" מסיגט והיתה מחלוקת בין חסידי סיגט לספינקא בגלל זה. בנו ר צבי על מקומו אחריו בספינקא. חיבר \"ארחות חיים\" שזכה להערכה רבה ומהרש\"ם מברעזאן, והאדר\"ת ממיר הוסיפו לספר הערות ותוספות. נפטר בחיי אביו.","s":"אוצר הרבנים 15987; טרנסילבניה; הונגריה; דור וחכמיו-א\"ש-ו; המבשר תורני גליון 239 עמוד לב; תוספת להמודיע אלול תשעד - בני ברק תשעים השנים הראשונות עמוד 136; היברובוקס","bk":[["ארחות חיים – שו\"ע או\"ח",""],["דעת כהן",""],["ארחות חיים",""]]},{"i":25595,"n":"כהנא שמואל זנויל","bt":"1906","dt":"ה'תשנח 1998","s":"היברובוקס","bk":[["רבנו משה בן מימון",""]]},{"i":25596,"n":"כהנא שמעון אריה בן שאול","bt":"1805","dt":"ה'תרלז 1877","s":"היברובוקס","bk":[["הגהות מהר\"שאך",""],["ספרי מהרשאך",""]]},{"i":25597,"n":"כהנא, אברהם אריה ליב מברדיטשו","f":"שלום שכנא מהורודנקא","k":"בעל אור הנערב","bt":"תק","dt":"תקמה-ח","dp":"פולנאה","b":"רב בברודי, ברדיטשוב, פולנאה-תקן. חתן ר מרדכי קע\"ט. חיבר \"אור הנערב\" אוסטרהא תקפד, \"דברי חמד\". בנו - ר שלמה בעל \"דברי שלמה\". אחיו: ר משה מנחם מנדל מזלוויץ, ר אהרן מזלוויץ.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 977,978; אוסטרהא רסא; פין-כנסת ישראל; שם הגדולים השלישי"},{"i":25598,"n":"כהנא, אברהם דב מארה\"ב","f":"יעקב מאיר-מאור יעקב","bp":"לאשע-פלך מינסק","dt":"תשיח","b":"תלמיד ישיבות מיר, סלובודקא, סלוצק, שקלוב אצל ר מאיר שורץ. נסמך מאת: ר ברוך בר ליבוביץ, ר משה שמואל שפירא מבוברויסק, ר\"מ מסלונים, ר חיים עוזר גרודזנסקי, ר משה מרדכי אפשטין. רב ביכנ\"ס במינסק-תרעח, וילנא, ראש החנוך הדתי בוילנא בנשיאות רחיים עוזר, ויסד מוסדות וישיבות ובהם בתי אולפנא \"יבנה\", ממיסדי אגודת ישראל במינסק ובוילנא, היגר לארה\"ב-תרפד וכיהן כרב בניו יורק, פארק-ראקווי-תרפח. מזכיר אגודת הרבנים באמריקה. גיסו - ר דובער אפלמן מברונזויל.","s":"אוצר הרבנים 1015; אנשי שם-אמריקה; מרקוביץ-ראסיין"},{"i":25599,"n":"כהנא, אברהם הפייטן","b":"פייטן, חיבר פיוט \"שמעני וקח את מאמרי\", \"האל אשר המציא לכל נמצא\" עם פירוש ממנו.","s":"פין-כנסת ישראל"},{"i":25600,"n":"כהנא, אברהם יחיאל מיכל","f":"אלכסנדר זושא משדליץ","b":"בנו של בעל \"תורת כהן - יקר מפז\".","s":"אלפסי"},{"i":25601,"n":"כהנא, אברהם מאוסטרהא ודובנא","f":"שלום שכנא כץ מקרקא","dt":"תצא-תצה","dp":"דובנא","b":"רב בברודי, אוסטרהא-תעח על מקום ר בצלאל כץ (בהסכמת ר נפתלי כץ-אביו של ר בצלאל - שהיה הסכם שלא ימנו באוסטרהא רב בחייו - ומחל וחתם על כתב הרבנות), דובנא (ברח מאוסטרהא-תפז או תפח בגלל הדוכס מושל העיר שנתן עיניו בבתו) על מקום ר יהושע בן אליעזר וגיסו ר שאול על מקומו אחריו. הסכים על \"דרש משה\" לר משה דרשן מקראקא-תעט, \"יפה מראה\"-תפד, ועוד. חתנו ר שאול בעל \"בנין אריאל\" על מקומו אחריו בדובנא. הסכים על \"קנין אברהם\" זולקוא תפג, \"יפה מראה\" אמשטרדם תפז, ועוד.נספד ב\"זכר החיים\" לר חיים רפפורט מלבוב. (כשהגיע בבריחתו לדובנא נשאל לאן הוא נוסע וענה שכתוב בתורה אצל הגר שנשאלה אי מזה באת ואנה תלכי וענתה מפני שרי אנכי בורחת - ומכאן שהבורח אינו יודע לאן פניו מועדות - ואז נתבקש מהם לכהן כרב בדובנא). בניו: ר יצחק משה מדובנא, ר ישראל מוישנביץ, חתנו - ר שאול מדובנא בעל \"בנין אריאל\". (יש אומרים שהיה בנו של ר שמואל ונכדו של ר שלום שכנא).","s":"אוצר הרבנים 482; אוסטרהא מא; שם הגדולים השלישי; ברוין-אנשי מופת"},{"i":25602,"n":"כהנא, אברהם מברודי ופולנאה","f":"שמואל","dt":"תקא","dp":"דובנא","b":"רב בברודי, אוסטרהא-תעח על מקום ר נפתלי כץ שעלה לארץ (ונאלץ לברוח בגלל שר העיר), דובנא על מקום ר זלמן אפרים (היה ביניהם פרק זמן שלא כיהן אב\"ד) ובנו ר יצחק משה על מקומו אחריו. חתנו - ר שאול מדובנא. נספד בספר החיים לר חיים רפפורט.","s":"אוצר הרבנים 487; בית העלמין בוילנא-קלויזנר; ברוין-אנשי מופת"},{"i":25603,"n":"כהנא, אברהם מברודי ופולנאה","f":"יצחק משה כהנא","bt":"תק","dt":"טו אדר","b":"חתן ר שאול מאמשטרדם בעל \"בנין אריאל\". רב בברסטיץ, לעת זקנה עבר לברודי. בנו - ר יעקב בעל \"גאון יעקב\".","s":"אוצר הרבנים 489; שם הגדולים השלישי; ברוורמן-אנשי שם"},{"i":25604,"n":"כהנא, אברהם מואסליקוב וירושלים","f":"יעקב בן אברהם","dt":"תרכט - כג חשון","dp":"ירושלים","b":"רב בואסילקוב, ובכמה קהלות, עלה לירושלים. בנו - ר יעקב זאב דינזון-כהנא מפאסוואל בעל \"שארית יעקב\". מצאצאי ר אברהם מקרוז-אחי הגר\"א.","s":"שם הגדולים השלישי"},{"i":25605,"n":"כהנא, אברהם מוישניויץ ודובנא","f":"ישראל מליזנסק או זאב","b":"רב בווינוביץ(=וישנוביץ)-ווהלין, דומ\"צ בדובנא. הסכים על \"נחל אשכול\" דובנא תקסט. בנו - ר שמחה מקטירבורג. לפי שם הגדולים השלישי - שם אביו ר זאב אב\"ד וישנביץ.","s":"אוצר הרבנים 488; אהלי שם; שם הגדולים השלישי"},{"i":25606,"n":"כהנא, אברהם עבר מקוזלוב","b":"רב בקוזלוב, מיקוליניץ.","s":"וונדר-גליציה ח\"ג"},{"i":25607,"n":"כהנא, אהרן אברהם","k":"בעל פרחי אהרן","bt":"תרכד","dt":"תרצו - כה שבט","b":"רב במיכלשוק(=מיכאילשוק), וואסאנש,סוויציאני,ר\"מ בראדין,הומען,עלה לא\"י תרפ\"א,ר\"מ בתל אביב","s":"אוצר הרבנים 1755"},{"i":25608,"n":"כהנא, אהרן מזלוויץ","f":"שלום שכנא מהורודנקא","dt":"תקלד - יב כסלו","b":"רב בזאלזיץ(=זלוויץ). אחיו: ר משה מנחם מנדל מזלוויץ, ר אברהם אריה מברדיטשוב בעל \"אור הנערב\".","s":"אוצר הרבנים 1595; וונדר-גליציה ח\"ג; שם הגדולים השלישי"},{"i":25609,"n":"כהנא, אהרן ממאסיף וסערט","f":"נחמן-ארחות חיים","k":"בעל וערך הכהן","dt":"תשד","b":"חתן ר חיים אלתר דאכנר ממאסיף וסערט. רב בסיטשל, ביסטרא, פטריווא. נספה בשואה.","s":"אוצר הרבנים 1604; טרנסילבניה; הונגריה"},{"i":25610,"n":"כהנא, אהרן מקזילוביץ","b":"רב בקזילוביץ","s":"אוצר הרבנים 1601"},{"i":25611,"n":"כהנא, אהרן מקרקוביץ","b":"אב\"ד קרקוביץ-תרע.","s":"וונדר-גליציה ח\"ג"},{"i":25612,"n":"כהנא, אלחנן","b":"שמש של ק\"ק אשכנזים בירושלים, חתם על כתב רבנות ר דוד אופנהיים בשנת תסז.","s":"גליס"},{"i":25613,"n":"כהנא, אליהו","s":"אוצר הרבנים 2125"},{"i":25614,"n":"כהנא, אליהו מוילנא","f":"יעקב מוילנא","dt":"תקפב - טו כסלו","dp":"וילנא","b":"נכד-אבי אמו ר ישכר בער-אחי הגר\"א.","s":"בית העלמין בוילנא-קלויזנר"},{"i":25615,"n":"כהנא, אליעזר מקרלין","k":"בעל שיח ספונים","b":"רב בקרלין-תק. חיבר פירוש לחמש מגילות בשם \"שיח ספונים\" ונדפס - \"שירת דודים\" על שיר השירים, \"עמק הבכא\" על איכה, ועוד, חיבר גם \"טעמי תורה\" - זולקווא תקב.","s":"אוצר הרבנים 2597; פין-כנסת ישראל"},{"i":25616,"n":"כהנא, אלכסנדר זושא משדליץ","f":"אברהם","k":"בעל תורת כהן - יקר מ","bt":"תקנה","dt":"תקצז - ו אד\"א","b":"תלמיד החוזה מלובלין, ר שמחה בונם מפשיסחא - וכתב את ספר רבו \"קול שמחה\", בנו ר אברהם משה מפשיסחא, ר יצחק מווארקי. רב בשדליץ-תקפו, פלאצק-תקצו. חיבר \"תורת כהן - יקר מפז\". בנו ר אברהם יחיאל מיכל כהנא.","s":"אוצר הרבנים 2811; אלפסי"},{"i":25617,"n":"כהנא, אלתר אליעזר מזידיטשוב ים","f":"יוסף מאיר מספינקא ים","bt":"תרצז","dt":"תשסט","b":"חתן ר יעקב יוסף זיסוויין. תלמיד ישיבת ויזניץ. אדמור בירושלים. בקי בתחומים רבים ובהם מוסיקה, היסטוריה. מקורב לחסידות סטמר ו\"נטורי קרתא\".","s":"אלפסי"},{"i":25618,"n":"כהנא, אריה ליב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר כתבי עת-לוין"},{"i":25619,"n":"כהנא, אריה ליב מזרכניץ","f":"שמואל מדובנא או שלום","b":"רב בזדאבניץ(=זרכניץ). אחיו: ר אברהם מאוסטרהא וברוד ודובנא, ר מרדכי משידלוב, ר ישראל מליזנסק, ר שמואל מדובנא. (לפי שם הגדולים השלישי - אביו היה ר שלום שכנא מקראקא).","s":"אוצר הרבנים 3315; שם הגדולים השלישי"},{"i":25620,"n":"כהנא, אריה ליב מקלויזנבורג","f":"יצחק איזיק","k":"אפאהידער רב","bt":"תרכה","bp":"מונקטש","dt":"תשג - יא חשון","dp":"קלויזנבורג","b":"לאחר שנתייתם גדל אצל אביו חורגו ר יוסף ליב כהנא בסיגט תלמיד ר מנחם מנדל פאנט בדעש, ובעל \"ייטב לב\" בסיגט. חתן ר יחזקאל פאנט בעל \"כנסת יחזקאל\". רב בכפר אפאהידא-ליד קלויזנבורג, עבר לקלויזנבורג.","s":"אוצר הרבנים 3316; טרנסילבניה; ברוין-אנשי מופת"},{"i":25621,"n":"כהנא, אריה פיבוש מקומרנא","f":"אהרן","dt":"תקסו - טז כסלו","dp":"ברודי","b":"רב בקומרנא, ברודי.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 3445"},{"i":25622,"n":"כהנא, בן ציון מירושלים","dt":"תרעו","b":"רב בפלגוריא,עלה לירושלים","s":"אוצר הרבנים 3917"},{"i":25623,"n":"כהנא, בנימין זאב מלמברג","f":"שמואל זנויל","bt":"תרלז","bp":"דוקלא","dt":"תרפד","b":"חתן ר יצחק איזיק פופרש מברודי. עסקן בברודי, למברג . היה בידידות עם מהרם שפירא.","s":"וונדר-גליציה ח\"ג"},{"i":25624,"n":"כהנא, ברוך דוד מוישניצה","f":"לוי יצחק","k":"בעל חיבת הארץ","bt":"תרי","bp":"וישניצה","dt":"תרפד","b":"חתן ר שרגא פייטל. עלה לירושלים-תרלג, צפת - שם הקים קלויז צאנז. בשליחות בגליציה מטעם כולל צפת. חיבר \"חיבת הארץ\" ירושלים תרנז, ועוד.","s":"וונדר-גליציה ח\"ג"},{"i":25625,"n":"כהנא, ברוך מסטוטשין","b":"נכד הישמח משה. רבה הראשון של סטוטשין.","s":"וונדר-גליציה ח\"ג"},{"i":25626,"n":"כהנא, ברוך מקרלסבורג","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא ארה\"ב","b":"אדמור מספינקא בארה\"ב.","s":"אלפסי"},{"i":25627,"n":"כהנא, דוד","k":"בעל תולדות המקובלים","bt":"1838","bp":"אודסה","dt":"1915","dp":"אודסה","b":"חוקר וסופר. פרסם בקובץ \"כנסת ישראל\"-תרמו, את ספר זכרונותיו של זקנו ר דוד בן מאיר הכהן מאודסה.","s":"רוזניס-תורכיה-ו"},{"i":25628,"n":"כהנא, דוד הכהן מברוד","f":"משה","k":"בעל נפש דוד","dt":"תקנט - ל שבט","b":"רב בליטין, דומ\"צ בברוד. בנו - ר לוי כהנא מקאזין.","s":"אוצר הרבנים 4867; אהלי שם"},{"i":25629,"n":"כהנא, דוד מלמברג","f":"שלמה","k":"בעל יומן גיטו למברג","bt":"תרסג","bp":"הרימלוב","b":"דוקטור מאוניברסיטת וינה. רב בלמברג. חתן ר מרדכי אנגלרד. ניצל מהשואה על ידי ההגמון פשיטיצקי - ובמקום מחבואו תרגם את התורה לאוקראינית. עבר לוארשא אחרי השחרור ועסק בשיקום והצלה. עלה לארץ-תשי וכיהן כרב צבאי. רב בבואנוס איירס-תשכח. חיבר \"יומן גיטו למברג\" ירושלים תשלח.","s":"וונדר-גליציה ח\"ג"},{"i":25630,"n":"כהנא, דוד נפתלי הרץ מגוליגור","bt":"תרל","dt":"תש","b":"חתן ר אליעזר מישל מגוליגור. רב בטורקה-תרעב על מקום חותנו, רב בפמורן-תרץ.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 5192"},{"i":25631,"n":"כהנא, הלל מסטניסלב","k":"בעל גלילות הארץ","bt":"תקפא","bp":"סטניסלב","dt":"תרסא - יז ניסן","b":"תלמיד ר משולם ישכר הורביץ מסטניסלב. עבר לבוטושאן והקים בה את בית הספר העברי הראשון. פרסם בכתב עת שונים. חיבר \"גלילות הארץ\" בוקרשט תרם.","s":"וונדר-גליציה ח\"ו"},{"i":25632,"n":"כהנא, זאב וולף מטשארנא","f":"שלמה אריה מעגעראש","k":"בעל אור לישרים","bt":"תרט","bp":"עגערעש","dt":"תש - יב אייר","dp":"טשאנרא","b":"תלמיד הכת\"ס, ומהר\"ם שיק, ור ישראל יצחק לנדסברג מגרוסורדין. חתן ר נתן נטע קולמן מטשארנא, ובזיוו\"ש חתן ר מרדכי רייכנפלד מיאנושהאזא. רב בשימאני-תרמא, טשארנא-תרמג על מקום חותנו, וחתנו ר אריה הברפלד על מקומו אחריו. חיבר \"שפתי כהן\" בסוף \"תל תלפיות\", ו\"אור לישרים\" בסוף \"מלחמת יהושע\" לחותנו זקנו. ?? לא באוצר ??","s":"אוצר הרבנים 5498; החת\"ס ותלמידיו; פרשבורג-וינגרטן"},{"i":25633,"n":"כהנא, חיים אריה מסיגט","f":"יחיאל צבי","k":"בעל דברי גאונים-תרל","bt":"1830","dt":"תרעז - כט שבט","dp":"סיגט","b":"נינו של \"קונטרס הספיקות\". תלמדי ה\"ייטב לב\" בסיגט. חתן ר צבי מדילאטין-גליציה, וגיסו של ר שלמה דרימר בעל \"בית שלמה\". דיין בסיגט אצל רבו ה\"ייטב לב\", והיה מסייע רבות לרבו (כולל השגת היתר מאה רבנים לבנו), אך אחר פטירת רבו היה במחלוקת עם בנו ר חנניה יו\"ט שהתנגד למינו ר נחמן בנו של ר חיים אריה לרבנות ספינקא, ובזמן הפילוג בקהלה עבר לצד הספרדים המתפלגים. היה בעל ספריה גדולה עם ספרים נדירים ובהם הרבה מהחכמים הספרדים, והשתמש בה לספרו \"דברי גאונים\" - שזכה להצלחה ונדפס שלש פעמים בחייו (הערות על ספרו ב\"עמק הלכה\" - דעש תרצב - מאת ר יצחק טיטלבוים מברדיוב). \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב.","s":"טרנסילבניה; אוצר הרבנים 6250; אוצר כתבי עת-לוין; היברובוקס","bk":[["דברי גאונים",""]]},{"i":25634,"n":"כהנא, חיים בצלאל מקלויזנבורג","f":"אריה ליבוש מקלויזנבו","dt":"תשד","b":"נכד ר יצחק איזיק-חתן ר יחזקאל פנט מקרלסבורג. רב ביהמ\"ד \"עבודת כהונה\" בקלויזנבורג-תשג על מקום אביו. חתן ר עזריאל שוורץ מסטמר. נספה בשואה.","s":"טרנסילבניה; אלפסי"},{"i":25635,"n":"כהנא, חיים ממארמארוש","f":"יהודה מנחם מסיגט","k":"בעל אבן שתיה-תרץ","dt":"תרפה - יד שבט","b":"חסיד קוסוב. דיין בכפר סלישט-מאמרמארוש. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, ועוד. חיבר \"אבן שתיה\" על צדיקי בית קוסוב והשלים וערך ר חיים ישכר גרוס מפטריווה.","s":"טרנסילבניה; הונגריה; אוצר כתבי עת-לוין"},{"i":25636,"n":"כהנא, יהודה ליב מלויצק","f":"משה מלויצק","b":"רב בלויצק-תס על מקום אביו.","s":"אוצר הרבנים 7297; אהלי שם"},{"i":25637,"n":"כהנא, יהודה ליב מקידאן","f":"יחזקאל","b":"תלמיד ר שלמה לנדא מוילקומיר. רב בקידאן על מקום ר משה מרדכי קצנלנבוגן ור ראובן זקש על מקומו אחריו. גיסו - ר דב בער רבינוביץ מראסיין. חתם על שטר הרשאה-תקנח, עם הדיין מנחם נחום בן יחיאל מיכל מקידאן.","s":"מרקוביץ-קידאן"},{"i":25638,"n":"כהנא, יהונתן בנימין מקלויזנבור","f":"שלמה יהודה","dt":"תרנ.. - בערך","dp":"ירושלים","b":"תלמיד הכת\"ס. מחכמי קלויזנבורג והיה לו בית מדרש פרטי, וכיהן כרב לא רשמי. בסוף ימיו עלה לירושלים. נזכר בספרי שו\"ת חכמי דורו.","s":"טרנסילבניה"},{"i":25639,"n":"כהנא, יהושע","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס.","s":"אוצר כתבי עת-לוין"},{"i":25640,"n":"כהנא, יהושע מלויצק","f":"ישראל כהנא","dt":"תקלה - ו סיון","b":"רב בלויצק","s":"אוצר הרבנים 7575"},{"i":25641,"n":"כהנא, יהושע מליזנסק","b":"רב בליזנסק-תק\"י","s":"אוצר הרבנים 7574"},{"i":25642,"n":"כהנא, יהושע מקראקא","f":"שלום שכנא כץ מקראקא","dt":"תצה","b":"ראב\"ד בקראקא על מקום אביו.","s":"אוסטרהא מא; שם הגדולים השלישי"},{"i":25643,"n":"כהנא, יוסף אלימלך מאונגוואר","f":"יצחק איזיק מהערנאד","k":"בעל פני יוסף","r":"רב דאונגוואר","bt":"תרכו","bp":"ראסלביץ(=ראסנביץ)","dt":"תשד - י סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, זקנו-ר יצחק ביליצר מנאדי-אידא, ר חיים צבי מנהיימר מאונגואר, ור שלמה גנצפריד מאונגוואר. מקורב לאדמור\"י צאנז, מונקטש ובלז ועוד. חתן ר משה יונגרייז מקאשוי, ובזיוו\"ש חתן ר יאיר קאלוש ממזעאלאברץ. רב וראש ישיבה בהערנאד-שזאדאני(=הערנאדזשאדני)-תרנב על מקום אביו, בוניהאד(=בניהאד)-תרעז, צעהלים-תרפג, אונגוואר-תרצא. נשיא הלשכה האורטודוכסית בבודפשט. חתם על כרוז יחד עם הבישוף ד\"ר סטויה - לשמור על הצניעות בקרב המתרחצים בנהר אוג. נספה בשואה. חיבר גם \"פני יוסף\". פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד.","s":"אוצר הרבנים 8713; החת\"ס ותלמידיו; הונגריה; אוצר כתבי עת-לוין; אהלי שם; תוספת להמודיע ח' סיון תשעג עמודים י - יא","bk":[["חידושי מהרי\"א הכהן",""]]},{"i":25644,"n":"כהנא, יוסף מאיר מספינקא ירושל","f":"צבי בן נחמן","k":"אדמור מספינקא ירושלי","bt":"תרע","dt":"תשלח - ח שבט","b":"נינו של האדמור ר יוסף מאיר וייס מספינקא. נכד-אבי אמו ר יוסף מאיר מספינקא. חתן ר יצחק טיטלבוים מהוסקוב (שושלת אויהל), (או של החקל יצחק מספינקא). רב בסערדנא-תרצו, אדמור באונגוואר, עלה לארץ-תשא וכיהן כאדמור מספינקא בירושלים, והקים ישיבת \"אמרי יוסף\". בנו ר ברוך חתן ר יעקב לייזר מפעשוורסק-אנטורפן.","s":"אלפסי"},{"i":25645,"n":"כהנא, יוסף מדווטשר","k":"בעל חקירת בראשית","b":"רב בפוגאראש,דווטשר-תר\"י","s":"אוצר הרבנים 8373"},{"i":25646,"n":"כהנא, יוסף מרדכי","f":"פיבוש","b":"רב מדרגמרשטט-תר\"מ","s":"אוצר הרבנים 8931"},{"i":25647,"n":"כהנא, יוסף מרדכי מטעטש","f":"יחיאל צבי כהנא","k":"בעל דברי צדיקים","dt":"תרנו - יב סיון","b":"תלמיד בעל \"ייטב לב\", ור שמואל שמלקא מסעליש. רב ודומ\"צ בטעטש.","s":"אוצר הרבנים 8930; הונגריה"},{"i":25648,"n":"כהנא, יחזקאל שרגא מצפת-ברוקלין","f":"נחמן מצפת","b":"תלמיד הדעת סופר, והעילוי ממיצ'ט בניו יורק. חתן ר ברוך שלום טריינין מדוינסק. רב בברוקלין. חיבר ספרים בעברית אידיש ואנגלית. וביניהם \"תורה ישרה\". בנו ר מאיר דוד שהקים את הליגה להגנה יהודית ור נחמן בעל \"מי מנוחות\". (שם אביו בגליציה - ברוך דוד מוישניצה)","s":"וונדר-גליציה ח\"ו, החת\"ס ותלמידיו"},{"i":25649,"n":"כהנא, יחיאל מיכל מסיגט","b":"נכד בעל קונטרס הספקות. חתן ר לוי יצחק הורביץ מבלחוב. מחכמי סיגט. בנו - ר שמואל זנויל כהנא-פרנקל מבודפשט.","s":"החת\"ס ותלמידיו"},{"i":25650,"n":"כהנא, יחיאל מיכל מפודהייץ","b":"רב בפודהייץ-תרב.","s":"וונדר-גליציה ח\"ג"},{"i":25651,"n":"כהנא, יחיאל מסאלקה","f":"יהודה כהנא","dt":"תרו - יג אייר","b":"רב בסאלקה","s":"אוצר הרבנים 9166"},{"i":25652,"n":"כהנא, יחיאל צבי","f":"יוסף מרדכי כהנא","b":"רב בסיגעט-תר\"כ","s":"אוצר הרבנים 9335"},{"i":25653,"n":"כהנא, יעקב אליהו וילצקי מפלאוו","dt":"תרמח","b":"תלמיד הפרי מגדים, ור צבי הירש הלר. אב\"ד פלאוונא, טומשוב.","s":"מתוך קטלוג"},{"i":25654,"n":"כהנא, יעקב גדליה","f":"יחיאל צבי","k":"בעל רמזי תורה-תרלו","b":"נינו של בעל \"קונטרס הספיקות\". מחכמי סיגט.","s":"טרנסילבניה"},{"i":25655,"n":"כהנא, יעקב מאיר מלאשע וניו יור","f":"אברהם דב הכהן","k":"בעל מאור יעקב","bt":"תרכ","bp":"מיר","dt":"תרצד - כח תשרי","b":"תלמיד ישיבות מיר אצל ר חיים ליב טיקטינסקי, וולוזין. רב בלאשע-פלך מינסק-תרמה, מינסק, פלונגיאן, מו\"צ בוילנא, ניו יורק-תרפד. נסמך מאת: ר ירוחם יהודה פרלמן - \"הגדול ממינסק\", ר הלל משקלוב וחסלביץ, ר יוסף רוזין מטלז וסלונים, ר שלמה הכהן מוילנא. בנו - ר אברהם דב מארה\"ב, חתנו - ר דב אפלמן מניו יורק.","s":"אוצר הרבנים 10214; אהלי שם; אנשי שם-אמריקה"},{"i":25656,"n":"כהנא, יעקב מבוליחוב","b":"רב בבוליחוב-תריח.","s":"וונדר-גליציה ח\"ג"},{"i":25657,"n":"כהנא, יעקב מבריסק","b":"רב בקלויז בבריסק בזמן רבנות ר שלמה זלמן בן ירמיה יעקב, אב\"ד מוהילוב. נזכר בהקדמת אחיינו - ר יעקב כהנא מטיעשן - בספרו \"אהל יעקב\".","s":"בריסק-עיר תהלה"},{"i":25658,"n":"כהנא, יעקב מוילנא","f":"אברהם מברסטביץ","k":"בעל גאון יעקב","r":"מח\"ס מרא דמתניתא, תנא ירושלמי כת\"י","bt":"תקכד","dt":"תקפו - יט אד\"ב","dp":"וילנא","b":"נכד (אבי אמו) ר שאול מאמשטרדם. מצאצאי ר שלום שכנא מלובלין. חתן ר ישכר בער-אחי הגר\"א וישב אצלו. מגדולי חכמי וילנא, נאמן קהילת וילנא ומנהל עניני הצדקה. חיבר פירוש למסכת עירובין בשם \"גאון יעקב\" - המו\"ל ר רפאל נתן רבינוביץ - לבוב תרכג. בנו ר אליהו.","s":"אוצר הרבנים 9684; ליטא; בית העלמין בוילנא-קלויזנר; פין-כנסת ישראל; פין-קריה נאמנה; כתבי גאונים דף ד ע\"א הערה ג; יומא דהילולא","bk":[["גאון יעקב עירובין",""],["גאון יעקב",""],["מרא דמתניתא","מפרשי תוספתא"],["גאון יעקב [עמ\"ס עירובין]",""],["גאון יעקב","מפרשי ש\"ס - אחרונים"]],"e":"תקכ\"ד-תקפ\"ו"},{"i":25659,"n":"כהנא, יעקב מחצי-עמר","b":"אב\"ד חצי-עמר - תרנו. חתן ר מרדכי אשכנזי מפיסטין.","s":"וונדר-גליציה ח\"ג"},{"i":25660,"n":"כהנא, יעקב מצ'רנוביץ","dt":"ט כסלו","b":"דיין בטשרנוביץ(=צ'רנוביץ).","s":"אוצר הרבנים 9685"},{"i":25661,"n":"כהנא, יעקב מקולומיאה","b":"רב בקולומיאה-תרלח.","s":"וונדר-גליציה ח\"ג"},{"i":25662,"n":"כהנא, יעקב מראווא","b":"רב בראווא.","s":"וונדר-גליציה ח\"ג"},{"i":25663,"n":"כהנא, יעקב משניפישוק","b":"מרביץ תורה בשניפישק-תר\"כ","s":"אוצר הרבנים 9686"},{"i":25664,"n":"כהנא, יצחק איזיק","dt":"תשד","b":"רב בפאררא","s":"אוצר הרבנים 11187"},{"i":25665,"n":"כהנא, יצחק איזיק הכהן מרסנוביץ","f":"מאיר כהנא אלטשולר","dt":"תרנב - כא טבת","b":"רב בראסלביץ(=רסנוביץ), הערנאד-זשאדאני. חתן ר יצחק איזיק הלוי ביליצר מנאדי-אידא. אביו היה רבה של טשעטשאביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד.","s":"אוצר הרבנים 11183; החת\"ס ותלמידיו; אהלי שם; אוצר כתבי עת-לוין"},{"i":25666,"n":"כהנא, יצחק מבריסק ופרמישלא","b":"דיין בפרמישלא, חתם-תמא על תקנה בועד ארבע ארצות בירוסלב עם ר יעקב בהר\"ש מקראקא, ר קלונימוס בן משה הקדוש מפוזנא, ועוד.","s":"בובר-זולקוא"},{"i":25667,"n":"כהנא, יצחק מדרוהוביטש","k":"בעל פני יצחק","b":"רב בדרוהוביטש. חיבר \"פני יצחק\" בכתב יד.","s":"וונדר-גליציה ח\"ג"},{"i":25668,"n":"כהנא, יצחק מירושלים","f":"יהודה ליב","k":"בעל תולדות יצחק","dt":"תרס - א אדר","dp":"ירושלים","b":"רב בסובאלק ובערים נוספות, עלה לירושלים-תריג, והיה מחכמי \"בית אל\". בשנת תרטז חתם בירושלים ב\"מעשה אבות\". חיבר \"תולדות יצחק\" ירושלים תרלד. בפטירתו אמר ר זלמן בהר\"ן להגאון מדוברובנא להספידו ולפרסם שהיה מל\"ו צדיקים שבדור.","s":"גליס; אוצר הרבנים 10734; פרומקין-תח\"י"},{"i":25669,"n":"כהנא, יצחק מקראקא","b":"רב בקרקא","s":"אוצר הרבנים 10733"},{"i":25670,"n":"כהנא, יצחק מרדכי ממינסק וירושל","k":"בעל זכר לחיים","b":"מחכמי מינסק, עלה לירושלים בזמן השואה."},{"i":25671,"n":"כהנא, יצחק משה מדובנא","f":"אברהם מדובנא","dt":"תקה-ו","dp":"דובנא","b":"אב\"ד דובנא-תצה על מקום אביו ור שאול=חתנו של החכם צבי על מקומו אחריו. חתם על תקנות רבות בפנקס קהלת דובנא. גיסו - ר שאול.","s":"אוצר הרבנים 11442; שם הגדולים השלישי; ברוין-אנשי מופת"},{"i":25672,"n":"כהנא, ישראל יונתן בנימין","f":"שלמה יהודה הכהן","bp":"קראסנא","dt":"תרסט - כו אב","dp":"ירושלים","b":"תלמיד הכת\"ס, ור יצחק שמחה ברגר ממאדיאר לאפוש. חתן ר שמחה ליב. רב בקלויזנבורג-תרלא. עלה לירושלים-תרנו.","s":"החת\"ס ותלמידיו"},{"i":25673,"n":"כהנא, ישראל מבריסק","f":"יונה","b":"פרנס בבריסק, חתם-תקיב עם כמה מחבריו על מכתב לר יונתן איבשיץ בענין הקמיעות.","s":"בריסק-עיר תהלה"},{"i":25674,"n":"כהנא, ישראל מוישנביץ","f":"אברהם מאוסטרהא ודובנ","b":"רב בוישנוויץ(=וישנביץ).","s":"שם הגדולים השלישי"},{"i":25675,"n":"כהנא, ישראל מליזנסק","f":"שמואל או שלום שכנא מ","dt":"תקטו - ו חשון","b":"רב בליזנסק. בנו - ר אברהם מוישנוביץ.","s":"אוצר הרבנים 11947; אהלי שם; שם הגדולים השלישי"},{"i":25676,"n":"כהנא, ישראל מנאווריא וזולקוא","f":"מרדכי","k":"בעל בית ישראל","bt":"תקסא","bp":"ברודי","dt":"תרמא - יד שבט","dp":"זולקוא","b":"רב בנבריה(=נאווריא), זולקוא-תרא. חיבר \"בית ישראל\" זולקוא תריח.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 11948; בובר-זולקוא"},{"i":25677,"n":"כהנא, ישראל מרוזינאי","dt":"תקנה - ג שבט","b":"רב ברוזינאי","s":"אוצר הרבנים 11946"},{"i":25678,"n":"כהנא, לוי הכהן","f":"דוד","dt":"תקצז - יט חשון","b":"רב בקאזין. בנו - ר מאיר מטשטשעויץ.","s":"אוצר הרבנים 12463; אהלי שם"},{"i":25679,"n":"כהנא, לוי יצחק מארה\"ב","k":"בעל משאת בית הלוי","b":"רב בארה\"ב-תרצו.","s":"אמריקה"},{"i":25680,"n":"כהנא, מאיר מטשעטשביץ","f":"לוי כהן","bt":"תקנ","dt":"תרטז - כח ניסן","b":"רב בטשעטשעוויץ-תקע\"ז","s":"אוצר הרבנים 12861"},{"i":25681,"n":"כהנא, מנחם מהומענע","dt":"תשד","b":"רב בהומענע","s":"אוצר הרבנים 13258"},{"i":25682,"n":"כהנא, מנחם מנדל מזאלוזיץ","f":"שלום שכנא כהנא מהורד","b":"רב בזאלוזיץ-תק\"נ","s":"אוצר הרבנים 13469 ו-13370"},{"i":25683,"n":"כהנא, מנחם מנדל מזברז","bt":"תקפב","dt":"תרל","b":"רב בטויסט, זברז-תר.","s":"וונדר-גליציה ח\"ג"},{"i":25684,"n":"כהנא, מנחם מנדל מספינקא לונדון","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא לונדון","b":"חתן ר דוד צבי שניבלג מויזניץ. אדמור מספינקא-תשמח בלונדון.","s":"אלפסי"},{"i":25685,"n":"כהנא, מנחם נחום","k":"בעל צמח מנחם","b":"רב בצערקוב-תק\"ע, מחותן עם ר מאיר גינצבורג מוילנא וגליל וויזון. חתנו - ר צבי הירש א\"ש. ?? לא באוצר ??","s":"אוצר הרבנים 13591; גינצבורג"},{"i":25686,"n":"כהנא, מרדכי דוד מספינקא י-ם","f":"יוסף מאיר מספינקא ים","k":"בעל ברכת אבי","bt":"תרצא","b":"בן האדמור מספינקא. חתן ר משה מנחם הרשטיק. חבר מערכת \"אוצר הפוסקים\" בירושלים.","s":"אלפסי"},{"i":25687,"n":"כהנא, מרדכי מוילנא","b":"מחכמי וילנא, חתם-תמא בועד ירוסלב על תקנת קהלת זולקוא, עם ר קלונימוס בן משה הקדוש מפוזנא, ועוד.","s":"בובר-זולקוא"},{"i":25688,"n":"כהנא, מרדכי ממאהליב","f":"נתן נטע מאוסטרהא","b":"רב באמיסטיבווה, אפטא, מוהלוב-תמד. תשובה ממנו בשו\"ת מהר\"ם זיסקינד רוטנבורג.","s":"אוסטרהא"},{"i":25689,"n":"כהנא, מרדכי מנייהייזל","f":"נחמן","k":"אדמור מנייהייזל","dt":"תשד - כו סיון","b":"נכד האדמור מספינקא ר יוסף וייס. חתן ר אהרן וייס מבנדיקוביץ. רב בכפר קעכניא-מארמרוש, רב בפאביאנהאזא-הונגריה. אדמור בנייהייזל. נספה בשואה. הו\"ל \"ליקוטי תורה\" לזקנו בעל \"אמרי יוסף\" - סיגט תרנב.","s":"אוצר הרבנים 13868; טרנסילבניה; ברוין-אנשי מופת"},{"i":25690,"n":"כהנא, מרדכי משידלוב","f":"שמואל או שלום שכנא","b":"רב בשידלוב-ת\"ק","s":"אוצר הרבנים 13867; שם הגדולים השלישי"},{"i":25691,"n":"כהנא, משה אליקים בריעה מספינקא","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא ב\"ב","b":"אדמור מספינקא ב\"ב על מקום אביו.","s":"אלפסי"},{"i":25692,"n":"כהנא, משה הכהן מבלז","f":"יהודה ליב הכהן","k":"בעל קרן אור","b":"רב בבעלז-תקכ. חיבר גם \"מראה כהן\". בנו - ר דוד בעל \"נפש דוד\".","s":"אוצר הרבנים 14780; אהלי שם"},{"i":25693,"n":"כהנא, משה זעירא מפרמישלא","f":"יוסף","b":"חתם בועד ירולסב-תנו בענין מדפיסי זולקוא, עם ר מנחם בן יוחנן ברוך מיונה, ועוד.","s":"בובר-זולקוא"},{"i":25694,"n":"כהנא, משה מאוסטרהא","f":"אהרן כהנא","dt":"תסד - ח טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא.","s":"אוסטרהא לא; בובר-לבוב"},{"i":25695,"n":"כהנא, משה מאמסטיבאוו ווילנא","bp":"אמסטיבאוו","b":"תלמיד ר עקיבא איגר, מחכמי וארשא, וילנא. שאלה ממנו לר חיים מוולוזין.","s":"מתוך קטלוג"},{"i":25696,"n":"כהנא, משה מבוצאץ","b":"רב בבוצאץ.","s":"וונדר-גליציה ח\"ג"},{"i":25697,"n":"כהנא, משה ממאחניווקע","f":"ישראל","bt":"תרל","b":"רב במחנובקה(=מאחניווקע)-פלך קיוב-תרנו.","s":"אוצר הרבנים 14797; אהלי שם"},{"i":25698,"n":"כהנא, משה מנחם מנדל מזלוויץ","f":"שלום שכנא מהורודנקא","b":"אב\"ד זלוויץ. אחיו: ר אהרן מזלוויץ, ר אברהם אריה ליב מברדיטשוב בעל \"אור הנערב\".","s":"שם הגדולים השלישי"},{"i":25699,"n":"כהנא, משה שמחה מסטניסלב","k":"בעל זכרון שמואל","b":"רב בסטניסלב-תרכט. חיבר \"זכרון שמואל\" בכתב יד.","s":"וונדר-גליציה ח\"ג"},{"i":25700,"n":"כהנא, משלם זוסיא מקמניץ-פאד","b":"רב בקמניץ-פאד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"הבונה\" - לבוב תרסד.","s":"אוצר כתבי עת-לוין"},{"i":25701,"n":"כהנא, נחום מיכל מפלונגיאן","b":"רב בפולאנגן(=פלונגיאן)-תרלח על מקום ר יהושע הלר, שוקיאן.","s":"ליטא; אובצינסקי-קורלנד"},{"i":25702,"n":"כהנא, נחמן מירושלים","f":"ברוך דוד","bt":"תרכט","b":"עלה לארץ עם אביו בילדותו. חתן ר משה יהודה יעבץ-מילר. עסק בקבלה עם ר יהושע פלאג'י.","s":"וונדר-גליציה ח\"ג"},{"i":25703,"n":"כהנא, נחמן מסיגט","f":"יהודה-קונטרס הספיקות","b":"דומ\"צ בסיגעט-תר. בנו - ר יוסף אריה מסיגט-חתן ר יחזקאל פנט מקרלסבורג.","s":"אוצר הרבנים 15986; טרנסילבניה; גרינוולד-סלובקיה והונגריה"},{"i":25704,"n":"כהנא, נחמן מספינקא","f":"צבי הירש מספינקא","k":"אדמור מספינקא בני בר","bt":"תרסה","bp":"ספינקא","dt":"תשלז - יז תשרי","dp":"ירושלים","b":"חתן דודו ר יעקב ישראל וישורון רובין האדמור מסוליציא. רב חסידי בקרלסבורג. ניצל מהשואה ואחריה דיין בקלויזנבורג ועסק בהתרת עגונות. עלה לארץ-תשי, וכיהן כרב המושב בני ראם, עבר לבני ברק וכיהן כאדמור מספינקא.","s":"טרנסילבניה; אלפסי","bk":[["ארחות חיים","שו\"ע או\"ח"]]},{"i":25705,"n":"כהנא, נתן זאנוויל מסיגט","f":"יוסף יוחנן","k":"בעל מלחמת התבל-תרעז","b":"נינו של בעל \"קונטרס הספיקות\". גביר מראשי הקהלה הספרדית בסיגט. חיבר \"מלחמת התבל באור היהדות\" ובו תמיכה בהתגיסות היהודים לצבא ההונגרי במלחמת העולם, ומתאר את מעללי הקוזקים כנגד קהלות ישראל בגליציה.","s":"טרנסילבניה"},{"i":25706,"n":"כהנא, נתן נטע מאוסטרהא","f":"משה מרדכי","dt":"תיז או תמג","b":"נכד ר נתן נטע הכהן מברעזן וראש הישיבה בלבוב. ראש חכמי דורו, רב בירוסלב-שצב, אוסטרהא והגליל על מקום ר שמשון באך-אחרי שצו. ניצל מפרעות תח ותט. הסכים על ספר \"הש\"ך\", ועוד. (יתכן שהוא ר נתן בן משה שמזכיר שטינשנידר ב\"ספרות ישראל\" - שנהרג בידי התורכים בעיר אונגריש ברוד במורביה-תמג). בנו ר מרדכי ממאהליב, וחתנו ר משה חריף מפולנאה בן שלמה חריף מלבוב - ונכדו - ר משה חריף מלבוב. (אצל בובר מביא שיש אומרים שבנו גם ר וולף וחתנו - ר יוסף בן משה חריף מלבוב) מצאצאיו ר אהרן מטרבאלי בעל \"שם אהרן\", ו\"מקלו של אהרן\".","s":"אוצר הרבנים 16432; אוסטרהא טו; אבני בית היוצר-וייס; בובר-לבוב"},{"i":25707,"n":"כהנא, פיבוש מווישיווה","f":"ישעיה","b":"מצאצאי בעל \"קונטרס הספיקות\". נכד ר חיים אריה כהנא בעל \"דברי גאונים\". רב בכפר אונטר-ווישיווה-תרפח על מקום ר יוסף מאיר ורצברגר. נספה בשואה.","s":"טרנסילבניה"},{"i":25708,"n":"כהנא, צבי הירש מבלבירישוק","f":"אברהם","k":"בעל לקוטי רצב\"א","b":"רב בבלבירישוק, לאזדיי.","s":"ליטא"},{"i":25709,"n":"כהנא, צבי הירש מדרבן","b":"רב בדרבן.","s":"וונדר-גליציה ח\"ג"},{"i":25710,"n":"כהנא, צבי הירש מטארפא","f":"נחמן כהנא","b":"רב בטארפא","s":"אוצר הרבנים 17314"},{"i":25711,"n":"כהנא, צבי הירש מספינקא","f":"נחמן-ארחות חיים","bt":"תרמד","dt":"תשד","b":"חתן ר ברוך רובין מבריזדאוויץ האדמור מקולומיאה. רב בספינקא-תרנט על מקום אביו. נספה בשואה. בניו: ר נחמן, ר יוסף עלו לארץ.","s":"אוצר הרבנים 17315; טרנסילבניה; הונגריה"},{"i":25712,"n":"כהנא, צבי הירש מקלוואריה","f":"פנחס חיים","b":"דיין בקלוואריה, חתם-תקצז עם הראב\"ד ר אריה ליב ברוידא, ועם ר אלתר בן יעקב ור משה בן יהודה.","s":"מתוך קטלוג"},{"i":25713,"n":"כהנא, צבי מסטרימטרה","f":"ישעיה מפטריווה","bt":"תרסד","bp":"כפר פטריווה-מארמארוש","dt":"תשה - כח טבת","dp":"אושוויץ","b":"מצאצאי בעל \"קונטרס הספיקות\" ר לוי יצחק מברדיטושב ועוד. תלמיד בעל \"קרן לדוד\" ור מנחם מנדל הגר בישיבת אויבר-ווישיווה. חתן הנגיד ר צבי יהודה באש מסטרימטרה. רב בסטרימטרה על מקום ר משה קיזלניק שער לריזאווליה, והקים שם ישיבת \"בית יעקב\". נספה בשואה. רוב כתביו אבדו וחלקם אצל חתנו ר חיים מאיר לוסטיג מניו יורק. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח.","s":"טרנסילבניה; אוצר כתבי עת-לוין"},{"i":25714,"n":"כהנא, צבי מסיגט","f":"נחמן","k":"בעל אוצר יהודה-תרצא","b":"נכד בעל \"קונטרס הספיקות\". מחכמי סיגט וביבליוגרף. היה ספרן אצל ר משה יהודה דוידוביץ. חיבר \"אוצר יהודה\" רשימת הספרים של ר משה יהודה דוידוביץ מסיגט - כ-1870 ספרים. ?? לא באוצר - מופיע המחבר כבעל הספרים ולא הספרן ??","s":"טרנסילבניה"},{"i":25715,"n":"כהנא, צבי מספינקא לוס אנגלס","f":"מרדכי בן נחמן","k":"אדמור מספינקא לוס אנ","bt":"תרפג","b":"נינו של ר יוסף מאיר וייס מספינקא. חתן ר קלונימוס קלמן ליבמן מפולין. אדמור מבנדיקוביץ בלוס אנגלס, עבר לניו יורק.","s":"אלפסי"},{"i":25716,"n":"כהנא, קלמן","f":"בנימין זאב","bt":"תרע","bp":"ברודי","dt":"ה'תשמא 1981","b":"בעל תואר דוקטור מאוניברסיטת ברלין ווירצבורג. חתן ר ברוך קונשטט. ר\"מ בישיבת פולדא, עלה לארץ-תרצח ושימש כרב בקיבוץ חפץ חיים.","s":"וונדר-גליציה ח\"ג; היברובוקס","bk":[["חקר ועיון",""],["טהרת בת ישראל",""],["סדר תנאים ואמוראים",""],["שנת השבע",""]]},{"i":25717,"n":"כהנא, שלום שכנא כץ מקראקא","f":"אהרן מנחם כץ מקראקא","dt":"תמה - ז-יז סיון","dp":"קראקא","b":"מצאצאי ר יוסף כץ בעל \"שארית יוסף\". אביו נקרא \"ר מנדל ר זלמן חזנש\". חתן ר יהושע בן יוסף מקראקא בעל \"פני יהושע\" (ובאוצר הרבנים - חתן המגיני שלמה). מגדולי חכמי דורו, גביר, מרביץ תורה, מנהיג בקראקא. בניו ר שמואל כהנא מדובנא, ר יהושע הכהן מקראקא, ר אברהם כהנא מברוד ואוסטרהא, ר אריה ליב מזרכניץ, ר מרדכי משידלוב, ר ישראל מליזנסק. חתניו - ר מנחם רפפורט, ר נתן פייטל, ר אברהם עברל זלצבורג. אחיו: ר תנחום מקראקא, ר משה מקראקא.","s":"אוצר הרבנים 18268; אוסטרהא רסא; אהלי שם; שם הגדולים השלישי; בובר-לבוב; צונץ-קראקא"},{"i":25718,"n":"כהנא, שלום שכנא מהורדנקא","f":"אריה ליב כהנא","b":"רב בהורדנקא-תק. בניו: ר משה מנחם מנדל מזלוויץ, ר אהרן מזלוויץ, ר אברהם אריה ליב מברדיטשוב בעל \"אור הנערב\".","s":"אוצר הרבנים 18273; שם הגדולים השלישי"},{"i":25719,"n":"כהנא, שלמה דוד מירושלים","f":"בן ציון כהנא","bt":"תרכט","dt":"תשיד - כז כסלו","b":"חתן ר שמואל זנויל קלפפיש. חבר בועד הרבנים בוארשא-תרנה, עלה לירושלים-תש, רב בעיר העתיקה. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"בית הכנסת\" - תל אביב תשו, \"מוריה\" - ירושלים תשג, \"הפוסק\" - תל אביב תש-תשיד.","s":"אוצר הרבנים 18707; אוצר כתבי עת-לוין"},{"i":25720,"n":"כהנא, שלמה דוד מפומורן","b":"רב בפומורן.","s":"וונדר-גליציה ח\"ג"},{"i":25721,"n":"כהנא, שלמה זלמן מאוסטרהא","f":"אברהם אריה-אור הנערב","k":"בעל דברי שלמה","dt":"תריב - יז אלול","dp":"אוסטרהא","b":"נכד ר שלום שכנא הכהן מקראקא. חתן ר אריה ליבוש אשכנזי-חתנו של הגביר ר אברהם אבלי מאוסטרהא. מחכמי אוסטרהא ומלמד תורה ומחבר הח\"ק-תקסה. נהג בחסידות ובפרישות (בפסח לא אכל מצה מלבד מצת החובה - מחשש חמץ). הו\"ל ספר אביו \"אור הנערב\". היה מחלוקת כנגדו מצד אנשים שלא רצה לכבדם מהיותו איש אמת.","s":"אוצר הרבנים 18766; אוסטרהא רסא"},{"i":25722,"n":"כהנא, שלמה מזולקוא","b":"מחכמי זולקוא, חתם-תעו בזולקוא שלא יהיו קרובי הרב בתוך מנהיגי הקהל.","s":"בובר-זולקוא"},{"i":25723,"n":"כהנא, שלמה מלובלין ובודון","b":"רב בבודון-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":25724,"n":"כהנא, שלמה מסיגט","b":"שו\"ב בסיגט.","s":"ברוין-אנשי מופת"},{"i":25725,"n":"כהנא, שמואל דוד מוארשא","b":"פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו.","s":"אוצר כתבי עת-לוין"},{"i":25726,"n":"כהנא, שמואל זנויל ממונקטש","f":"יהודה יעקב","k":"בעל זכרון שמואל","dt":"תרעה - כז ניסן","b":"דומ\"צ במונקאטש-תרסז וראש ישיבה. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו.","s":"אוצר הרבנים 19535; אהלי שם; אוצר כתבי עת-לוין; ברוין-אנשי מופת"},{"i":25727,"n":"כהנא, שמואל זנויל מסיגט","bp":"מאקאווא","b":"תלמיד ר מרדכי בנט. מגדולי סיגעט-תר\"כ. חתן בעל \"קונטרס הספיקות\". בנו - ר יהודה כץ-חתנו של ר יחזקאל פנט מקרלסבורג, חתנו - ר יהודה מודרן.","s":"אוצר הרבנים 19536; טרנסילבניה; גרינוולד-סלובקיה והונגריה"},{"i":25728,"n":"כהנא, שמואל מדובנא","f":"שלום שכנא כץ מקרקא","dp":"תעט-פט - כה סיון","b":"מצאצאי ר יוסף כץ בעל שארית יוסף, ונכד ר אהרן מנחם-חתנו של הפני יהושע. ממנהיגי ועד ארבע ארצות-תנג, רב בניישטט, דובנא-תסט, עבר לברודי. הסכים על \"פני אריה זוטא\"-וילמשדורף תף. אבי משפחת כהנא בדובנא בנו - ר ישראל מליזנסק. (יש אומרים שבנו גם ר אברהם כהנא מאוסטרהא, אחרים אומרים שהיה אחיו). חתנו ר מנליש מקראקא ודובנא.","s":"אוצר הרבנים 19210; אוסטרהא מא; אהלי שם; שם הגדולים השלישי; ברוין-אנשי מופת"},{"i":25729,"n":"כהנא, שמחה מזאשקוב","f":"שמואל","k":"בעל שלמי שמחה","bt":"תרלח","b":"נכד ר חיים רפפורט, ונכד ר אברהם כהנא-חתנו של ר שאול מאמשטרדם. רב בזשקוב-פלך קיוב-תרנט. נסמך מאת: ר\"מ לאקשובקא, ר חזקיה מדיני, רא\"י אבלסון מאודסה. חיבר שו\"ת בשם \"שלמי שמחה\" - בכת\"י.","s":"אוצר הרבנים 19714; אהלי שם"},{"i":25730,"n":"כהנא, שמחה מקאטירבארג","f":"אברהם מוישניויץ","b":"רב בקטיבורג(=קאטירבארד)-ווהלין-תקץ. בנו - ר שמואל מלכוביץ. ונכדו ר שמחה בורשטין מפראנפיל.","s":"אוצר הרבנים 19713; אהלי שם"},{"i":25731,"n":"כהנא, שמעון אלעזר מירושלים","b":"מראשי הכולל בירושלים-תרן.","s":"מתוך קטלוג"},{"i":25732,"n":"כהנא, שרגא פייב ממארגרטן","f":"יוסף אלימלך מאונגואר","k":"בעל דברי חן","bt":"תרנב","dt":"תרעט- יז ניסן","b":"תלמיד ר יהודה גרינוולד בסטמר. בגיל 13 פרסם חדושי תורה ב\"נטעי בחורים\" ובכתבי עת שונים. חתן ר שמואל זלמן וינברגר ממארגרטן וכיהן כרב אצלו במארגרטן, רסלביץ(=ראסנאויץ), זשאדאני. נסמך מאת: ר אברהם יצחק גליק בעל \"באר יצחק\", ר מרדכי פריד ממארטינסברג בעל \"ברוך מרדכי\". נזכר בחדושי מהרי\"א לאביו - ירושלים תשכט. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. חיבר גם \"דברי שרגא\", ועוד.","s":"טרנסילבניה; אוצר כתבי עת-לוין; החת\"ס ותלמידיו; אהלי שם"},{"i":25733,"n":"כהנא-בלומנפלד, יוסף מטוקום","f":"זאב וולף","b":"רבה הראשון של טוקום-תקסא, בהסכמת ר אבלי פוסוואלר.","s":"אובצינסקי-קורלנד"},{"i":25734,"n":"כהנא-פרנקל, שמואל זנויל מבודפש","f":"יחיאל מיכל מסיגט","bt":"תרן","dt":"תשל - יח אב","b":"תלמיד הדעת סופר. חתן ר אברהם מ\"ש-פרנקל מבודפשט נשיא הלשכה האורטודוכסית בהונגריה, רב על מקום חותנו-תרצז ניצל מהשואה, ואחריה המשיך כרב בבודפשט. עבר לניו יורק.","s":"החת\"ס ותלמידיו"},{"i":25735,"n":"כהנא-שפירא, אברהם אשר שמואל","f":"ישראל איסר מווידיסלב","k":"ראש\"י מזלין","bt":"תקמט","dt":"תריב - טו תמוז","b":"רב בזלין, שיניבה, עלה לירושלים-תרו, וקיבל מכתב המלצה מר צבי הירש מרימנוב.","s":"וונדר-גליציה ח\"ה; אלפסי"},{"i":25736,"n":"כהנא-שפירא, אברהם יצחק","f":"רפאל יעקב מטורנא","b":"מחכמי ירושלים. חתן ר חיים רוטנברג (נכד אחיו של חדושי הרי\"מ), ונכדת הגר\"א, ובזיוו\"ש חתן ר משה שטיין.","s":"וונדר-גליציה ח\"ה"},{"i":25737,"n":"כהנא-שפירא, אברהם מירושלים","bp":"ירושלים","b":"תלמיד ישיבת חברון בירושלים. ראש ישיבת \"מרכז הרב\" בירושלים. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר כתבי עת-לוין"},{"i":25738,"n":"כהנא-שפירא, אהרן שמואל","f":"עזריאל למל","b":"רב בשברשין-תפ\"ב","s":"אוצר הרבנים 1891"},{"i":25739,"n":"כהנא-שפירא, אליעזר נתן מירושלי","b":"חתם-תרכב עם ראשי הכוללות בירושלים על כתב שליחות ר נתן נטע נאטקין.","s":"מתוך קטלוג"},{"i":25740,"n":"כהנא-שפירא, אלעזר מירושלים","f":"אברהם אשר שמואל","bt":"תקצו","bp":"קראקא","dt":"תרעח","b":"עלה לירושלים-תרז עם אביו. ראש כולל גליציה והתעודות שהוציא עבור הקונסוליה האוסטרית הוכרו כרשמיות. חתם בתרכ\"ה אחרי ר מנדל צימטבוים ממישלניץ (שהיה נציגו של ר עזריאל הילדסהיימר). כיהן בועד השחיטה של המהרי\"ל דיסקין כנציג החסידים. בנו ר פנחס עסקן ומראשי כולל גליציה - גורש בתרעז לאנטוליה כנתין זר.","s":"וונדר-גליציה ח\"ה"},{"i":25741,"n":"כהנא-שפירא, דוד מקראקא","f":"מרדכי צבי מקראקא","bt":"תרסא","bp":"בזיסק","dt":"תשלא","b":"תלמיד ה\"אבני נזר\". חתן ר חיים יהושע גוטשטכר מוארשא ועבר לשם, והיה רב בגטו, ניצל מהשואה. רב בפיורדא כ-25 שנה. עלה לארץ-תשלא.","s":"וונדר-גליציה ח\"ה"},{"i":25742,"n":"כהנא-שפירא, חיים מקוזניצא","f":"שלמה זלמן סנדר ממאלץ","k":"בעל כרם חיים","bt":"תרלד","b":"נינו של ר חיים מוולוזין. חתן ר שמואל משה גוריצקי מקאפציווא. ר\"מ בקיבוץ בחורים במינסק, רב בקוזניצא-פלך גרודנא-תרסז. חיבר \"כרם חיים\" - בכת\"י.","s":"אוצר הרבנים 6195; ליטא; אהלי שם"},{"i":25743,"n":"כהנא-שפירא, יהודה מקובנא","f":"שלמה זלמן סנדר ממאלץ","k":"בעל וזאת ליהודה","bt":"תרלח","dt":"תרף - כ אדר","b":"מצאצאי ר חיים מוולוזין. רב בקובנא-תרף. חתן ר מאיר אטלס משאוויל, גיסיו - ר אלחנן וסרמן, ר חיים עוזר גרודזנסקי. חיבר \"וזאת ליהודה\" ונדפס בסוף \"דבר אברהם\" לאחיו. נפטר ללא ילדים.","s":"אוצר הרבנים 7116; ליטא; אהלי שם"},{"i":25744,"n":"כהנא-שפירא, יהושע יוסף מקראקא","f":"אברהם אשר שמואל","bt":"תקעד - בערך","dt":"תרעד","s":"וונדר-גליציה ח\"ה"},{"i":25745,"n":"כהנא-שפירא, יחיאל מיכל מרדומיש","f":"משה","k":"בעל דעת נבונים","bt":"תרך","dt":"תרצה","b":"תלמיד ר נפתלי צבי מטורנא. מחשובי חסידי דזיקוב. חתן ר מרדכי הורביץ ממעליץ וישב אצלו. רב ברדומישל-תרנא, עבר למעליץ. חיבר \"דעת נבונים\" ירוסלב תרסח. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"הירדן\" - רישא תרץ.","s":"וונדר-גליציה ח\"ה; אוצר כתבי עת-לוין"},{"i":25746,"n":"כהנא-שפירא, יעקב","f":"משה כהנא שפירא","b":"רב-שנת תר\"ל","s":"אוצר הרבנים 9970"},{"i":25747,"n":"כהנא-שפירא, יעקב","f":"שלמה זלמן סנדר ממאלץ","k":"בעל נאות יעקב","b":"מצאצאי ר חיים מוולוזין. חתן הגביר ר אברהם יגל מפיעסק. רב-שנת תרף.","s":"אוצר הרבנים 9971; ליטא; אהלי שם"},{"i":25748,"n":"כהנא-שפירא, יעקב אליהו ז'ילנר","f":"אברהם אשר שמואל","b":"חסיד ר אליעזר מנחם מנדל מללוב, חתם עם רבו על שטר בירושלים-(בין תרל לתרם). חתנו ר שלום גלרנטר מו\"ל \"כור לזהב\"-תרמה.","s":"וונדר-גליציה ח\"ה"},{"i":25749,"n":"כהנא-שפירא, יעקב מאיר","f":"צבי אשר מירושלים","bt":"תרנא","bp":"ירושלים","dt":"תשלא","b":"עבר לארה\"ב-תרפד וכיהן כראש ישיבת \"משכן ישראל\" בפילדלפיה, יסד את ישיבת \"יבנה\" בניו יורק עם אחיו ר נחום יצחק. חזר לירושלים-תשיא והקים את מכון מהרש\"ל עם בנו ר מנחם נחום. חתן ר אליעזר אריה ליבוש כהנא בעל דפוס בירושלים.","s":"וונדר-גליציה ח\"ה"},{"i":25750,"n":"כהנא-שפירא, יעקב מברודי ולבוב","f":"יצחק","b":"מחכמי ברודי, לבוב. חתנו - ר מרדכי הלוי בן יצחק מחעלמא. נזכר בהקדמת \"גבורת שאול\" לבן אחותו - ר שאול בן משה מלאמז.","s":"בובר-לבוב"},{"i":25751,"n":"כהנא-שפירא, יעקב מטיטשין","f":"דוד","k":"בעל אהל יעקב","b":"רב וראש ישיבה בטיטשין-תס. נכד ר יצחק הכהן אב\"ד קראקא. חיבר \"אוהל יעקב\" פפד\"א תעט - הובא לדפוס ע\"י בניו: ר משה מעשיל מגיד מהרודישטש ור יצחק מטרעפולי (ליד בריסק).","s":"וונדר-גליציה ח\"ה; איטליה גירונדי-י קכז; אוצר הרבנים 9967,9687; פין-כנסת ישראל"},{"i":25752,"n":"כהנא-שפירא, יעקב ממאלטש","b":"רב במאלטש-תרנ\"ח","s":"אוצר הרבנים 9972"},{"i":25753,"n":"כהנא-שפירא, ישעיה מאיר","f":"יוסף בירך","k":"בעל חקירת ראשית","bt":"תקפח או תקף","bp":"ממל","dt":"תרמז","dp":"צ'ורטקוב","b":"עבר עם הוריו לסקול. חתן הגביר ר חיים אפיסדורף מצשינוב. מקורב לר מאיר מינץ, והיה מבאי ביתו של השו\"מ. עסק במסחר ביהלומים, ופרסם בכתבי עת, מיודד עם ר בנימין זאב וילר מירוסלב שישב בצשינוב אצל חותנו. רב בצורטקוב כיהן כמשנה לרב בצ'ורטקוב, ונאלץ להתפטר בגלל פעילותו להפצת השכלה. יצג זרם מתון בתנועת ההשכלה שניסה לשמור על המסורת ולהתאים את היהדות לזמן החדש (והיה מחלוקת עם החסידים שמינו את ר ברוך מאיר פריש, ועוד מחלוקת בין חסידי ויזניץ וסטרטין) כשהגיע האדמור ר דוד משה פרידמן - פוטר מתפקידו - אך נשאר בצורטקוב ופעל כרב בשאר הקהלה. בתשובה שכתב בנושא קו התאריך פסק כפי שפסק לימים החזון איש. למד באוני' והוסמך לרבנות. פרסם מאמרים ב\"המגיד\", \"הלבנון\", \"העברי\", ועוד. תומך ב\"חיבת ציון\", חבר ב\"אליאנס\", ובחברת מפיצי השכלה\". חיבר \"חקירת ראשית\" ליק תרלב, ספר זכרון - ובו מתנגד לתיקונים בדת ומסביר שהרבנים הם ביטוי לרצון העם לשמור על נכסי הרוח שלו. בנו דוד - רופא וסופר בדוינסק ונכדתו שרה משוררת עברית שנתפרסמה בשירה \"אל טל ואל מטר\".","s":"וונדר-גליציה ח\"ה; ליטא"},{"i":25754,"n":"כהנא-שפירא, מנחם נחום","f":"יעקב מאיר","b":"מיסד מכון מהרש\"ל עם אביו. ועומד בראשו. חתן ר דודו שלמה זלמן. עורך אוצר השו\"ת א\"י.","s":"וונדר-גליציה ח\"ה"},{"i":25755,"n":"כהנא-שפירא, מרדכי צבי מקראקא*","f":"משה נתן מקשונז","bt":"תרמ","b":"רב בקשונז על מקום אביו?, ברזיסק-פלך קיעלץ-תרנו. דיין בקראקא עם ר משה שמואל בלייכר ור ניסן כץ שנידר.","s":"וונדר-גליציה ח\"ה; אוצר הרבנים 14246; אהלי שם"},{"i":25756,"n":"כהנא-שפירא, משה אבלי הכהן","f":"אברהם אשר שמואל","b":"רב ברוהטין - תשובה אליו ב\"בית יצחק\".","s":"וונדר-גליציה ח\"ה"},{"i":25757,"n":"כהנא-שפירא, משה הכהן מנישוועז","f":"יצחק?","k":"ר מושקה ר איציקס","b":"נכד-אבי אמו ר חיים מוולוזין. רב-שנת תר. בנו - ר יעקב מוולוזין ונכדו ר זלמן סנדר ראש ישיבת \"ענף עץ חיים\" במאלטש. (באוצר ובחכמי מינסק-איזנשטט - חתן ר חיים מוולוזין בזיוו\"ש - נשא את אלמנת ר יוסף סולוביציק).","s":"אוצר הרבנים 15217; ליטא; אהלי שם; ליפמן-קובנא"},{"i":25758,"n":"כהנא-שפירא, משה נתן מקשונז","k":"בעל שמן למאור","bt":"תריב","dt":"תרצו","b":"תלמיד ר נחום זאב בעל 'אגודת אזוב'. חתן הגביר ר יעקב הנדלסמן מראדום ועבר לשם ולמד עם גיסו ר יואב יהושע וינגרטן בעל חלקת יואב. מלמד תורה בראדום ובמייכוב, לאחר שאיבד את רכושו רב בקשונז(=קשוינז)-פלך קיעלץ-תרס ובנו ר מרדכי צבי על מקומו אחריו, נתקבל לרבנות בלודז' אך סירב. מקורב לאדמור מסוכטשוב בעל אבני נזר, ובנו בעל שם משמואל היה חתנו בזיוו\"ש, חתנו גם - ר אליעזר צבי לונטל מטאלדש. מכתביו נדפס 'שמן למאור'. רוב כתביו אבדו בשואה.","s":"אוצר הרבנים 15604"},{"i":25759,"n":"כהנא-שפירא, משה שלמה","f":"פנחס","k":"ירושלים","bp":"ירושלים","dp":"תרץ - ב אדר","b":"סופר ועסקן צבור בירושלים."},{"i":25760,"n":"כהנא-שפירא, נחום יצחק מירושלים","f":"צבי אשר מירושלים","k":"בעל ילקוט סיני","bt":"תרמב","bp":"ירושלים","dt":"תשכג","b":"למד בישיבות ירושלים, חבר של רי\"מ חרל\"פ ונסעו יחד ליפו למשך 20 שנה ללמוד אצל הראי\"ה קוק. נסע לר חיים מבריסק-תרעא, נשלח ע\"י החפץ חיים לירושלים לחיזוק הישיבות. בארה\"ב-תרעו, וכיהן כרב בסטמפורד, הקים ישיבת יבנה בניו יורק עם אחיו ר יעקב מאיר. שב לירושלים-תשטו ועמד בראש כולל מהרש\"ל (ר\"ת רבלין שפירא לעווי) שהקים אחיו. חתן ר יהושע זאב זיסנויין. חיבר \"ילקוט סיני\" ירושלים תשכג.","s":"וונדר-גליציה ח\"ה; אוצר הרבנים 15901"},{"i":25761,"n":"כהנא-שפירא, עזריה למל","f":"יוסף הכהן","b":"רב-שנת ת\"נ","s":"אוצר הרבנים 16729"},{"i":25762,"n":"כהנא-שפירא, פנחס","f":"אלעזר מירושלים","bt":"תרכה","dt":"תרעח","dp":"וינה","b":"מראשי כולל גליציה לצד אביו. גורש כנתין זר בתרעז לאנטוליה.","s":"וונדר-גליציה ח\"ה"},{"i":25763,"n":"כהנא-שפירא, צבי אשר מירושלים","f":"שמואל יהודה מקראקא","k":"ריצב\"א - התורה והמצו","bt":"תריח - יב","bp":"קראקא","dt":"תרצח - יז שבט","dp":"ירושלים","b":"תלמיד רח\"נ דמביצר. עלה לירושלים-תרלג, מקורב לר מאיר אוירבך מקליש בירושלים. רב בשכונת הבוכרים, ר\"מ וראש ישיבה בכמה ישיבות. חתן ר שלמה זלמן לוי ממיסדי \"מאה שערים\". בשליחות-תרנז. חיבר \"התורה והמצוה\" ירושלים תרעג. בשנת תרלד חתם בפולמוס החצר. נכדו ר מנחם נחום הוציא \"חבל הכסף\" והוא ספר היחס ותולדות זקנו הרצ\"א.","s":"וונדר-גליציה ח\"ה; אוצר הרבנים 17499"},{"i":25764,"n":"כהנא-שפירא, רפאל יעקב מטורנא","f":"יוסף צבי","dt":"תרסא","b":"חתן רבז\"ו לעזער מטורנא. בגללו בוטל המנהג בטורנא להדליק בחלונות ביום אידם.","s":"וונדר-גליציה ח\"ה"},{"i":25765,"n":"כהנא-שפירא, שלמה דוד","b":"תשובה אליו ב\"משיב כהלכה\"-תרא.","s":"וונדר-גליציה ח\"ה"},{"i":25766,"n":"כהנא-שפירא, שלמה הרץ מקראקא","b":"תשובה אליו ב\"שם עולם\"-תרלו.","s":"וונדר-גליציה ח\"ה"},{"i":25767,"n":"כהנא-שפירא, שלמה זלמן מירושלים","f":"צבי אשר מירושלים","bt":"תרמז","b":"חתן ר אהרן יהושע פישל זקס. בנו - ר אברהם אלקנה ראש ישיבת מרכז הרב והרב הראשי. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\".","s":"וונדר-גליציה ח\"ה; אוצר כתבי עת-לוין"},{"i":25768,"n":"כהנא-שפירא, שלמה זלמן סנדר","f":"יעקב בן משה","k":"בעל מסגרת זהב","bt":"תריא","bp":"קוברין","dt":"תרפג - כט שבט","dp":"ירושלים","b":"נכד ר משה כהנא-שפירא(=מושקה איציקס)-נכד ר חיים מוולוזין. תלמיד ישיבת וולוזין אצל ר יוסף דב סולובציק והתחנך יחד עם ר חיים סולוביציק. מחכמי קוברין, רב במאלטש-פלך גרודנא ויסד שם את ישיבת \"ענף עץ חיים\". עבר לקריניק-תרסג עם הישיבה. עלה לירושלים-תרפג וכיהן כנשיא אגו\"י. בניו: ר יעקב בעל נאות יעקב, ר אברהם דובער - אב\"ד קובנא-חתן הגדול ממינסק, ר חיים - רב בקוזניצה, ר יהודה-חתן ר מאיר אטלס. חיבר \"מסגרת זהב\" בכתב יד. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט, \"תבונה\" - קובנא תרפא. היה בידידות עם הגדול ממינסק (לימים מחותנו) - כאשר בצעירותו נסע לסעלץ במיוחד כדי לפוגשו. בניו: ר יעקב, ר אברהם דובער מסמאלעויטש-חתן ה\"גדול ממינסק\", ר חיים מקיזניצא, ר יהודה. חתנו - ר יעקב בלידשטין מחארשין-בן גיסו ר ברוך יוסף מאיליא.","s":"גליס; אוצר הרבנים 18821; ליטא; אוצר כתבי עת-לוין; הגדול ממינסק; אהלי שם","bk":[["חידושי הגרז\"ס",""]]},{"i":25769,"n":"כהנוב אלעזר בן אורי מאיר","bt":"1917","dt":"ה'תשסב 2002","s":"היברובוקס","bk":[["זכרון בצלאל",""],["פרי הארץ",""],["תורת השביעית",""]]},{"i":25770,"n":"כהנוב, אורי מאיר מארה\"ב","k":"בעל פרי הארץ-תשיט","bt":"תרמג","bp":"רוסיה","dt":"תשך - ב שבט","dp":"ניו יורק - ירושלים","b":"ברח מרוסיה בגלל הגיוס לצבא והגיע להונגריה. תלמיד ישיבת צעהלים, עלה לירושלים ולמד בישיבת \"תורת חיים\" וחזר להונגריה, התישב בכפר סיטשל-מארמרוש-תרע, שו\"ב ורב בסיטשל. עבר להרמאנשטדט וניהל בה ישיבה. היגר לארה\"ב-תרפד וכיהן כר\"מ בישיבת \"תורה ודעת\". פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\".","s":"טרנסילבניה; אוצר כתבי עת-לוין; היברובוקס","bk":[["משמרת הכהנים",""]]},{"i":25771,"n":"כהנוב, אליהו מירושלים","f":"פיבל","bt":"תרמג","bp":"ירושלים","b":"מנהל בית הספר \"התורה והמלאכה\" בירושלים."},{"i":25772,"n":"כהנוב, דוד הכהן מארה\"ב","f":"יהושע","bp":"באקי-פלך קיוב","b":"נכד (אבי אמו) ר משה נחום ירושלימסקי מקיעלץ. תלמיד ישיבת נוברדוק, סלובודקא, סלוצק. נסמך מאת: ר איסר זלמן מלצר, ר משה מרדכי אפשטין, ר ברוך בר ליבוביץ, ר מרדכי אריה באראשענקא מזועניגראדקא, ר פישל מאומאן. חתן ר פנחס דראזנע. רב בטולנא-תרפב, גייטין-פלך פודוליה-תרפד, היגר לארה\"ב-תרפט וכיהן כרב ור\"מ בשיקגו. חבר אגודת הרבנים באמריקה ותנועת המזרחי.","s":"אנשי שם-אמריקה"},{"i":25773,"n":"כהנוב, משה נחמיה מירושלים","f":"משלם פייבל","k":"בעל נתיבות שלום","r":"רב בחסלויטש ועוד ר\"י עץ חיים","bt":"תקעז","bp":"קוסטיוקוביה (רייסן)","dt":"תרמז - ב סיון","dp":"ירושלים","b":"ראב\"ד בפטרוביץ-תרסה, חסלביץ-רייסן(=רוסיה הלבנה) ור ליפא יו\"ט הלפרין בעל \"מלבושי יו\"ט\" על מקומו אחריו, עלה לירושלים-תרכג-ה והיה מראשי ישיבת \"עץ חיים\". חיבר \"נתיבות שלום\" קניגסברג תריט, \"אבל משה\" - הספד על מוטיפיורי - ירושלים תרמה, ועוד. פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז. (לא היה כהן)","s":"גליס; אוצר הרבנים 15592; אוצר כתבי עת-לוין; מוריה 24-ז-ט; שם הגדולים השלישי; וזה שער השמים עמוד 258, המבשר תורני גליון 230 עמוד כד","bk":[["נתיבות השלום",""],["ארץ חפץ – תרו\"מ",""],["חוקות עולם – כלאים",""],["נתיבות השלום – שו\"ע",""],["שאלו שלום ירושלים",""],["שנת השבע - שמיטה",""],["שפתי ישנים - צוואה",""]]},{"i":25774,"n":"כהנוביץ, ישראל יצחק מקנדה","b":"רב בויניפג-קנדה."},{"i":25775,"n":"כהנוביץ, צבי","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":25776,"n":"כהנמן, יוסף שלמה מפוניבז וב\"ב","f":"יהודה ליב","r":"רב וראש ישיבת פוניבז'","bt":"תרמו","bp":"קול-ליטא","dt":"תשכט - כ אלול","b":"תלמיד ישיבות ז'ידיק, פולונגיאן, טלז, נוברדוק והיה יד ימינו של בעל \"ערוך השלחן\", וסייע בהשלמת חיבורו, ורב על מקומו אחריו - ע\"פ צוואתו של הרב. עבר לראדין והתקרב לחפץ חיים. חתן ר ליב רובין מווידז, רב בווידז על מקום חותנו והקים שם ישיבה. בזמן מלחה\"ע ה-I היה בקוטלוניאן ופעל אצל הגרמנים למען היהודים שבאזור הכיבוש, ובזכות פעילותו חודש הישוב היהודי בפונוביז. רבה האחרון של פוניבז-תרעט על מקום ר יצחק יעקב רבינוביץ והקים ישיבה ומוסדות לנוער ולבנות. נבחר כציר ב\"סיים\" הליטאי, וחבר באגודת הרבנים בליטא, פעיל באגו\"י. ביקר בארץ-תרצה, עלה לארץ-תש - רוב בני משפחתו נשארו בליטא ונספו בשואה. הקים ישיבת פונוביז בבני ברק, ועוד מוסדות ליתומים לילדים ומוסדות חשובים נוספים. חידש את כינוסי \"ירחי כלה\". בנו - ר אברהם - ר\"מ בישיבה.","s":"אוצר הרבנים 8988; ליטא; במחיצתם של גדולי ישראל חלק ב' עמודים 348 - 397, מוריה קובץ ו' עמודים א - ג","bk":[["דברי הרב",""],["חי' הגאון מפוניבז' (הרב מפוניבז')",""],["חידושי הגאון מפוניבז'",""]]},{"i":25777,"n":"כהנר מיאזנא","b":"רב ביאזנה.","s":"ליטא"},{"i":25778,"n":"כואיף, אפרים","s":"ארזי הלבנון"},{"i":25779,"n":"כובשי, שלום מתימן","b":"רב בקוזיה אלמחאבשה-תימן - בתחילת המאה ה-20.","s":"ארזי הלבנון"},{"i":25780,"n":"כוגהין, יוסף מבוכרה","f":"יצחק","bt":"תרז","bp":"קוקאנד-טורקסטן","dt":"תרפד - תשרי","dp":"ירושלים","b":"עלה לירושלים פעיל צבור בעדה הבוכרית בירושלים, חזר לבוכרה והיה פעיל ציוני, חזר לארץ והתישב בחדרה.","s":"גאון-יהודי המזרח"},{"i":25781,"n":"כודיידאתיף, אבא","b":"מחכמי בוכארה, דיין-תר\"ס","s":"ארזי הלבנון"},{"i":25782,"n":"כוכבי דוד בן שמואל; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","s":"היברובוקס","bk":[["ספר הבתים",""],["ספר המכתם",""]]},{"i":25783,"n":"כוכבי, דוד","k":"בעל בית אל","b":"נזכר אצל ר מנחם די לונזנו בעל \"אור תורה\", חיבר גם \"מגדל דוד\".","s":"פין-כנסת ישראל"},{"i":25784,"n":"כוכבי, דוד מפרובנס","k":"בעל ספר הבתים","dt":"ק","b":"מגדולי חכמי פרובינצה,דיין באביניון","s":"אוצר הרבנים 4860 א'"},{"i":25785,"n":"כוכבי, מאיר","b":"מגדולי הפוסקים בצרפת-שנת ס'","s":"אוצר הרבנים 12864"},{"i":25786,"n":"כולי - משפחה","f":"יעקב","bt":"תקפ","bp":"טיטואן","dt":"תרמו","dp":"חיפה","b":"רב בטיטואן, עלה בשנת תרך והיה רב בטבריה, בשנת תרמא אב\"ד וראש ישיבה בחיפה.","s":"גליס"},{"i":25787,"n":"כולי, דוד מקושטא","b":"מגדולי חכמי קושטא-ש\"ז","s":"אוצר הרבנים 4873"},{"i":25788,"n":"כולי, יהודה מירושלים","f":"יעקב","b":"מחכמי ירושלים-תקיח, דרשן, מלומדי ישיבת \"דמשק אליעזר\".","s":"אוצר הרבנים 6973; ארזי הלבנון; פרומקין-תח\"י"},{"i":25789,"n":"כולי, יעקב מירושלים וקושטא","f":"מכיר","bt":"תמה","bp":"ירושלים","dt":"תצב - יט אב","dp":"קושטא","b":"ר' יעקב כולי הוא נכדו [בן בתו] של המהר\"ם חביב. ספרו המפורסם, \"ילקוט מעם לועז\" לא זכה לסיום על ידו, אלא נכתב רק עד אמצע פרשת תרומה, שאז נפטר. ר' יצחק ב\"ר שמריה מאגריסו המשיך בעבודת הקודש, והוציא לאור את המשך הספר, אך גם הוא לא זכה לסיימו, ונפטר בשנת ה'תקכה. אחריו הו\"ל ר' יצחק ארגואיטי את ספר דברים עד סוף פ' עקב [נפטר: ה'תקלג]. משערים, שהשלמות הספר הנ\"ל נעשו על פי כתבים שהשאיר אחריו ר' יעקב כולי, ושמחבריהם אף זכו להכירו. על ספר יהושע כתב ר' רחמים מנחם מיטראני [נפטר ה'תרכז], על מגילת אסתר ר' רפאל חייא פונטרימולי, ב\"ר חיים בנימין בעל \"פתח הדביר\" [נדפס: ה'תרכד], על מגילת רות ר' רפאל מאיר בן ויניסטי [נדפס: ה'תרמב], על שיר השירים ר' חיים יצחק שאקי [נדפס: ה'תרנט]. הספר נכתב בלאדינו [=שפת יהודי ספרד], ותורגם ללה\"ק ע\"י ר' שמואל ב\"ר חיים יוסף ירושלמי [קרויזר], שאף השלים את החיבור, על חומש דברים - פ' ראה ואילך - ועל שאר הנ\"ך. ר\"ש קרויזר נולד: ה'תרפג, נפטר: ה'תשנז.","s":"גליס; אוצר הרבנים 9688; פין-כנסת ישראל; רוזניס-תורכיה-ה; שבת בשבתו גליון 1436; יומא דהילולא","bk":[["מעם לועז – בראשית ושמות",""],["מעם לועז, תצ\"ב, קבור בטורקיה",""],["ילקוט מעם לועז",""]],"e":"תמ\"ט-תצ\"ב"},{"i":25790,"n":"כולי, מכיר מירושלים","bt":"שצו","bp":"קנדיא (כרתים)","dt":"תפח - כט כסלו","dp":"צפת","b":"עלה מצרפת? לירושלים-תמח ונשא את בתו של ר משה בן חביב, ואחר פטירתה את בתו של ר אריה יהודה ליב כץ בעל \"שער אפרים\" בשנת תנט. בנו - ר יעקב בעל \"מעם לועז\".","s":"גליס; אוצר הרבנים 14140; גאון-יהודי המזרח; רוזניס-תורכיה-ה"},{"i":25791,"n":"כולי, שבתי","b":"מחכמי איטליה","s":"אוצר הרבנים 18069"},{"i":25792,"n":"כולי-קזאני, ישראל יעקב","f":"שבתי כולי","b":"רופא מחכמי קנדיא(=כרתים). נזכר בתקנה-שלז על איסור על נשים לצאת אחר הנפטר.","s":"אוצר הרבנים 12235; גאון-יהודי המזרח"},{"i":25793,"n":"כומיטיאני, מרדכי","f":"אליעזר","k":"הרמ\"ך-בעל כתר תורה","bt":"קפ","bp":"קושטא","dt":"רן","b":"תלמיד ר חנוך סאפורתא. רב באדרינופול. היה במחלוקת עם ר שבתי בן מלכיאת הכהן אודות ספרי האבן עזרא.","s":"ארזי הלבנון; אוצר הרבנים 13873; פין-כנסת ישראל"},{"i":25794,"n":"כונסארי, אהרן","b":"מחכמי יאזד(פרס)","s":"ארזי הלבנון"},{"i":25795,"n":"כורייף, אברהם יהודה מאיטליה","b":"רב באיטליה. מכתב ממנו-תקפו אל ר עזרא דילויכיו מלוגו-איטליה.","s":"מתוך קטלוג"},{"i":25796,"n":"כושפו, אהרן מקושטא","b":"רב בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא.","s":"רוזניס-תורכיה-א"},{"i":25797,"n":"כחלון, חואתו חיים","b":"מחכמי טריפולי בלוב","s":"ארזי הלבנון"},{"i":25798,"n":"כחלון, יוסף מלוב","bt":"תרם","dt":"תשי - בערך","b":"רב בזנזור-לוב-תרף עד תשה.","s":"מלכי חי\"ל-מרציאנו"},{"i":25799,"n":"כחלון, יעקב מלוב","f":"סעייד","bt":"תרסז","bp":"כפר זליתן-לוב","dt":"תשנא","dp":"ישראל","b":"רב בכפר זליתן-לוב-תרפג (שם נולד) עד תש, עלה לארץ-תשי וכיהן כרב במושב עלמא.","s":"מלכי חי\"ל-מרציאנו"},{"i":25800,"n":"כי\"ח - כל ישראל חברים - חברה","s":"טולדנו-נר המערב"},{"i":25801,"n":"כייאט, אברהם","dt":"תקמו","b":"דיין בתונס","s":"ארזי הלבנון"},{"i":25802,"n":"כייאט, נסים מג'רבה","b":"רב בג'רבא - בשנות הת'. תקנות שלו עם חברו ר מיכאל וזאן נזכרו ב\"ישיב משה\" לר משה שתרוג. תלמידיו ר אהרן פרץ בעל \"בגדי אהרן\", ור יצחק חדאד בעל \"תולדות יצחק\" המזכירו בספרו.","s":"ארזי הלבנון"},{"i":25803,"n":"כלאב, י' ד' מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא.","s":"אוצר כתבי עת-לוין"},{"i":25804,"n":"כלאב, יעקב","dt":"תשיט - ג טבת","b":"ר\"מ בירושלים","s":"אוצר הרבנים 9689"},{"i":25805,"n":"כלאב, ישראל משה","dt":"תשג","b":"ר\"מ בריגא","s":"אוצר הרבנים 12279"},{"i":25806,"n":"כלאף, אברהם","b":"מקובל, מרבני תונס","s":"ארזי הלבנון"},{"i":25807,"n":"כלב בן חצרון","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":25808,"n":"כלב מארטא-יוון","f":"יוחנן","b":"רב בארטא בזמן ר יהודה מינץ. דודו ורבו של ר בעל \"בנימין זאב\".","s":"ארזי הלבנון; פין-כנסת ישראל"},{"i":25809,"n":"כלב מיוון","f":"שלמה","b":"פייטן מחכמי יוון-רפב.","s":"ארזי הלבנון"},{"i":25810,"n":"כלב מירקדו מאיר","f":"יוסף","bp":"רודוס","dt":"תרנו - ו ניסן","dp":"ירושלים","b":"אביו של הראשון לציון ר יעקב מאיר, וגיסו של ר יעקב פאפולה מירושלים. חתנו - ר מאיר קשטיל.","s":"גאון-יהודי המזרח; אוצר הרבנים 12431; ארזי הלבנון"},{"i":25811,"n":"כלב ממצרים","b":"רב במצרים בזמן הרמבם, השיב על השגות ר שמשון משאנץ על הרמב\"ם.","s":"ארזי הלבנון"},{"i":25812,"n":"כלב מקושטא","f":"שמואל","b":"דיין בקושטא-שנות ה-ת' אצל ר יום טוב ן יקר, חתום על כתב המינוי למשלחת שמונתה לחקור אודות נתן העזתי.","s":"רוזניס-תורכיה-ד"},{"i":25813,"n":"כלב שמואל מקושטא","b":"מחכמי קושטא. נזכר ב\"תורת אמת\" לר אהרן ששון.","s":"ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":25814,"n":"כלב, אברהם יעקב","b":"רב בפרייל-תר\"ס","s":"אוצר הרבנים 1193"},{"i":25815,"n":"כלב, אברהם מאנגורה","b":"מחכמי אנגורה(=אנקרה?)-ש',","s":"רוזניס-תורכיה-א"},{"i":25816,"n":"כלב, יוסף מהאזינפוט","f":"משה","b":"רב בהאזינפוט(=האזנפוט).","s":"אובצינסקי-קורלנד"},{"i":25817,"n":"כלב, יעקב","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז.","s":"אוצר כתבי עת-לוין"},{"i":25818,"n":"כלבו, אברהם מברזענין וזוגורבא","f":"משה יחיאל","k":"בעל המחדד","bt":"תרלו","b":"תלמיד זקנו-אב\"ד לונטשיץ. חתן ר שלמה אוירבך מקאליש בעל \"אמרי בינה\". רב בבורזענין-פלך קאליש-תרסג. נסמך מאת: ר ישראל יהושע מקוטנא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד.","s":"אוצר הרבנים 500; אוצר כתבי עת-לוין; אהלי שם"},{"i":25819,"n":"כלבו, דוד ממצרים","b":"רב באלכסנדריה-שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":25820,"n":"כלבו, יהושע יוסף","f":"יעקב מנחם","k":"בעל בנין אריאל","b":"חיבר ספר על ירושלים ובית המקדש בשלשה חלקים."},{"i":25821,"n":"כלבו, מאיר","k":"בעל פירוש לתורה","b":"חיבר פירוש לתורה בכת\"י (והיה בידי ר משה רפאל די אגילאר), מוזכר ב\"שפתי ישנים\".","s":"איטליה גירונדי-מ קא"},{"i":25822,"n":"כלבו, עמנואל משלוניקי","f":"רפאל משלוניקי","dt":"תקם-ס - ב אלול","dp":"שלוניקי","b":"למד רפואה בפדובה-תפד. רופא ותלמיד חכם. ישב בשלוניקי-תצג ונשא ונתן בהלכה עם ר משה אמריליו, הגיע עם אביו לליוורנו. חיבר פסקים קינות ושירים - ומהם ב\"קול עוגב\" לר אברהם ברוך פיפרנו. היה משורר חשוב יחד עם חברו ר אברהם יצחק קאשטילו (והיה מעין תחרות ביניהם).","s":"איטליה גירונדי-ע ז; ארזי הלבנון; זכרון שלוניקי-68,80,92; רוזניס-תורכיה-ה,ו"},{"i":25823,"n":"כלבו, רפאל משלוניקי","b":"מחכמי שלוניקי, התישב בליוורנו ולימד תורה. מוזכר ב\"קול עוגב\"","s":"איטליה גירונדי-ר ד; ארזי הלבנון"},{"i":25824,"n":"כלבזון, יהודה אידל מדובייק","b":"חזן בדובייק-ליטא.","s":"ליטא"},{"i":25825,"n":"כליף, שמואל מדמשק","b":"דיין בדמשק-שנג אצל ר יעקב אבולעפיה.","s":"רוזניס-תורכיה-ג"},{"i":25826,"n":"כליפא הכהן מג'רבה","k":"בעל מענה רך","b":"נכד הראב\"ד של ג'רבא ר רחמים הכהן. חיבר \"מענה רך\" ונדפס בסוף \"שלום דוד\" ג'רבא תרעה. ?? לא באוצר ??","s":"ארזי הלבנון"},{"i":25827,"n":"כליפא הכהן מהדיג'ת-ג'רבה","k":"בעל שמחה וששון","dt":"תרצב - ה תמוז","b":"רב וראש ישיבה בהדיג'ת-ג'רבא. חיבר עוד \"מדרש שלמה\", \"שם הגדולים\". בנו ר יהודה מניני הכהן בעל \"קול יהודה\".","s":"ארזי הלבנון"},{"i":25828,"n":"כליפא הכהן מתונס","k":"בעל שפתי רננות","bt":"תקפב","bp":"תונס","b":"רב בתונס.","s":"אוצר הרבנים 12437; אהלי שם"},{"i":25829,"n":"כליפא ן, דוד מאלגיר","f":"מכלוף","k":"בעל דרכי דוד","bt":"תרסו","dt":"תשנג","dp":"ירושלים","b":"תלמיד ר אליהו בן גיגי מסעידא. רב בתימושנת-אלגיר-תשח, מאסי-(ליד פאריס)-צרפת-תשכב, עלה לירושלים, חיבר גם \"מכלל יופי\" - ירושלים תשל. חיבר חיבור על תולדות רבני אלגיר - ואבד.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":25830,"n":"כליפא, אברהם ממצרים","b":"מחכמי קהיר-שסו.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":25831,"n":"כליפי, חיים דוד מטריפולי","k":"בעל אורח לחיים","dt":"תרמו","b":"רב בטריפולי. חיבר \"מערכת כללים\", \"סימנא דחיים\". מתורתו ב\"מעטה תהלה\" ליוורנו תריח. חתם בשם - \"חיים מדב\"ר\".","s":"ארזי הלבנון; מלכי חי\"ל-מרציאנו"},{"i":25832,"n":"כלף, אברהם מתונס","dt":"תרכח - ט אייר","b":"רב בתונס. נספד מאת ר אליעזר אשכנזי מתונס ב\"הלבנון\"-תרכח.","s":"שם הגדולים השלישי"},{"i":25833,"n":"כלף, משה מתימן","b":"דיין בשרעב-תימן - מחצית ראשונה של המאה ה-20.","s":"ארזי הלבנון"},{"i":25834,"n":"כלפאני הכהן מגאבס-תונס","k":"בעל כסא רחמים","b":"רב בגאבס-תונס. מתלמידיו - ר נסים סיסי, ור פרג'י עלוש.","s":"ארזי הלבנון"},{"i":25835,"n":"כלפו, משה","b":"מגדולי התורה באיטליה בבארי-ד'תת\"ל","s":"אוצר הרבנים 14798"},{"i":25836,"n":"כלפון","f":"מנשה","b":"בשנת תתק (1140) היה בבית הדין בירושלים","s":"גליס; ספר הישוב ב"},{"i":25837,"n":"כלפון - משפחה","b":"משפחה שמקורה בספרד.","s":"גאון-יהודי המזרח"},{"i":25838,"n":"כלפון ממצרים","f":"עולא","b":"הגיע מטריפולי למצרים בזמן הרמב\"ם-ד'תתקן ונזכר בתשובותיו, דיין בדמנהור.","s":"אוצר הרבנים 6621; ארזי הלבנון; מלכי חי\"ל-מרציאנו"},{"i":25839,"n":"כלפון משה הכהן מג'רבה","f":"שלום","k":"בעל שואל ונשאל","bt":"תרלד","bp":"ג'רבא","dt":"תשו - יח טבת","dp":"ג'רבא - ירושלים","b":"נכד ר שאול הכהן מג'רבא. תלמיד ר יוסף ברבי בעל \"בן פורת יוסף\", ור משה זקן מאזוז. חתן דודו - אחי אמו - ר אברהם הכהן. שו\"ב בזרזיס, רב בג'רבא על מקום ר משה זקן מאזוז. בניו ר אברהם מגוץ, ור שושן הכהן דיין בג'רבא וישראל. חיבר ספרים רבים. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"הירח\" - ג'רבה תשח.","s":"אוצר הרבנים 12439; ארזי הלבנון; אוצר כתבי עת-לוין","bk":[["שואל ונשאל","שו\"ת - אחרונים"]]},{"i":25840,"n":"כלפון, אברהם הכהן מגרבה","f":"משה","k":"בעל ברכת אברהם","bt":"תרנח","dt":"תרצא","b":"מחשובי רבני ג'רבה, בעל \"ברכת אברהם\"","s":"ארזי הלבנון"},{"i":25841,"n":"כלפון, אברהם מטריפולי","f":"רפאל","k":"בעל חיי אברהם","bt":"תצה - תקא","bp":"ליוורנו או טריפולי","dt":"תקפ","dp":"צפת","b":"הגיע מליוורנו לטריפולי בילדותו עם הוריו. פרנס מחכמי טריפולי-תקלה, ונשיא הקהלה-תקלח. סיפר שמל אותו בעל \"אור החיים\" בליוורנו. חיבר פיוט \"מי כמוכה\" לשבת פורים בורגיל, וקינותיו על בנו שנשרף עק\"ה במאורעות. מחבוריו: \"חיי אברהם\" על טעמי המצוות (ליוורנו תקפו). ו\"לקט הקיצור\", אסף וחקר אודות קורות היהודים בטריפולי וחבר פיוטים שונים, כתב ידו על תקנות קדומות נעלם. ידידו של החיד\"א - והתכתב עמו, תלמידו של ר משה לחמייש. עלה לצפת אחר שנת תקסו או תקפ (ולפי \"ארזי הלבנון\" נולד בטריפולי ועלה בתקסו).","s":"גליס; ארזי הלבנון; אוצר הרבנים 504; שם הגדולים השלישי; איטליה גירונדי-א ק; אוצר הרבנים 505; מלכי חי\"ל-מרציאנו; פרומקין-תח\"י; פין-כנסת ישראל; ספר החידא ועוד"},{"i":25842,"n":"כלפון, אברהם ממרוקו","bt":"תקע - בערך","bp":"טיטואן? - מרוקו","dt":"תרן - בערך","b":"רב בתייארת-אלגיר. נזכר אצל ר אברהם אנקאווא ב\"כרם חמר\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":25843,"n":"כלפון, אברהם מספרד","b":"פייטן ומחבר מחכמי ספרד-ד'תתק\"מ","s":"אוצר הרבנים 503"},{"i":25844,"n":"כלפון, אברהם מתימן","k":"אברהם אל עדני","b":"משורר, מראשוני הפייטנים בתימן, מהעיר עדן","s":"ארזי הלבנון"},{"i":25845,"n":"כלפון, דוד מגיברלטר","b":"מו\"צ בגיברלטר-תץ. נזכר ב\"בית יהודה\" לר יהודה עייאש.","s":"אוצר הרבנים 4874; ארזי הלבנון; מלכי רבנן"},{"i":25846,"n":"כלפון, דוד מגיברלטר","f":"אברהם","b":"חיבר פירוש לאידרות בגיבאלטאר-סיים בסיון תצ\"א","s":"ארזי הלבנון"},{"i":25847,"n":"כלפון, דוד מחיפה","f":"אברהם רפאל","bt":"תריח","bp":"חיפה","dt":"תרצז - ל אדר","dp":"חיפה","b":"מורה בכי\"ח, חיבר שירים ומנגינות, ממיסדי \"בני יהודה\" - \"הדר הכרמל\" בחיפה.","s":"גאון-יהודי המזרח"},{"i":25848,"n":"כלפון, יהודה מטריפולי","bt":"תם","dt":"תקי - בערך","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":25849,"n":"כלפון, יוסף מטריפולי","f":"מרזוק","dt":"תקע - אחרי","dp":"מצרים","b":"רב בטריפולי-תקסב, ודיין עם ר יעקב זטלאווי, עלה לארץ - והיה גם בחיפה, עבר למצרים. נזכר אצל ר אברהם אדאדי ב\"ויקרא אברהם\". חתם בפנקס בי\"ד טריפולי.","s":"אוצר הרבנים 8375; מלכי חי\"ל-מרציאנו"},{"i":25850,"n":"כלפון, ימין","dt":"תרפט - ח טבת","b":"מרבני חיפה","s":"אוצר הרבנים 9338"},{"i":25851,"n":"כלפון, יעקב","f":"יוסף","k":"בעל משפטים צדיקים","b":"נכד ר יעקב מטיטואן וגיברלטר."},{"i":25852,"n":"כלפון, יעקב ליאון ממרוקו","b":"רב בטיטואן-תר\"ס","s":"אוצר הרבנים 7303"},{"i":25853,"n":"כלפון, יעקב מטיטואן וגיברלטר","k":"בעל נגד מלכים","bt":"תקסח","bp":"טיטואן","dt":"תרטו - יט אב","dp":"טיטואן","b":"רב בטיטואן-שנות ה-תק', גיברלטר-תקצה, חתם על פס\"ד עם ר מנחם אבודרהם ור וידאל ביבאס. נכדו - ר כלפון בן יוסף בעל \"משפטים ישרים\".","s":"אוצר הרבנים 9690; מלכי רבנן"},{"i":25854,"n":"כלפון, יעקב ממרוקו","b":"רב בפאס-תרם."},{"i":25855,"n":"כלפון, יצחק מלוב","bt":"תקס","dt":"תרל - בערך","b":"רב בבנגזי, והיה מראשוני הרבנים הידועים משם. נזכר ב\"מסעי ישראל\" ליק תריט.","s":"מלכי חי\"ל-מרציאנו"},{"i":25856,"n":"כלפון, יצחק ממרוקו וספרד","b":"משורר, נקרא בשם אבו אברהים בן חלפון ונזכר אצל ר\"מ ן עזרא שהגיע מאפריקה לספרד.","s":"מלכי רבנן"},{"i":25857,"n":"כלפון, כליפא מטריפולי","k":"בעל מקור דמך","bt":"תרי","bp":"טריפולי","dt":"תרפ","b":"חיבר שירים וקינות \"מקור דמך\" - ליוורנו תרלה. ?? לא באוצר ??","s":"ארזי הלבנון"},{"i":25858,"n":"כלפון, כליפא מטריפולי","k":"הו\"ל מקור דמעה","b":"תלמיד ר יעקב מימון. רב בטריפולי. הו\"ל \"מקור דמעה\" ליווורנו תרלה. נזכר ב\"באר לחי\" לר חי מימון - ליוורנו תרמח.","s":"מלכי חי\"ל-מרציאנו"},{"i":25859,"n":"כלפון, מרדכי משה ממרוקו","b":"חתם-תרח על אישור פס\"ד של ר ראובן אלמליח ור אברהם אנהורי, יתכן שהיה רב בטיטואן?","s":"מתוך קטלוג"},{"i":25860,"n":"כלפון, משה מטבריה","f":"רפאל מטבריה","dt":"תרפד - טז אב","b":"רב בגיברלטר?, עלה לארץ. מחכמי טבריה, רב בחיפה. חתנו - ר משה ן נעים מגיברלטר.","s":"אוצר הרבנים 14799; ארזי הלבנון"},{"i":25861,"n":"כלפון, נסים מטריפולי","bt":"תם","dt":"תקי - בערך","b":"רב בטריפולי. מתורתו ב\"זרע יצחק\" לר יצחק חדד - ירושלים תשסא.","s":"מלכי חי\"ל-מרציאנו"},{"i":25862,"n":"כלפון, ציון מטריפולי","bt":"תרי","dt":"תרף - בערך","b":"רב בטריפולי. חתם על הסכמה לשמירת זכויות הספרדים בקופת ר מאיר בעל הנס בטבריה. נזכר ב\"זכרון ירושלים\" תונס תרסד.","s":"מלכי חי\"ל-מרציאנו"},{"i":25863,"n":"כלפון, רחמים","f":"אברהם מטריפולי","b":"הו\"ל את ספר אביו \"חיי אברהם\".","s":"ארזי הלבנון"},{"i":25864,"n":"כלפון, רפאל אברהם ממרוקו","k":"אכ\"ל","bt":"תקף","bp":"מרוקו","dt":"תרמו - ד ניסן","dp":"חיפה","b":"מחכמי טיטואן-מרוקו, עלה לטבריה-תרך וכיהן כדיין וראש ישיבה, עבר לחיפה וכיהן כאב\"ד-תרמא וראש ישיבה. חתם על כתב שליחות ר שלמה טולדנו. הסכים על \"זבחי שלמים\" לר משה קורדובירו-תרמג, \"יסוד המערבי\", \"עשיר ורש\" ועוד. בנו - ר משה - חתנו של ר רפאל משה ן נאים מגיברלטר.","s":"גליס; אוצר 17841; ארזי הלבנון"},{"i":25865,"n":"כלפון, שלמה מטריפולי","b":"גביר בטריפולי בשנות ה-תע', סייע לפדות את ר עמנואל ריקי שנשבה בידי שודדים בדרכו מארץ ישראל.","s":"פרומקין-תח\"י"},{"i":25866,"n":"כלפון, שמואל מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון.","s":"טולדנו-נר המערב"},{"i":25867,"n":"כמון ן, מרדכי מפאס","b":"מחכמי פאס, חתם-רפו בענין הנפיחה.","s":"טולדנו-נר המערב"},{"i":25868,"n":"כמון ן, שאול מפאס","b":"מחכמי פאס-רפו, וחתם אז על הסכמה בענין נפיחת הריאה.","s":"ארזי הלבנון; מלכי רבנן"},{"i":25869,"n":"כמוס הכהן","f":"חיותו","k":"בעל כמוס עמדי","dt":"תשלז","b":"תלמיד ר דידו (דוד) הכהן מג'רבא. מחכמי ג'רבא, עלה לארץ והתישב בנתיבות.","s":"ארזי הלבנון"},{"i":25870,"n":"כמוס ן, אברהם הכהן","f":"יוסף","k":"בעל חיי אברהם","b":"כתב \"חיי אברהם\"","s":"ארזי הלבנון"},{"i":25871,"n":"כמוס שמואל הכהן מג'רבה","f":"שלום","k":"בעל דברי שמואל","b":"תלמיד ר דידו (דוד) הכהן מג'רבא.","s":"ארזי הלבנון"},{"i":25872,"n":"כנאפו, מסעוד ממוגדור","b":"דיין במוגאדור-תרע אצל ר יוסף כנאפו. חיבר שו\"ת בכת\"י. העתיק בכתב ידו - \"שבחי פסח\" בערבית יהודית.","s":"אוצר הרבנים 13653; אהלי שם; ארזי הלבנון"},{"i":25873,"n":"כנזי, שלמה הקראי מדמשק","f":"יוסף","k":"בעל ספר המישור","b":"נכד אשר יצחק בן יונה. רופא קראי מחכמי דמשק. חיבר ספר המישור - תפב - בכת\"י.","s":"רוזניס-תורכיה-ד"},{"i":25874,"n":"כניזו, שלום ממראקש","dt":"תקסט - א חשון","dp":"מראקש","b":"רב במראקש-מרוקו.","s":"ארזי הלבנון"},{"i":25875,"n":"כנסת יחזקאל - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בעזרת יחזקאל יהודה מבגדד והודו.","s":"רוזניס-תורכיה-ה"},{"i":25876,"n":"כנסת ישראל - ישיבה בירושלים","b":"ישיבה בירושלים-תק שיסד ר חיים ן עטר בעל אור החיים. ראש הישיבה ר חיים מונדיבי, עוד מתלמידיה ר שם טוב גבאי, ר יעקב אצבאן, ר יעקב פריינטי, ר צבי הלוי, ר עזריה לאורניס, ר אליהו דודו, ר שלמה ארגואוטי, ר מרדכי מערבי, ר דוד חסאן, ר יונה נבון, ר חיים יהודה אמזלג, ר יהודה די אבילא.","s":"טולדנו-נר המערב"},{"i":25877,"n":"כנסת ישראל - ישיבת בירושלים","b":"ישיבת בירושלים מיסודו של ר חיים ן עטר בעל אור החיים.","s":"רוזניס-תורכיה-ה"},{"i":25878,"n":"כנפו יוסף בן משה","k":"בעל מנחת ערב","bt":"תקפג","dt":"תרסא - כה כסלו","b":"מספריו הנוספים של ר\"י כנאפו: אות ברית קודש; זבח פסח [עניני חודש ניסן והגדש\"פ]; זך ונקי; חסדים טובים [כולל שלושה ספרים: חסד ה'; חסדי אבות [מעשיות הבעש\"ט בערבית]; חסדי דוד]; טוב רואי; יפה עינים - בדרכי שמים [מעין ספרו זבח פסח]; מנחת ערב; שומר שבת.","s":"מלכי רבנן; היברובוקס","bk":[["שומר שבת",""],["אות ברית קדש",""],["טוב רואי",""],["יפה עינים",""]]},{"i":25879,"n":"כנראה שפי' זה היה לפני הרוקח ושבלי הלקט","bt":"ד'תתקכ (בערך)","bk":[["פי' קדמון להגדש\"פ",""]]},{"i":25880,"n":"כסאר, חיים","k":"בעל שם טוב","bt":"תרסב","bp":"צנעא","dt":"תשנח - כב כסלו","b":"תלמיד ר' יחיא קאפח,עלה לא\"י תש\"ט,מגדולי חכמי תימן בא\"י,סופר גיטין ורב בית כנסת בירושלים,חיבר \"שם טוב\" על משנה תורה לרמב\"ם","s":"ארזי הלבנון","bk":[["שם טוב",""],["החיים והשלום",""],["קיץ המזבח",""]]},{"i":25881,"n":"כסאר, שלום מתימן","b":"חכם באשי בצנעא-תרן.","s":"ארזי הלבנון"},{"i":25882,"n":"כסאר, שלום מתימן וירושלים","f":"יחיא","bt":"תרלו","bp":"צנעא","dt":"תשכד","dp":"ירושלים","b":"עלה בילדותו עם הוריו לירושלים-תרמב, תלמיד ר יחיא צארום. ראש ישיבת \"מקור חיים\" בירושלים. חיבר זכרונות על עליית היהודים בתרמ\"ב.","s":"ארזי הלבנון; אוצר הרבנים 18157 א'; גאון-יהודי המזרח"},{"i":25883,"n":"כסיסא, חיים הכהן מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו-שנות ה-ת-תק'.","s":"מלכי רבנן"},{"i":25884,"n":"כסכסו, שמואל מפאס","b":"מחכמי פאס-שנות ה-תק'. מכתב תמיכה אליו מר רפאל יעקב שמחון. אולי הוא ר שמואל סכסו שנזכר אצל היעב\"ץ.","s":"מלכי רבנן"},{"i":25885,"n":"כספי, אבא מרי מאלגיר","f":"נחמן","k":"דון אשתרוק בונפיל","bt":"קמ","dt":"רך","b":"הגיע מספרד לאלגיר-קנא בזמן הגזירות. תלמיד הריב\"ש, והרשב\"ץ. מגדולי חכמי אלג'יר-קצ. שיר ממנו לכבוד הרשב\"ץ ב\"יבין שמועה\" להרשב\"ץ, וקינה ממנו על מצבת הריב\"ש.","s":"אוצר הרבנים 62 א'; אלופי יעקב א-יד; מלכי ישורון-חכמי אלגיר"},{"i":25886,"n":"כספי, אבא מרי מאלגיר","f":"יוסף","bt":"רל","dt":"ש","b":"רב משורר ופיטן באלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":25887,"n":"כספי, יוסף מאלגיר","f":"שלום בן אבא מרי","bt":"קע","dt":"רמ - בערך","b":"רב ומשורר ופיטן באלגיר בזמן הרשב\"ץ. קינות ממנו ב\"אורח מישור\" לר יעקב רקח, ועוד.","s":"מלכי ישורון-חכמי אלגיר; פין-כנסת ישראל"},{"i":25888,"n":"כספי, יוסף מאלגיר - ב","f":"אבא מארי","bt":"רס","dt":"של - בערך","b":"רב משורר ופיטן באלגיר. מפיוטיו בספרי חכמי אלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":25889,"n":"כספי, יוסף מצרפת וספרד - א","f":"אבא מארי","k":"בעל גביע כסף","bt":"מ'","dt":"ק'","b":"פייטן ומדקדק מחכמי צרפת, עשיר, רב במצרים, פאס, ספרד. חיבר \"קבוצת כסף\", \"מצרף לכסף\", פירוש לספר הקמה לר יונה ן גנאח, ועוד. היה מחלוקת על כתביו - ר יוסף יעבץ יצא כנגדו בספריו \"יסוד האמונה\" ו\"אור החיים\", ור קלונימוס בן קלונימוס השיג על ספרו \"טירת כסף\"-עט.","s":"אוצר הרבנים 8376; איטליה גירונדי-י קמח; פין-כנסת ישראל"},{"i":25890,"n":"כספי, מרדכי מירושלים","f":"אברהם","bt":"תרמה","bp":"ירושלים","b":"קונסול לטביה בירושלים."},{"i":25891,"n":"כספי, נתנאל מספרד","b":"מחכמי ספרד בזמן ר יצחק קנפנטון. תלמיד ר שלמה בן מנחם וחברו של ר שלמה די לוניל.","s":"ארזי הלבנון"},{"i":25892,"n":"כספי, רפאל משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי.","s":"רוזניס-תורכיה-ג"},{"i":25893,"n":"כספי, שלום מאלגיר","f":"אבא מארי","bt":"קל","dt":"ר - בערך","b":"פוסק מחכמי אלגיר בזמן הריב\"ש, והרשב\"ץ.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":25894,"n":"כספי, שלמה מאלגיר","bt":"תך","dt":"תץ - בערך","b":"משורר ודיין באלגיר אצל רי\"ש צרור. חתם על החרם נגד נחמיה חיון. נזכר ב\"פרי צדיק\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":25895,"n":"כספי, שלמה משלוניקי","dt":"שפא - יב אב","dp":"שלוניקי","b":"משורר מחכמי שלוניקי.","s":"עמנואל-שלוניקי; רוזניס-תורכיה-ג"},{"i":25896,"n":"כספי, שמואל מאלגיר","bt":"תס","dt":"תקל - בערך","b":"דיין באלג'יר-תקד אצל ר אברהם יאפיל. חתם על הסכמות ותשובות שהובאו אצל חכמי דורו, ובהם על ספרי ר יהודה עייאש.","s":"ארזי הלבנון; איטליה גירונדי-ש ט; מלכי ישורון-חכמי אלגיר"},{"i":25897,"n":"כעאבלו, יהודה מאספי-מרוקו","f":"מסעוד","b":"מחכמי אספי-מרוקו-תכט.","s":"מלכי רבנן"},{"i":25898,"n":"כעבאלו, יהודה מאספי","b":"מחכמי אספי-תכט, נזכר באגרת ר מסעוד אתאזי.","s":"טולדנו-נר המערב"},{"i":25899,"n":"כעבאלו, מסעוד מאספי-מרוקו","b":"רב באספי-מרוקו - בשנות ה-ת.","s":"ארזי הלבנון; מלכי רבנן"},{"i":25900,"n":"כעבון, ישראל מאלגיר","bt":"רץ - בערך","dt":"שע - בערך","b":"רב באלגיר, תלמסאן. נזכר ב\"עומר השכחה\" ואצל החיד\"א.","s":"אוצר הרבנים 11952; ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":25901,"n":"כעבון, מכלוף מאלגיר","bt":"שך","dt":"שץ - בערך","b":"רב במילייאנא-אלגיר. שאלה ממנו לרשב\"ץ האחרון.","s":"מלכי ישורון-חכמי אלגיר"},{"i":25902,"n":"כץ אריה ליב בן משה","dt":"ה'תקפ 1820","s":"היברובוקס","bk":[["פני אריה",""],["קונטרס מילי דאבות",""]]},{"i":25903,"n":"כץ ברטדם, שלמה","dt":"תריח - יא אד\"א","b":"רב בשטעקטשין,פינטשוב,ראב\"ד בקרקא","s":"אוצר הרבנים 18395"},{"i":25904,"n":"כץ גרוס, משה פערי","bp":"טיסא-פערע","b":"תלמיד החת\"ס, ור יצחק פרנקל מקראלי. חתן הגביר ר דוד קליין. גר בפעטשי-ניידורף וניהל אחוזה בפריטש ובעל מפעל למים מינרלים \"סאלוואדור\". כשירד מנכסיו נתמנה שם לרב-תרכה.","s":"החת\"ס ותלמידיו"},{"i":25905,"n":"כץ דב בן יעקב","bt":"1903","dt":"ה'תשלט 1979","s":"היברובוקס","bk":[["פולמוס המוסר",""]]},{"i":25906,"n":"כץ יהודה בן יעקב מאיר","f":"יעקב מאיר","k":"בעל קול יהודה","bt":"תר","dt":"תרסט","b":"מחסידי ר חיים מצאנז, סירב להצעת רבו לרבנות דוקלא (ותולה בסירוב את השריפה שכלתה את רכושו), רב בסנוק. חיבר \"קול יהודה\" מונקטש תרסז. מתורתו ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז.","s":"וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין; היברובוקס","bk":[["קול יהודא",""]]},{"i":25907,"n":"כץ מאיר יוסף","bt":"1900","dt":"ה'תשמח 1988","s":"היברובוקס","bk":[["שאר יוסף",""]]},{"i":25908,"n":"כץ מחוקק, בנימין","dt":"תסה","b":"רב בוירמיזא","s":"אוצר הרבנים 3724"},{"i":25909,"n":"כץ קודש, י' אר' ליבוש","dt":"תרכח - יד אלול","b":"מו\"צ בוורשה-תקצ\"ה","s":"אוצר הרבנים 7146"},{"i":25910,"n":"כץ קערעפש, יום טוב ליפמן מאירש","f":"אהרן","bp":"אטש","b":"תלמיד החת\"ס. חתן ר דוד קערעפש מאירשא ועבר לשם והיה מחכמי אירשא. נזכר ב\"חתם סופר\".","s":"החת\"ס ותלמידיו"},{"i":25911,"n":"כץ ראובן בן השקי","bt":"1605","dt":"ה'תלג 1673","s":"היברובוקס","bk":[["דבר שבקדושה",""],["ילקוט ראובני",""],["עונג שבת",""]]},{"i":25912,"n":"כץ ראובן בן שמעון","f":"שמעון הכהן מאלשאן","k":"בעל דגל ראובן","bt":"תרם","bp":"אולשאן-פלך וילנא","dt":"תשכד - יז חשון","dp":"פתח תקוה","b":"תלמיד ישיבות איווייה, מיר, ראדין, סלובודקה, וסלוצק (מ-14 הבחורים שעברו לשם עם ר איסר זלמן מלצר), ולמד בקיבוץ ר חיים עוזר גודזנסקי בוילנא. חתן ר אברהם יצחק משכיל לאיתן מחסלביץ. רב בסליב(=סעליב)-פלך מינסק-תרסה, אמדור-תרסט, ראש ועד העזרה במחוז גרודנא-לאחר מלחה\"ע ה-I, רב בסטאויסק-תרפג, לבקשת החפץ חיים יצא בראש משלחת רבנים בארה\"ב-תרפט ונשאר שם לכהן כרב ביון-ניו ג'רסי, וסגן נשיא אגודת הרבנים בארה\"ב. רב ראשי בפתח תקוה-תרצב, ומנהל ישיבת לומז'ה שם. ממייסדי \"ועד הישיבות\" בא\"י. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"המאור\" - תל אביב תרצה, פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ, \"השער\" - בני ברק תשח, \"תורת ארץ ישראל\" - ירושלים תרץ.","s":"אוצר הרבנים 17705; ליטא; אוצר כתבי עת-לוין; אהלי שם; קשת גבורים חלק א עמודים 141 - 146; היברובוקס","bk":[["דגל ראובן - שו\"ת",""],["שער ראובן - מאמרים",""],["דגל ראובן",""],["דודאי ראובן",""],["שער ראובן",""]]},{"i":25913,"n":"כץ רפא, יקותיאל","b":"גביר,רב בפורטו-רכ\"ז","s":"אוצר הרבנים 11531"},{"i":25914,"n":"כץ רפאל בן יקותיאל זיסקינד","bt":"1722","dt":"ה'תקסג 1803","s":"היברובוקס","bk":[["דעת קדושים",""],["זכר צדיק",""],["מרפא לשון",""],["שאלת הכהנים תורה",""],["תורת יקותיאל",""]]},{"i":25915,"n":"כץ, אביגדור מזבורוב","b":"רב בזבורוב. זקנו של ר יצחק הורודנר מוינה.","s":"וונדר-גליציה ח\"ג"},{"i":25916,"n":"כץ, אביגדור מרדכי מאוסטרין","f":"אברהם עזרא מאמדור","k":"בעל פרי הדר","b":"רב באוסטרין(=אסטרין)-[תרכ..], גראיעווע. חיבר גם \"קרבן תודה\", ענבי גפן\", \"תורת אביגדור\", ועוד. גיסו - ר בן ציון איזנשטט בעל \"אמרי ברוך\".","s":"ליטא; שם הגדולים השלישי"},{"i":25917,"n":"כץ, אברהם אהרן מנייטרא","f":"משה פרוסטיץ מנייטרא","bt":"תרכט או תרלד","dt":"תרץ - יז אייר","dp":"נייטרא","b":"תלמיד השב\"ס, ור משה צבי הרש פוקס מגרוסורדין. מו\"ץ בנייטרא-תרס ורב-תרפז על מקום אביו. נסמך מאת: השב\"ס, דודו ר דוד פרידמן מצעהלים. בנו ר אליהו כץ רב בבאר שבע.","s":"החת\"ס ותלמידיו; אוצר הרבנים 941; הונגריה; אהלי שם"},{"i":25918,"n":"כץ, אברהם אליהו משה מפעצעל","dt":"תרלג - יד תשרי","b":"רב בפעצעל","s":"אוצר הרבנים 956"},{"i":25919,"n":"כץ, אברהם אריה ליב מברוד","f":"כהנא, אברהם אריה ליב","b":"רב בברוד תק\"כ","s":"אוצר הרבנים 978"},{"i":25920,"n":"כץ, אברהם דב ברטשי מלמברג","f":"חיים","bt":"תרלט","bp":"בוברקא","dt":"תשב","b":"חתן ר ישראל גרינולד ממוסט. רב בלמברג-תרסב. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":25921,"n":"כץ, אברהם חיים ממוהילוב","k":"בעל פת לחם","b":"מג\"מ במאהליב-תק\"נ","s":"אוצר הרבנים 1075"},{"i":25922,"n":"כץ, אברהם מויזון","b":"רב בויזון על מקום ר אהרן שמידט ור זלמן מלצר הי\"ד על מקומו אחריו.","s":"ליטא"},{"i":25923,"n":"כץ, אברהם מירושלים","b":"תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\".","s":"אוצר כתבי עת-לוין"},{"i":25924,"n":"כץ, אברהם מלמברג","b":"דיין בלבוב, חתם-תפד עם ר נתן נטע בן זלמן ור אהרן זליג בן שמואל למשפחת צבי, ועוד.","s":"אוצר הרבנים 485; בובר-לבוב"},{"i":25925,"n":"כץ, אברהם מפעטרא","dt":"תרך - אחרי","dp":"פעטרא (ליד מרגרעטין)","b":"תלמיד החת\"ס. בנו - ר יצחק יוסף כץ קאהן מסמאש-אויוואר, חתנו - ר אליהו וייס משימלויא. תשובה אליו ב\"חתם סופר\".","s":"החת\"ס ותלמידיו"},{"i":25926,"n":"כץ, אברהם עזרא מאמדור","f":"שמואל מאמדור","dt":"תרמב","b":"רב באמדור-במאה ה-19, לאחר פסק דין מוטעה פרש מן הרבנות ויצא להשתלם בתורה ובפוסקים, קהילת אמדור המתינה לו עד שחזר. בנו ר אביגדור מרדכי מאוסטרין בעל \"פרי הדר\".","s":"ליטא; שם הגדולים השלישי; ברוורמן-אנשי שם"},{"i":25927,"n":"כץ, אברהם צבי מדאוג","b":"רבה של דאוג-ליטא כ-40 שנה, ור אפרים ניסן מה-יפית על מקומו אחריו.","s":"ליטא"},{"i":25928,"n":"כץ, אברהם שלמה מריסקובה ונ\"י","f":"אליהו מראסלביץ","k":"בעל אורחות המשפטים","bt":"תרמד","dt":"תשלה - יד ניסן","b":"חסיד סיגט-סטמר. תלמיד בעל \"ערוגת הבשם\" בחוסט, וה\"קדושת יו\"ט\" בסיגט. חתן ר צבי ברגפלד מנימוזה, רב בנימוזה-תרעה על מקום חותנו, רב בריסקווה-(=פוליען-ריסקובה)-מרמארוש והקים ישיבת \"תורת אש\" (ר\"ת שמו). נחשב למומחה בדיני ממונות ונבחר כבורר ואב\"ד בדיני תורה מסובכים. ניצל מהשואה, ואחריה רב בקלויזנבורג, וכיהן כנשיא הועד הפועל של לשכת הרבנים-תשה. היגר לארה\"ב-תשי, עלה לארץ-תשכה וכיהן כרב \"קרית יואל\" בבני ברק. חיבר גם \"דברי אש\". פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"טרנסילבניה; אוצר הרבנים 18671 א'; אמריקה"},{"i":25929,"n":"כץ, אהרן גד מנימוז'ה","f":"אליהו מראסלוביץ","k":"בעל קרן אורה - בכת\"י","r":"אב\"ד ראסאלויץ","bt":"תרמז","dt":"תשא - ח תמוז","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט, וה\"קדושת יו\"ט\" בסיגט. חתן הגביר ר אלתר לאנדוי מבאטארטש-ליד האלמין, ועבר לשם. רב בנימוזה-תרפו על מקום אחיו ר אברהם שלמה שעבר לריסקווה. רוב כתביו אבדו בשואה.","s":"טרנסילבניה; זכרו תורת משה גליון תרכ","bk":[["פרח מטה אהרן – שו\"ת",""]]},{"i":25930,"n":"כץ, אהרן יצחק הלוי מפולנגן","f":"שמואל מנחם מפולנגן","bt":"תרסח","dt":"תשא","dp":"פולנגן-ליטא","b":"תלמיד זקנו ר חיים הלוי מפומפיאן, וישיבות טלז, פוניבז. רב באוטיאן, פולנגן על מקום אביו. נספה בשואה.","s":"ליטא"},{"i":25931,"n":"כץ, אהרן מברלין","f":"איזיק","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין.","s":"תולדות אנשי השם-לנדסהוט"},{"i":25932,"n":"כץ, אהרן מורנדורף","b":"רב בוארנדורף(=ורנדורף)-תקכא, ומדינת פדרבורן ווסטפליה.","s":"מתוך קטלוג"},{"i":25933,"n":"כץ, אהרן מזילוזיץ","k":"בעל לקוטי שושנים","b":"רב בזילוזיץ-תרסו. חיבר \"לקוטי שושנים\" מונקטש תרעד, ועוד.","s":"וונדר-גליציה ח\"ג"},{"i":25934,"n":"כץ, אהרן מנחם (משה) מקראקא","f":"יוסף","k":"ר מנדל ר זלמן חזנש","dt":"שעו - ט אדר","dp":"קראקא","b":"(לפי גדולי אוסטרהא היה נכדו של ר יוסף בעל שארית יוסף). חתן ה\"פני יהושע\"?. ש\"ץ בקראקא. בנו: ר שלום שכנא כהנא מקראקא. אחיו: ר תנחום מקראקא, ר משה מקראקא.","s":"אוצר הרבנים 1835; שם הגדולים השלישי; צונץ-קראקא"},{"i":25935,"n":"כץ, אהרן שלמה מאלמאשד","b":"רב באלמאשד-ת\"ר","s":"אוצר הרבנים 1883"},{"i":25936,"n":"כץ, אהרן שמואל מיאנישוק וראסיי","f":"חיים שמעון הכהן","k":"בעל גחלי אש","bt":"תרל","dt":"תשג","b":"תלמיד ישיבת וולוזין. חתן ר בן ציון גינצבורג-מו\"ל ביאור הגר\"א. רב ביאנישוק-פלך קובנא-תרנז, מו\"צ בראסיין-תרסא על מקום ר אברהם יצחק רבינוביץ, ולימים-תרעא אב\"ד ורבה האחרון של ראסיין. חיבר גם \"אמרי אש\". נספה בשואה.","s":"אוצר הרבנים 1888; ליטא; אהלי שם; מרקוביץ-ראסיין"},{"i":25937,"n":"כץ, אלברט מברלין","k":"בעל היהודי וארץ אבות","bt":"תריט","bp":"לודז","b":"תלמיד ישיבת לובלין, וילנא, בעל תואר ד\"ר. רב בביהכ\"נ \"אהל יצחק\" בברלין-תרמד. חיבר גם \"נשמת העם היהודי\", \"שקר הדם\", \"היהודים בקוקז\", \"היהודים בסין\", ועוד. מראשי חברת \"לקורות היהודים וספרותם\".","s":"אהלי שם"},{"i":25938,"n":"כץ, אליהו מבאר שבע","f":"אברהם אהרן","k":"בעל באר אליהו","bt":"תרעו","bp":"נייטרא","dt":"תשסה - ח כסלו","b":"תלמיד הדעת סופר, וגיסו ר שלמה וייס מסעמניץ ור שמואל דוד הלוי אונגר ועוד. חתן ר משה ליבוביץ. ניצל מהשואה ואחריה רב בנייטרא, פרשבורג, רב ראשי בסלובקיה. עלה לארץ וכיהן כרב בבאר שבע-תשלא.","s":"החת\"ס ותלמידיו"},{"i":25939,"n":"כץ, אליהו מרסלביץ","b":"רב בראסלאביץ-תרע\"ד","s":"אוצר הרבנים 2124"},{"i":25940,"n":"כץ, אליעזר מזלוטשוב","f":"משה אשכנזי הכהן","b":"רב בזלוטשוב(=זלאטשוב)-ת\"ו","s":"אוצר הרבנים 2521"},{"i":25941,"n":"כץ, אליעזר מנ\"י","b":"תלמיד ישיבת \"רבי יצחק אלחנן\". פרסם מאמרים ב\"הדנו\" - נ\"י תרפה.","s":"אוצר כתבי עת-לוין"},{"i":25942,"n":"כץ, אליעזר מפרשבורג","f":"שמעון צבי הרש","dt":"תרפט - יב שבט","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור משה שיק מחוסט. רב בפרשבורג, מלמד ב\"יסודי התורה\" בפרשבורג-תרמה, ראש חברת ש\"ס בפרשבורג.","s":"החת\"ס ותלמידיו; פרשבורג-וינגרטן"},{"i":25943,"n":"כץ, אלכסנדר מזברז","b":"רב בזברז.","s":"וונדר-גליציה ח\"ג"},{"i":25944,"n":"כץ, אלכסנדר סנדר מוארשא","f":"אריה ליב מפלוצק","b":"נכד ר שמואל לסקר. חתן ר משה מאניס מקמפנא. נזכר בספר קרובו \"שמן רוקח\", וב\"צלעות הבית\" לר מאיר פוזנר. גיסו(-בעל אחותו) - ר מאיר צילך מלוסק.","s":"עיר לאסק וחכמיה"},{"i":25945,"n":"כץ, אלעזר מקמינקא","f":"יהושע מליזנסק","dt":"תקמד - יג תמוז","b":"רב בקמינקא.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 2875"},{"i":25946,"n":"כץ, אנשיל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר כתבי עת-לוין"},{"i":25947,"n":"כץ, אפרים יחיאל ממודנא","f":"דוד","dt":"תקסט","b":"רב במודנא. נכד מוהררי\"ך בעל \"זרע אמת\" ממודנא.","s":"איטליה גירונדי-א מד"},{"i":25948,"n":"כץ, אריה ליב מפרידאן","f":"משה מטיקטין ומאקובה","k":"בעל פני אריה","dt":"תקפא","b":"חתן ר אשר קמץ. רב בפרידאן-פלך פוזנא. נשא ונתן עם חכמי דורו ובהם ר עקיבא איגר. נספד ב\"דרשות גבר\"י\" פפדא תקפו. עליו בהקדמת רצ\"י מיכלזון ל\"דברי גדולים\", ו\"בית אהרן וישראל\" קובץ 30 תשנו.","s":"אוצר הרבנים 3313"},{"i":25949,"n":"כץ, אשר אנשיל ממטרסדורף","b":"דומ\"צ במטסדורף-תר\"י","s":"אוצר הרבנים 3566"},{"i":25950,"n":"כץ, אשר אנשיל מנירמעדיעץ","f":"יונתן בנימין מטשנגר","k":"בעל ולאשר אמר-תשמא","bt":"תרמא","bp":"צ'נגר","dt":"תשד - כז סיון","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט. נסמך מאת: בעל \"הכנה דרבה\". חתן ר שלמה זלמן ארנרייך משאמלוי, דיין בשאמלוי ור\"מ בישיבת חותנו שם. רב בניר-מעדיאש-תרסט, רב בדונא-סערדאהעי(=סערדאוהל) ועמד בראש הישיבה. נספה בשואה. בנו ר יהושע הו\"ל כמה מספריו.","s":"אוצר הרבנים 3565; אהלי שם; ברוין-אנשי מופת; טרנסילבניה; הונגריה"},{"i":25951,"n":"כץ, אשר שמואל מקנדה","f":"פנחס יהודה מקרולה","dt":"תשם -","b":"חתן דודו ר אברהם שלמה כץ מריסקווה. רב בזשיבוי. ניצל מהשואה, ואחריה עבר לקנדה וכיהן שם כרב. הו\"ל \"ים הרחב\" לר חיים בצלאל פאנט.","s":"טרנסילבניה"},{"i":25952,"n":"כץ, בן ציון","f":"אברהם צבי","k":"בעל מזקנים אתבונן","bt":"1875","bp":"דאוג-ליטא","dt":"1958","dp":"תל אביב","b":"בנו של רבה של דאוג-ליטא. נכד ר שמואל איסר שהיה ר\"מ בישיבת מייליס בוילנא. התפרסם כ\"עילוי מדאוג\". פרסם מאמרים נגד החומרות היתרות ועורר מחלוקת. חיבר גם \"לתולדות ההלכה\". הוזמן לפטרבורג ע\"י הברון גינצבורג להוציא את כת\"י הירושלמי שהיה ברשות הברון עם פירוש מרדכי לכבוד הפרופ' חוולסון - אך לא הסתייע. חיבר גם \"לקורות היהודים ברוסיה\" - ברלין תרנט, ועוד. עלה לארץ-1931 וחיבר \"האמת קודמת לשלום\" לטובת סטבסקי שנאשם ברצח ארלוזרוב.","s":"ליטא"},{"i":25953,"n":"כץ, בן ציון מבורשטשוב","f":"יעקב קופל","k":"בעל ירושלים דדהבא","bt":"תרמז","bp":"סערט","dt":"תרצה","b":"חתן ר אברהמצי יוסף בקנרוט מסכודניצה. רב בבורשטשוב-תרעא, וינה, טשרנוביץ-תרפג. נפטר ללא ילדים. חיבר \"ירושלים דדהבא\" דרוהוביטש תרע. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 3920"},{"i":25954,"n":"כץ, בנימין בישקא מאורלי","b":"בניו: ר נחמן מאורלי, ור שבתי משנאדאווה ואורלי בעל \"שבת אחים\".","s":"מוריה 21-י-יב"},{"i":25955,"n":"כץ, בנציון מטעטש","b":"חתן ר יהודה יואל דייטש מגאניטש. חתנו - ר מאיר דייטש מגאניטש - נתניה.","s":"החת\"ס ותלמידיו"},{"i":25956,"n":"כץ, בצלאל מאוסטרהא","f":"נפתלי","dt":"תעז - כא סיון","dp":"אוסטרהא","b":"חתן ר יואל הלפרין מאוסטרהא. רב באוסטרהא על מקום אביו. נפטר בחיי אביו. (בזמן הלוייתו היו חייבים לעבור דרך בית מקלט היעזוטים שדרשו לתת להם נרות כדי לעבור בשלום ואם לא סקלו את אנשי ההלוויה - ור נפתלי אביו שהיה בעל קבלה מעשית סימן עיגול סביב המטה והגויים שחיכו להם עם אבנים לא ראו אותם). בניו - ר יצחק איזיק מאוסטרהא, ר נחמן הכהן (חתנו של ר חיים רפפורט מלבוב), ר יוסף (חתנו של ר יהודה ליב מייזלש ממיר), חתניו - ר משה רוקח מזלוטשוב, ר יוסף לנדא מקלימנטוב, ר דב בער בן ר שמואל רבי יעקליש מאוסטרהא.","s":"אוסטרהא מ; אוצר הרבנים 4011"},{"i":25957,"n":"כץ, בצלאל מיאס","f":"ישעיה כץ","b":"רב ביאס והמדינה-תק\"י","s":"אוצר הרבנים 4012"},{"i":25958,"n":"כץ, בצלאל מראקישוק","f":"יוסף מראקישוק","bt":"תרד","dt":"תש","b":"רב בראקישאק(=ראקישוק) בקהלה החסידית על מקום אביו - במשך עשרות שנים. חסיד ליובאביץ. חתנו ר אברהם מאירוביץ על מקומו אחריו.","s":"אוצר הרבנים 4015; ליטא"},{"i":25959,"n":"כץ, ברוך מברוד","dt":"תקכ","b":"דרשן,מגיד בברוד","s":"אוצר הרבנים 4101"},{"i":25960,"n":"כץ, גבריאל מזאמטר","f":"יעקב","k":"בעל דרשות גברא","bt":"תקמד","bp":"וערשנה","dt":"תרכד - יד אייר","dp":"זאמטער","b":"רב בגנעזען, טירטשיגל, זאמטר-תקצג ועמד בראש ישיבה.","s":"אוצר הרבנים 4288; פין-כנסת ישראל"},{"i":25961,"n":"כץ, דב","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא.","s":"אוצר כתבי עת-לוין"},{"i":25962,"n":"כץ, דב בריש הכהן מאפטא","f":"יצחק","k":"בעריש שפתי כהנ'ס","b":"מצאצאי בעל הש\"ך. חתן הגביר ר אברהם אבלי-נכד ר יחזקאל הלוי מקרוטשין. מגדולי חריפי דורו, רב בפינטשוב-תקל, סטבניץ, אפטא. בניו - ר יצחק, ר יצחק אברהם (נקרא יצחק ע\"ש אחיו שנפטר) בעל \"כתר כהונה\"על מקומו אחריו. מצאצאיו החלו לכנות עצמם - רפפורט.","s":"אוצר הרבנים 4546; אהלי שם"},{"i":25963,"n":"כץ, דב בריש מראקוב ופינטשוב","f":"אברהם יצחק כץ","dt":"תקעה - ב אד\"ב","b":"רב בראקוב,פינטשוב","s":"אוצר הרבנים 4547"},{"i":25964,"n":"כץ, דב מדוברומיל","f":"ראובן","b":"רב בדוברומיל.","s":"וונדר-גליציה ח\"ג"},{"i":25965,"n":"כץ, דוד מגיד מקולבסוב","f":"מאיר [או ברוך]","dt":"תקפז","b":"תלמיד ר אלימלך מליזנסק, ר לוי יצחק מברדיטשוב והחוזה מלובלין. רב בקולבוסוב-תקס, אדומישל-גדול-תקסה, נכדו ר פנחס כץ על מקומו אחריו. מתורתו ב\"מגיד תהלות\"","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":25966,"n":"כץ, דוד מדולינא","f":"מנחם מנדל","b":"רב בדולינא-תקפא.","s":"וונדר-גליציה ח\"ג"},{"i":25967,"n":"כץ, דוד מחנטשין","f":"דוב בעריש כץ","b":"רב בחנטשין-תק\"צ","s":"אוצר הרבנים 4871"},{"i":25968,"n":"כץ, דוד ממטרסדורף","f":"צבי הירש","k":"בעל מנחת כהן","b":"רב במטרסדורף-תר\"כ","s":"החת\"ס ותלמידיו; אוצר הרבנים 4870"},{"i":25969,"n":"כץ, דוד צבי מרדומישל","f":"פנחס","b":"רב ברדומישל על מקום אביו, בנו ר משה על מקומו אחריו.","s":"וונדר-גליציה ח\"ג"},{"i":25970,"n":"כץ, הלל מלבוב","f":"יצחק","dt":"תב - יג ניסן","dp":"לבוב","b":"ר\"מ ודיין בלבוב. חתם-שצט עם ר שמואל זאנויל אוירבך, ור יעקב קצנלנבוגן.","s":"אוצר הרבנים 5289; מצבות קדש-לבוב; בובר-לבוב"},{"i":25971,"n":"כץ, הלל מצפת","f":"שמואל","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי.","s":"פרומקין-תח\"י"},{"i":25972,"n":"כץ, זאב וולף","dt":"תקיב - ה טבת","b":"ראב\"ד בקרקא","s":"אוצר הרבנים 5499"},{"i":25973,"n":"כץ, זאב מטרנופול","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא.","s":"אוצר כתבי עת-לוין"},{"i":25974,"n":"כץ, זושא זיסקינד","f":"דוב בערים כץ","b":"רב-שנת תק\"פ","s":"אוצר הרבנים 5715"},{"i":25975,"n":"כץ, חיים","f":"שמואל","b":"מצאצאי ר גומפריך. תלמיד ר שמעון וינר, נסמך-תריב מאת ר יעקב הרצוג מאבניא.","s":"מתוך קטלוג"},{"i":25976,"n":"כץ, חיים דוד זאב","dt":"תש","b":"רב בדובראווא","s":"אוצר הרבנים 6299"},{"i":25977,"n":"כץ, חיים הלוי מפומפיאן","f":"יהודה ליב נח מזאסלי","k":"בעל עונג חיים","bt":"תריד","bp":"ז'וסלי-ליטא","dt":"תרצב - ב אד\"ב","b":"חתן הגביר ר יוקיל סגלובסקי מקובנא. נסמך מאת: ר יצחק אלחנן מקובנא ועסק אצלו בהוראה. רב בגודלבה(=געויא)-פלך סובאלק-תרמא, איווייה(=וועויא)-פלך וילנא, פומפיאן-פלך קובנא-תרמט. דרשן, מראשוני הרבנים הציונים בליטא ודרש למען הציונות. חיבר גם \"מסלות חיים\", \"ישועת חיים\", ועוד. בניו: ר יוסף הלוי מגלובוק, ר שמריהו מויזון, ר משה יונה מסרדניק, ור שמואל מנחם מוילון ופולנגן. נכדו ותלמידו ר אהרן יצחק כץ הלוי רב בפולנגן.","s":"אוצר הרבנים 6029; ליטא; אהלי שם"},{"i":25978,"n":"כץ, חיים מאוסטרהא","f":"נפתלי","b":"יש אומרים שלא היה בן כזה.","s":"בובר-לבוב"},{"i":25979,"n":"כץ, חיים מוילנא וירושלים","f":"טוביה","k":"חיים פאקראוער","dt":"תקעג - כח תמוז","dp":"צפת או ירושלים","b":"חתן ר אברהם בן משה ציפקעס (אצל ריבלין - חתן שפרינצא בת ר שמחה כץ רפפורט). מתלמידי הגר\"א, רב בפוקרוי, דיין בוילנא, התכתב עם ר אברהם דנציג המזכירו בספרו \"נשמת אדם\", בספר \"עליות אליהו\" מסופר שר חיים היה הולך מדי יום לשמוע את שיעורי הגר\"א במכילתא. הסכים על ספר \"תולדות אדם\" לר יחזקאל המגיד מוילנא. בשנת תקע עלה לירושלים בשיירת ר ישראל משקלוב. (בספר \"עיר וילנא\" מסופר שנפטר בירושלים תקעג). חתם ראשון על הכרוז ליהודי רוסיה וליטא לתמוך בישוב בצפת, ובביהמ\"ד ע\"ש הגר\"א בצפת. הניח פירוש לתלמוד ועל השו\"ע - בכת\"י בידי נכדו ר לוי חיים רוקח דיין בוילנא. ישב בדין-תקנה במחלוקת בין החסידים והמתנגדים בוילנא יחד עם חברו ר יהודה ליב בן יצחק כץ (=ליבלי רומשיסקער) - כאשר מצד החסידים היה ר מאיר רפאל'ס ומצד המתנגדים ר ליבלי ר בער'ש.","s":"גליס; אוצר הרבנים 6031; עיר וילנא ח\"א; ליטא; פרומקין-תח\"י"},{"i":25980,"n":"כץ, חיים מיברוב ולבוב","f":"יקותיאל זיסקינד","b":"חתן ר חיים הלוי מיברוב. רב ביאבורוב(=יברוב), נמרוב(=נעמרוב), ראב\"ד בלבוב, ראש מדינה דגליל לבוב, וראש דד\"א-תפו. לפי ר יוסף לוינשטין - אולי אחיו ר רפאל הכהן בעל \"ושב הכהן\".","s":"אוצר הרבנים 6025; בובר-זולקוא; בובר-לבוב"},{"i":25981,"n":"כץ, חיים ממגרוב","bt":"תרמח","bp":"מגרוב","dt":"תשה","b":"חתן ר ישראל חיים רוזנפלד מפאקש-תרע. מחכמי אונגוואר סוחר מצליח ואיש חסד. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":25982,"n":"כץ, חיים מפרג","f":"יצחק כץ","dt":"רע - כח תשרי","dp":"פרג","b":"ממגורשי קושטא? מרביץ תורה בפרג. נהרג עק\"ה סמוך לעיר צחיטא(=צוויטאוי). בנו - ר מרדכי גרשון מוינה. אחיו - ר עקיבא מאויבן.","s":"אוצר הרבנים 6022; פין-כנסת ישראל; שם הגדולים השלישי"},{"i":25983,"n":"כץ, חיים שמואל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה.","s":"אוצר כתבי עת-לוין"},{"i":25984,"n":"כץ, יהודה","f":"נפתלי מפרג ולובלין","b":"אחיהם של ר פנחס מפולדא, ר יצחק מסטפין, ר חיים מפוזנא, ר מרדכי מברודא.","s":"ברוורמן-אנשי שם"},{"i":25985,"n":"כץ, יהודה ליב מפלאצק","f":"יצחק כץ מלובלין","b":"רב בפלאצק","s":"אוצר הרבנים 7300"},{"i":25986,"n":"כץ, יהודה ליב משברשין","b":"רב בשברשין-תס\"א","s":"אוצר הרבנים 7293"},{"i":25987,"n":"כץ, יהודה מאוסטרהא","f":"שלמה זלמן","k":"ר יהודה ר יוקבת","dt":"תעט - ח תשרי","dp":"אוסטרהא","b":"חתן ר יעקב-יוקבת חסיד מאוסטרהא. מחכמי ונכבדי קראקא. בנו של ר שלמה זלמן כץ שהיה אבי משפחת זוסמן, ובנו ר שלמה זלמן שהיה ר\"מ באוסטרהא.","s":"אוסטרהא נג"},{"i":25988,"n":"כץ, יהודה מלמברג","dt":"שעה - כו ניסן","b":"רב בלבוב","s":"אוצר הרבנים 6961"},{"i":25989,"n":"כץ, יהודה פסח מלענשנע","k":"בעל קרבן פסח","b":"רב בלענטשנע","s":"אוצר הרבנים 7454"},{"i":25990,"n":"כץ, יהושע השל ריינס מהורדנא","f":"אריה ליב","k":"בעל ישועות יהושע","bp":"גרודנא","dt":"תקעג - ז ניסן","dp":"הורדנא","b":"רב בהורדנא. תלמיד ר אלכסנדר זיסקינד בעל \"יסוד ושורש העבודה\". הגיה את באור הגר\"א לנביאים, ולמשניות. חיבר \"ישועות יהושע או מעיני יהושע\" על \"שנות אליהו להגר\"א.","s":"אוצר הרבנים 7638; ליטא; פין-כנסת ישראל; פרידנשטין - הורדנא"},{"i":25991,"n":"כץ, יהושע זאב הכהן מוארשא","f":"יהודה ליב","k":"בעל דברי רבית","b":"מחכמי וארשא, חיבר גם \"מורה קריאת התורה\"."},{"i":25992,"n":"כץ, יהושע ממאקווא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר כתבי עת-לוין"},{"i":25993,"n":"כץ, יהושע מסמבאטהעלי","k":"בעל ויאמר יהושע","b":"רב בסמבאטהעלי, ניו יורק, ובנו ר אשר אנשיל בעל \"שמן ראש\" על מקומו אחריו.","s":"אמריקה"},{"i":25994,"n":"כץ, יהושע מקראקא","f":"שלום שכנא הכהן -רש\"ך","bt":"תי","dt":"תצה - יא כסלו","dp":"קראקא","b":"ראב\"ד בקראקא.","s":"אוצר הרבנים 7577,7641; צונץ-קראקא"},{"i":25995,"n":"כץ, יואל מאוסטרהא","f":"נחמן מאוסטרהא","dt":"תקסא - ג אלול","dp":"אוסטרהא","b":"נכד ר בצלאל כץ מאוסטרהא ונינו של ה\"סמיכת חכמים\". רב בביחוב, דיין באוסטרהא מאנשי קלויז הגדולה. הסכים על \"משנת חכמים\", ועוד. חתם הרבה בפנסקי הח\"ק. (ב\"דעת קדושים\" נכתב עליו כנראה בטעות כי היה ממשפחת רפפורט ובנו של ר נחמן מויסוקי).","s":"אוסטרהא קצב"},{"i":25996,"n":"כץ, יואל מסטניסלב ואנטניא","f":"יצחק אייזיק מאוסטרהא","dt":"תקל - יז כסלו","b":"מצאצאי מהר\"ל מפרג. חתן ר דב בר מצורטקוב-(בן ר אברהם סגל מהארחוב ולבוב). רב באנטניא, התקבל לסטאניסלב וטבע בדרך בנהר. בניו: ר יצחק איזיק הכהן מקוריץ בעל \"ברית כהונת עולם\", ר משולם הכהן מזורוונע קוריץ, ולבוב בעל \"פתחי נדה\", ר יהודה ליב הכהן מבולחוב,וסטרי.","s":"אוצר הרבנים 7839; אוסטרהא קעו"},{"i":25997,"n":"כץ, יואל מערדעד","f":"מאיר הכהן מנווטלנפלו","k":"בעל טירת כסף","bt":"תרנב","bp":"תרנב","dt":"תשד - ט סיון","b":"תלמיד השב\"ס, ור שלמה זלמן עהרנריך משימלויא, ר יהודה גרינוולד בסטמר, ר שמעון גרינפלד בסמיהאי, ועוד. חתן ר יהודה ליב וינברגר מניגערשט. דיין בניגרעשט ליד חותנו ורב בטשערטעז הסמוכה-השייכת לגליל חותנו והתגורר בניגרשט, רב בערדעד(=ארדד=ארדוד)-ליד סטמר. נחשב למומחה בעניני גיטין ועגונות, והיה מסדר הגיטין של העיר סטמר (משום שבעיר סטמר לא נערכו גיטין בגלל בעיה עם שם העיר המדוייק - סאטו מארה). מקורב לציונות. נספה בשואה. חיבר \"טירת כסף\", \"פרדס רמונים\", ועוד. בנו ר פנחס חיים כץ רב בערדעד לצדו. וחתנו ר שמואל טיטלבוים אב\"ד ניגרעשט. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","s":"אוצר הרבנים 7840; החת\"ס ותלמידיו; טרנסילבניה; הונגריה; אוצר כתבי עת-לוין"},{"i":25998,"n":"כץ, יוזאפ מהנובר","b":"רב בהנובר,אלטונא-תק\"כ","s":"אוצר הרבנים 8016"},{"i":25999,"n":"כץ, יוזמן מניישטט","b":"מגדולי חכמי אשכנז,מרביץ תורה בנוישטט-ר\"כ","s":"אוצר הרבנים 7805"},{"i":26000,"n":"כץ, יום טוב","k":"הו\"ל עולת שבת","b":"הוציא לאור \"עולת שבת\" לר יואל ן שועיב. ?? לא באוצר ??","s":"איטליה גירונדי-י סג"},{"i":26001,"n":"כץ, יונתן מסעליש","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט.","s":"אוצר כתבי עת-לוין"},{"i":26002,"n":"כץ, יוסף (ראה גם ויס, יוסף)","b":"סופר סת\"ם ברדיחוב-תרלד.","s":"וונדר-גליציה ח\"ג"},{"i":26003,"n":"כץ, יוסף יוזפא מוינה","f":"יהושע פאלק- הסמ\"ע","k":"בעל כתנת פסים","dt":"שצט - יח אדר","b":"מחכמי וינה. הו\"ל ספרי אביו \"דרישה ופרישה\" עם הערות ממנו בשם \"כתנת פסים\" לובלין שצה. בנו - ר שלמה בעל תפארת הקדש.","s":"אוצר הרבנים 8366; פין-כנסת ישראל; בובר-לבוב"},{"i":26004,"n":"כץ, יוסף יצחק מדומברובה","f":"אברהם אבלי-זכרון אבר","bt":"תקצז","b":"נתייתם בילדותו וגדל אצל ר ליבוש מטומשוב. נסמך מאת: ר יצחק שמלקיש מלמברג. חתן ר נחום צבי-חתנו של ר חיים דוד קלוגר מגריידינג. רב בדומברובה?(=דאבראטוואר-ליד קאמניקא)-תרך, יאנוב-תרלו.","s":"אוצר הרבנים 8882; אהלי שם"},{"i":26005,"n":"כץ, יוסף מאמשטרדם","b":"דיין באמסטרדם-תס\"ט","s":"אוצר הרבנים 8367"},{"i":26006,"n":"כץ, יוסף מהנובר","b":"חתן ר אליהו פאלק מהמבורג. רב בהנובר והמדינה-תנט.","s":"אוצר הרבנים 8368; דוקס-אוה למושב"},{"i":26007,"n":"כץ, יוסף מירושלים","b":"מגדולי ירושלים-תק\"כ","s":"אוצר הרבנים 8365"},{"i":26008,"n":"כץ, יוסף מפוליען-ריסקובה","b":"רב בפוליען-ריסקובה-תרלה.","s":"הונגריה"},{"i":26009,"n":"כץ, יוסף מקולומיי","b":"רב בקולומיי-ש\"צ","s":"אוצר הרבנים 8370"},{"i":26010,"n":"כץ, יוסף מקראקא","f":"מרדכי גרשון מוינה","k":"בעל שארית יוסף","r":"רב ופוסק - רב בקרקוב","bt":"רעא","bp":"קרקוב","dt":"שנא - ג שבט","dp":"קראקא","b":"לאחר פטירת אביו גדל אצל ר יואל שנשא את אמו. חתן ר משה עברליש, גיסו של הרמ\"א. מגדולי דורו, אב\"ד וראש ישיבה בקראקא כ-50 שנה. בניו: ר אהרן מנחם מקראקא, ר תנחום מקראקא, ר אהרן משה מקראקא, חתניו - ר שלמה חריף מלבוב, . מחותנו - ר דוד זלצבורג. דודו(=בעל אחות אמו) - ר משה יפה מקראקא (זקנו של הב\"ח).","s":"אוצר הרבנים 8364; אוסטרהא רסא; פין-כנסת ישראל; שם הגדולים השלישי; צונץ-קראקא; פין-קריה נאמנה; יומא דהילולא","bk":[["שארית יוסף (שו\"ת)",""]],"e":"רע\"א~-שנ\"א","rb":"קרקוב"},{"i":26011,"n":"כץ, יוסף מראקישוק","f":"מאיר","b":"רב הקהילה החסידית בראקישוק, ובנו ר בצלאל על מקומו אחריו.","s":"ליטא"},{"i":26012,"n":"כץ, יוסף פנחס ממאדין","b":"שו\"ב במאדין-תרנט, קנטשוגה-תרסג.","s":"וונדר-גליציה ח\"ג"},{"i":26013,"n":"כץ, יוסף ראובן הלוי מגלובוק","f":"חיים מפומפיאן-עונג ח","bt":"תרלז","bp":"גודלווה(=גודלאווה)","dt":"תשא","b":"חתן ר מיכל יפה מנישינטא-פלך קובנא. רב בוישינטה(=נישינטא)-תרסג, אב\"ד גלובוק. חבר \"המזרחי\" בוילנא. נספה בשואה.","s":"ליטא; אהלי שם"},{"i":26014,"n":"כץ, יוסף שמואל מניקלשבורג","bt":"תקך - בערך","b":"תלמיד בעל מחצית השקל, ר מרדכי בנט - והדפיס את תשובותיו. דיין בניקלשבורג מעל 40 שנה. בנו - ר משה ליב מניקלשבורג.","s":"מתוך קטלוג"},{"i":26015,"n":"כץ, יחזקאל מזולקוא","f":"ר\"מ","b":"מחכמי זולקוא, נזכר-תנא בין חמשה שומרי התקנות ונקרא האלוף הראש.","s":"בובר-זולקוא"},{"i":26016,"n":"כץ, יחזקיה הכהן מוורבוי ובעלעד","k":"בעל מגדנות חזקיהו","b":"מקובל, מו\"צ בוורבוי, יעמרינג?, רב בבעלעד-תקץ ומחוז רעבוי. התכתב עם החת\"ס. חתנו - ר זליג ליב פנחס יהודה פייפר.","s":"אוצר הרבנים 9116"},{"i":26017,"n":"כץ, יחיאל חיים מקרליפקה","b":"רב בקרליפקה.","s":"וונדר-גליציה ח\"ג"},{"i":26018,"n":"כץ, יחיאל מזלין","b":"רב בזלין-תרלד.","s":"וונדר-גליציה ח\"ג"},{"i":26019,"n":"כץ, יחיאל מיכל","b":"פרסם מאמרים ב\"זהב הארץ\" - ירושלים תרסט.","s":"אוצר כתבי עת-לוין"},{"i":26020,"n":"כץ, יחיאל מיכל מוילנא","f":"שמעון","bt":"תרנז","bp":"אולשאן","dt":"תשב","dp":"פונארי","b":"תלמיד ישיבות שטוצין, גרודנא, סלובודקה, וחברון. חתן ר שלמה הכהן מוילנא. רב בוילנא. נספה בשואה. מתורתו בספר אחיו ר ראובן כץ - \"דגל ראובן\".","s":"ליטא"},{"i":26021,"n":"כץ, יעקב","s":"אוצר הרבנים 9680"},{"i":26022,"n":"כץ, יעקב בעל התוספות","k":"ר' יעקב כץ הזקן","dt":"קט","b":"עק\"ה,מגדולי התורה באשכנז בגורטנהויזן","s":"אוצר הרבנים 9683"},{"i":26023,"n":"כץ, יעקב יהודה מרימנוב","f":"זאב וולף","dp":"קליינוארדין","b":"רב ברימנוב.","s":"וונדר-גליציה ח\"ג"},{"i":26024,"n":"כץ, יעקב יוסף מאנאד","f":"יהודה אריה ליב","bt":"תקץ","bp":"טיבאלד דאראץ","dt":"תרן - כג אדר","dp":"אנאד","b":"תלמיד הכת\"ס, ור שמואל שלזינגר קיצע משאהל, ור יהושע מורפעלעט. חתן ר מאיר כהן. רב באברהאם. רב בשאהל על מקום רבו (שנאלץ להיכנס לעסקי חותנו). רב בנעמעשביק(=נאמאשי), רבה הראשון של אנאד-תרך, חתנו ר חיים מאיר שיק על מקומו אחריו. בנו - ר אליהו קאהן מואראש-נאמעני.","s":"אוצר הרבנים 10108; החת\"ס ותלמידיו; הונגריה"},{"i":26025,"n":"כץ, יעקב מאוסטיטשקי","b":"רב באוסטיטשקי. חתן המגיד הקדוש ר בנימין ב\"ר אבא הכהן ממנוסטרישץ.","s":"וונדר-גליציה ח\"ו"},{"i":26026,"n":"כץ, יעקב מאלטונא","f":"משה","bt":"תקסח","bp":"אלטונא","dt":"תרסו - יא תשרי","dp":"אלטונא","b":"ממשפחת ר שמואל עלקאן בעל \"מקום שמואל\", ומצאצאי ר ברוך כהנא. תלמיד החת\"ס. רב באלטונא-תרז וראב\"ד (באופן זמני) שם-תרלג על מקום ר יעקב עטלינגר - בעל \"ערוך לנר\". מתורתו במשניות אלטונא תרה, בשו\"ת החת\"ס, ב\"שומר ציון\". בנו - ר אהרן כץ - רב באיכנהויזן (ביירען). גיסו - ר ישעיה הולנדר.","s":"החת\"ס ותלמידיו; אוצר הרבנים 9672; דוקס-אוה למושב"},{"i":26027,"n":"כץ, יעקב מזולקוא (פלק)","f":"שמואל אלכסנדר מלבוב","b":"נכד הסמ\"ע. מחכמי זולקוא, חתם-תם על תקנה בענין הכנסות השמשים בקהלה.","s":"בובר-זולקוא"},{"i":26028,"n":"כץ, יעקב מפלאצק","f":"יהודה ליב כץ","b":"רב בפלאצק-תץ על מקום אביו.","s":"אוצר הרבנים 9681"},{"i":26029,"n":"כץ, יעקב מצעהלים ופרשבורג","b":"מחכמי פרשבורג, חתם-תקסז על כתב מנוי רבנות לחת\"ס.","s":"אבני בית היוצר-וייס"},{"i":26030,"n":"כץ, יעקב מקליקול","f":"ישראל","bt":"תרכג","bp":"רומשישוק-ליטא","dt":"תרפג - י תשרי","dp":"וילדינגן-גרמניה","b":"מגדולי המוסר בליטא. תלמיד ישיבות קובנא, וולוזין, קלם. תלמיד ר יצחק בלזר. ר\"מ בישיבת ר הירשל בסלובודקה, משפיע רוחני בישיבת טלז-תרס, רב בקליקול-תרסו, נדד עם ישיבה מריגא להומל וכיהן בה כר\"מ. רב בקליקול-תרף, זאגר חדש על מקום ר בן ציון פלדמן. מבניו: ר שלמה כצ'ס מפתח תקוה, ר דב כץ בעל \"תנועת המוסר\".","s":"ליטא"},{"i":26031,"n":"כץ, יעקב משה מקרוסנו","b":"רב בקרוסנו-תרכו.","s":"וונדר-גליציה ח\"ג"},{"i":26032,"n":"כץ, יעקב צבי מסובוסלו ואמשטרדם","f":"שלמה מסובוסלוי","k":"בעל לקט הקמח החדש","dt":"תשכד - ו כסלו","b":"נכד ר יעקב צבי מסאביסלוי. רב בסובאסלו(=סאביסלוי)-תרף על מקום אביו, סאראסלויא, ניצל מהשואה ואחריה רב הקהלה החרדית באמשטרדם. פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!).","s":"אוצר הרבנים 10284; הונגריה; אוצר כתבי עת-לוין; ברוין-אנשי מופת","bk":[["לקט הקמח החדש [על שו\"ע או\"ח]",""]]},{"i":26033,"n":"כץ, יעקב קופל מסטאנוב","b":"רב בסטאנוב-תקט\"ז","s":"אוצר הרבנים 10304"},{"i":26034,"n":"כץ, יצחק איזיק מאוסטרהא","f":"בצלאל אב\"ד אוסטרהא","dt":"תצה - ו כסלו","dp":"אוסטרהא","b":"נכד ר נפתלי כץ מאוסטרהא. חתן ר יהודה ליב איטינגא מלבוב, ובזיוו\"ש חתן קרובו ר יהודה ליב בן ר אשר ענזיל מאוסטרהא. תלמיד ר יעקב עמדין (היעב\"ץ) בלבוב. רב באוסטרהא על מקום חותנו שעבר לסלוצק-תפב בערך. הסכים על \"עולת אהרן\"-תצא. בנו ר יואל כץ מאנטאני וסטניסלב. חתנו - ר נחום מצויזמיר.","s":"אוצר הרבנים 11181; אוסטרהא מ,מד; ברוורמן-אנשי שם"},{"i":26035,"n":"כץ, יצחק איזיק מפרוסטיץ","f":"נפתלי","b":"יש אומרים שלא היה בן כזה.","s":"בובר-לבוב"},{"i":26036,"n":"כץ, יצחק איזיק מקראקא","dt":"תקעב - י כסלו","b":"הדיין הגדול בקרקא","s":"אוצר הרבנים 11185"},{"i":26037,"n":"כץ, יצחק איזיק משערשוב","f":"יעקב כהן גדול מואלפא","k":"בעל שערי יצחק","dt":"תריח - י אדר","b":"שם משפחתו גם אלכסנדרובסקי (ע\"ש שושלת הכהונה של משפחתו עד אלכסנדר הכהן מזמן שמעון הצדיק). תלמיד ר משה משרשקוב(=שארשוב), ור נח מלכוביץ. רב בשארשוב. בניו - ר ישראל שלמה זלמן אלכסנדרובסקי משארשוב, ר צבי אריה.","s":"אוצר הרבנים 11184; אלפסי; ברוורמן-אנשי שם"},{"i":26038,"n":"כץ, יצחק הכהן מקושטא או שלוניק","f":"עקיבא מספרד","b":"רב במגרש גלאטי ופערא בקושטא-רכ? בנו - ר עקיבא כץ מאויבן ופרג.","s":"אוצר הרבנים 10722; %"},{"i":26039,"n":"כץ, יצחק הכהן מריפין","b":"פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו.","s":"אוצר כתבי עת-לוין"},{"i":26040,"n":"כץ, יצחק הקטן מלובלין","b":"עק\"ה,רב בלובלין-שמ\"ז","s":"אוצר הרבנים 10723"},{"i":26041,"n":"כץ, יצחק מארץ ישראל","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ.","s":"אוצר כתבי עת-לוין"},{"i":26042,"n":"כץ, יצחק מבומסלא","f":"בנימין כץ מחוקק","dt":"שצד - ז שבט","b":"רב בבומסלא","s":"אוצר הרבנים 10729"},{"i":26043,"n":"כץ, יצחק מזולקוא","f":"שלמה","b":"מחכמי זולקוא, חתם-תפב עם ראשי הקהלה, ובשנת תקג על בחירת ראשי העדה.","s":"בובר-זולקוא"},{"i":26044,"n":"כץ, יצחק מטוטשין","f":"אברהם דב בערשי למברג","b":"חתן הרב גולובה מטוטשין. רב בטוטשין על מקום חותנו. נספה בשואה. פרסם ב\"טאגבללאט\" ו\"איד\".","s":"וונדר-גליציה ח\"ג"},{"i":26045,"n":"כץ, יצחק מלבוב","b":"רב בלבוב-ש\"מ","s":"אוצר הרבנים 10732"},{"i":26046,"n":"כץ, יצחק מסטנוביץ ופינטשוב","f":"דב בריש מפינטשוב","bt":"תקג","dt":"תקלד - כה שבט","b":"מצאצאי בעל הש\"ך. רב בסטאבניץ,פינטשוב. בנו ר דוד זאב רפפורט. (באהלי שם - הוא אחיו של ר אברהם אבלי בעל \"כתר כהונה\" - והוא שהיה רב בסטנביץ ופינטשוב)","s":"אוצר הרבנים 10727; אהלי שם"},{"i":26047,"n":"כץ, יצחק מפודהייץ","f":"משה","k":"הו\"ל גבורות אנשים","b":"נכד בעל הש\"ך, ונכד ר מאיר בן שאול וייל - אב\"ד בריסק. חתן ר משה סגל מזאבריז-בנו של ר למל מוילנא. רב בפודהייץ, (סטאבניץ, אפטא-תנז?). לפי מרקוביץ - חתן ר משה בן מרדכי ז\"ק מונגרוב ומינסק.","s":"אוצר הרבנים 10726; אהלי שם; מינסק-איזנשטט"},{"i":26048,"n":"כץ, יצחק מפינטשוב","dt":"תטו","b":"רב בפינטשוב. נרשם בין מצבות קראקא אבל לא נפטר שם.","s":"אוצר הרבנים 10731; צונץ-קראקא"},{"i":26049,"n":"כץ, יצחק מפרג - הזקן","f":"שמשון","k":"בעל פירוש למדרש","bp":"פרג","dt":"שפד - יב-ד סיון","dp":"פרג","b":"מצאצאי ר עקיבא מאובן. חתן מהר\"ל מפרג. רב בניקלשבורג ומדינת מורביה, וינה, ראב\"ד בפרג. בתו - חוה - מלומדת כאחד הגאונים המפורסמים - אשת ר שמשון בכרך. בניו: ר חיים הכהן מפוזנא, ר נפתלי כץ מפינסק ולובלין. מנכדיו - ר יאיר בעל חות יאיר.","s":"אוצר הרבנים 10728; אוסטרהא; פין-כנסת ישראל"},{"i":26050,"n":"כץ, יצחק מפרג - הנכד","f":"נפתלי מפרג ולובלין","dp":"לובלין","b":"דרשן בפרג, רב בסטעפין ובנו ר נפתלי על מקומו אחריו, דרשן ור\"מ בלובלין-תמ.","s":"אוצר הרבנים 10724; אוסטרהא"},{"i":26051,"n":"כץ, יצחק מקראקא","f":"שלום","dt":"שסא - כד טבת","dp":"קראקא","b":"מחכמי קראקא.","s":"צונץ-קראקא"},{"i":26052,"n":"כץ, יקותיאל זלמן מקלצק","b":"מגדולי חכמי קלצק-תק\"פ","s":"אוצר הרבנים 11551"},{"i":26053,"n":"כץ, ירחמיאל הכהן מאוסטרהא","f":"שלמה זלמן","dt":"תצו - ב חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אחיו של ר יהודה ר יוקבת כץ. נפטר צעיר.","s":"אוסטרהא סו"},{"i":26054,"n":"כץ, ישכר בער משברשין וחברון","f":"נפתלי","k":"בעל מתנות כהונה","bp":"שברשין (פולין)","dp":"חברון","b":"מחכמי פולין, למד בבית מדרש הרמ\"א. רב בשעברשין-שנז, עלה לארץ-שם בערך, היה מתלמידי ר משה קורדובירו, רב בחברון. חיבר \"מתנות כהונה\" קראקא שמו, ועוד. (לדעת לונץ - לא הגיע לארץ). נכדו - ר אברהם בן אליעזר בעל \"אורי וישעי\" הו\"ל את ספרו \"מראה כהן\".","s":"גליס; אוצר הרבנים 12364; פין-כנסת ישראל; ירושלים לזכר לונץ (שם השערה כי כלל לא הגיע לארץ ישראל)"},{"i":26055,"n":"כץ, ישעיה מדוקלא","b":"רב בדוקלא-תרנו.","s":"וונדר-גליציה ח\"ג"},{"i":26056,"n":"כץ, ישעיה מוורצקי","b":"דומ\"צ בוורצקי-תר\"י","s":"אוצר הרבנים 11715"},{"i":26057,"n":"כץ, ישעיה מיאקא","b":"רב ביאקא-תקפב, נזכר אצל החת\"ס שהשיב לו ולחבריו ר משה אריה ליב מגלנטא(=גלאנדע), ור יוסף מסערער.","s":"אוצר הרבנים 11716; רוזניס-תורכיה-ו"},{"i":26058,"n":"כץ, ישעיה מלובלין","f":"יצחק כץ","b":"מחכמי לובלין-ת\"פ","s":"אוצר הרבנים 11718"},{"i":26059,"n":"כץ, ישראל מואדיסלב","b":"רב בוואדסלב-תקס\"ז","s":"אוצר הרבנים 11950"},{"i":26060,"n":"כץ, ישראל מלמברג","f":"אברהם דב בערשי למברג","k":"יה\"ן","b":"מעסקני המזרחי בלמברג. השתתף ב\"בית יעקב\"-לודז - בשמו הספרותי יה\"ן. ניצל מהשואה ועבר לניו יורק. עלה לירושלים.","s":"וונדר-גליציה ח\"ג"},{"i":26061,"n":"כץ, ישראל מסערדאוהל","dt":"תרז - בערך","b":"תלמיד החת\"ס. מחכמי סערדאוהל. והאב\"ד ר יהודה אסאד מכנהו בשם \"קדוש ישראל\". חתנו - ר מנחם דונט מנייטרא.","s":"החת\"ס ותלמידיו"},{"i":26062,"n":"כץ, ישראל מפומפיאן","f":"יהודה","b":"רב בפומפיאן-ליטא.","s":"ליטא"},{"i":26063,"n":"כץ, ליפמן מסאבודקה","b":"רב בסאבאדקה-תקע\"ב","s":"אוצר הרבנים 12693"},{"i":26064,"n":"כץ, מאיר הכהן ממוהילוב ודובנא","f":"משה אשכנזי מדאנהויזן","k":"בעל גבורת אנשים","r":"אב\"ד אמסטוב","dt":"תג - ג כסלו","dp":"דובנא","b":"רב באמסטיבאווי(=אמסטובאווי), מאהילוב(=מוהילוב), דובנא-תב על מקום ר צבי הירש בן עוזר, ור יהודה החסיד (שנהרג בגזרות תח) על מקומו אחריו. בניו - ר שבתי בעל הש\"ך, ר יונה נחום מסוכטשוב, חתנו - ר יצחק א\"ש ונכדו ר מאיר בעל \"פנים מאירות\".","s":"אוצר הרבנים 12862; שם הגדולים השלישי; ברוין-אנשי מופת; פין-קריה נאמנה; תוספת להמודיע כא חשון תשעד עמוד כט","bk":[["שאלות ותשובות - נדפסו בתוך ספר גבורת אנשים",""]]},{"i":26065,"n":"כץ, מאיר מחעלמא ובלז","f":"משה ירמיה מנראל","b":"אחיו של ר טוביה בעל \"מעשה טוביה\". רב בחעלמא, בעלזא-תס?. בנו - ר אברהם רפפורט. (בלבול עם ר מאיר בן משה ירמיה רפפורט - ראה בערכו).","s":"אוצר הרבנים 12863,(13002)"},{"i":26066,"n":"כץ, מיכל מוילנא","dt":"תשג","b":"רב בוילנא.","s":"אוצר הרבנים 13172"},{"i":26067,"n":"כץ, מנחם","b":"רב דמדינת רוסיה-תקע\"א","s":"אוצר הרבנים 13257"},{"i":26068,"n":"כץ, מנחם מבריסק","f":"בנימין","b":"אב\"ד בריסק-תנה. הסכים על \"נפתלי שבע רצון\". אחיינו - ר אליהו בעל יד אליהו (שנפטר בחברון) המזכירו בספרו.","s":"בריסק-עיר תהלה"},{"i":26069,"n":"כץ, מנחם מואנילוב","b":"דיין בואנילוב, חתם-תלג עם ר אהרן בן צבי הירש סגל, ר שניאור פיבש בן דוד הקדוש.","s":"אוצר הרבנים 13256; בובר-לבוב"},{"i":26070,"n":"כץ, מנחם מנדל מאונסדורף","b":"ראב\"ד באונסדורף-תר\"כ","s":"אוצר הרבנים 13468"},{"i":26071,"n":"כץ, מנחם מנדל מזולקוא","f":"יהודה ליב","b":"מחכמי זולקוא, חתם-תסד בפנקס הקהלה.","s":"בובר-זולקוא"},{"i":26072,"n":"כץ, מנחם מנדל מפרשבורג","f":"אברהם מפרשבורג","dt":"תרכז - יב אייר","dp":"פרשבורג","b":"תלמיד החת\"ס. סופר הבי\"ד ונאמן הקהלה בפרשבורג במשך מז שנה, בנו ר פנחס על מקומו אחריו. בנו ר יהודה ליב בעל \"יושר דברי אמת\".","s":"החת\"ס ותלמידיו"},{"i":26073,"n":"כץ, מרדכי","b":"רב-שנת ש\"ס","s":"אוצר הרבנים 13869"},{"i":26074,"n":"כץ, מרדכי","bt":"1885","bp":"שקומיאן-ליטא","dt":"1954","b":"תלמיד ישיבות וילקומיר, וילנא. פעיל בתנועת ס.ס. בוילקוביסק. פרסם ב\"הצפירה\", \"הזמן\", ועוד. היגר לארה\"ב דרך יפן, פרסם מאמרים בעתוני התקופה.","s":"ליטא"},{"i":26075,"n":"כץ, מרדכי ברוך","f":"אברהם דב בערשי למברג"},{"i":26076,"n":"כץ, מרדכי גרשון מוינה","f":"חיים מקושטא","b":"ממגורשי וינה. דיין בקראקא-שנת ש'. בנו - ר יוסף מקראקא בעל \"שארית יוסף\".","s":"אוצר הרבנים 14093; שם הגדולים השלישי"},{"i":26077,"n":"כץ, מרדכי הכהן מברודא ופוזנן","f":"נפתלי","k":"יעקב מרדכי (באוצר)","b":"רב בברוד-מהרן, פוזנא. חתן ר משולם-חתנו של הרבי ר השל. חתנו היה ר יעקב עמדין-היעב\"ץ. הסכים על \"אבן השהם\". (ראה גם: יעקב מרדכי מפוזנא).","s":"אוצר הרבנים 10244; אוסטרהא כא-ד; בובר-לבוב"},{"i":26078,"n":"כץ, מרדכי מאפטא","f":"נתן נטע כץ","b":"רב באמסטיבווא,אפטא-ת\"נ","s":"אוצר הרבנים 13871"},{"i":26079,"n":"כץ, מרדכי מבירטש","b":"רב בבירטש-תרלז.","s":"וונדר-גליציה ח\"ג"},{"i":26080,"n":"כץ, מרדכי מוונגרוב","f":"מהר\"מ","b":"מחכמי וונגרוב.","s":"מתוך קטלוג"},{"i":26081,"n":"כץ, מרדכי מלבוב","f":"דוד","dt":"שצא - א ניסן","dp":"לבוב","b":"ר\"מ בלבוב. היה בין המשיבים בענין אילנות בבית העלמין יחד גדולי דורו ובהם בעל תוי\"ט. נזכר ב\"איתן האזרחי\", וב\"משאת בנימין\".","s":"אוצר הרבנים 13870; מצבות קדש-לבוב לה; בובר-לבוב"},{"i":26082,"n":"כץ, מרדכי מלבוב","f":"שמרל מלבוב","dt":"תסג - ד כסלו","dp":"לבוב","b":"מחכמי לבוב. גיסו של ר יעקב יהושע פאלק בעל פני יהושע (?).","s":"מצבות קדש-לבוב"},{"i":26083,"n":"כץ, מרדכי מפרוינקירכן","dt":"תקלא - יז אייר","b":"רב בפרוינקירכן","s":"אוצר הרבנים 13866"},{"i":26084,"n":"כץ, מרדכי מפרוסטיץ וזולקוא","f":"משה","k":"בעל דרך ים התלמוד","b":"הו\"ל חידושי מהרש\"א עם תוספות ממנו בשם \"דרך ים התלמוד\" זולקוא תנב.","s":"בובר-זולקוא"},{"i":26085,"n":"כץ, משה","f":"יהושע פאלק- הסמ\"ע","b":"חתן ר דוד בן מרדכי. רב-שנת שצה.","s":"אוצר הרבנים 14793; בובר-לבוב"},{"i":26086,"n":"כץ, משה הכהן מבריסק ולויצק","f":"מרדכי גרשון או פסח","b":"רב בקלויז השר שאול וייל בבריסק, אב\"ד סלוצק, לוצק-תכד. הסכים על \"עמודיה שבעה\" דירנפורט תנג. בניו - ר יוסף, ר יהודה ליב, חתנו - ר אברהם מלונטשיץ.","s":"אוצר הרבנים 14773; אהלי שם; בריסק-עיר תהלה"},{"i":26087,"n":"כץ, משה יהודה מסערדהאלי","f":"אשר אנשל כץ","k":"בעל ויגד משה","bt":"תרסז","dt":"תשד - כז סיון","b":"מרביץ תורה בסרדאהעלי. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר הרבנים 15429; אוצר כתבי עת-לוין"},{"i":26088,"n":"כץ, משה יונה הלוי מסרדניק","f":"חיים מפומפיאן-עונג ח","dt":"תרצו - חשון","b":"חתן הגביר ר נתן ליב שלאווא. רב בסרדניק. פרסם מאמרים ב\"חכמי ליטא\" - קאלואריא תרמה.","s":"אוצר הרבנים 15457; ליטא; אוצר כתבי עת-לוין; אהלי שם"},{"i":26089,"n":"כץ, משה ליב הכהן מניקלשבורג","f":"יוסף שמואל מניקלשבור","dt":"תרנ","b":"תלמיד אביו-שהיה דיין בניקלשבורג, ר יהודה אסאד, ר נחום טריבטש מניקלשבורג. מגיד, ראב\"ד בניקלשבורג. חיבר שו\"ת בכת\"י. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך. נספד מאת ר חזקיה פיבל פלויט.","s":"אוצר הרבנים 15532; אוצר כתבי עת-לוין"},{"i":26090,"n":"כץ, משה מביאליסטוק וירושלים","f":"אברהם יהושע","k":"בעל אשי משה","b":"מחכי ביאליסטוק, עלה לירושלים."},{"i":26091,"n":"כץ, משה מדובנא","f":"יוסף","dt":"תמד - ט סיון","dp":"לבוב","b":"מרביץ תורה, רב בדובנא על מקום ר נחמן רפפורט, ור ישראל בן מרדכי יאליס על מקומו אחריו.","s":"אוצר הרבנים 14789,14287; מצבות קדש-לבוב; בובר-לבוב; ברוין-אנשי מופת"},{"i":26092,"n":"כץ, משה מזולקוא","f":"יצחק","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה.","s":"בובר-זולקוא"},{"i":26093,"n":"כץ, משה מטור-טארבש","f":"אהרן שלמה מאלמאשד","k":"בעל דברי משה","dt":"תרנה - ד אדר","b":"גיסו של ר שמלקא קליין מסעליש. חתן ר אהרן פריד מקאסני, רבה הראשון של טור-טרבש-ליד האלמין-תרל שהיה בגליל סעליש אצל גיסו. רבות מתשובותיו ב\"אהל אברהם\" למחותנו - ר אברהם קרפלס - מונקטש תרנט. מתורתו ב\"מגד ירחים\" - סיגט תרנח.","s":"אוצר הרבנים 14796; טרנסילבניה; הונגריה; אוצר כתבי עת-לוין"},{"i":26094,"n":"כץ, משה מטיקטין ומאקובה","b":"רב בטיקטין, מאקובה. מחותן עם ר אשר קמץ - (בנו - ר משה מפארידן בעל \"פני אריה\" היה חתנו של ר אשר קמץ). ונקראו הוא ומחותנו \"הגאונים מטיקטין\".","s":"מתוך קטלוג"},{"i":26095,"n":"כץ, משה מיאנוב","f":"ליב","b":"רב ביאנוב-תקפג.","s":"וונדר-גליציה ח\"ג"},{"i":26096,"n":"כץ, משה מלבוב","f":"דוד צבי","dt":"תעט - יט חשון","dp":"לבוב","b":"ר\"מ בלבוב","s":"אוצר הרבנים 14791; מצבות קדש-לבוב; בובר-לבוב"},{"i":26097,"n":"כץ, משה מפודהייץ","f":"שבתי - בעל הש\"ך","k":"בעל נקודות הכסף","dt":"תמו - יא חשון","b":"חתן ר מנחם מנדל מרגליות. מגדולי דורו, רב בפודהייץ, במלחמת התורכים נשרפה הקהילה ונשבתה, נסע לפפד\"א. יש אומרים שלאחר פטירתו נישאה אלמנתו לר משה זאב ממינסק.","s":"אוצר הרבנים 14792; אהלי שם; פין-קריה נאמנה"},{"i":26098,"n":"כץ, משה מפרמישלא ומזיבוז","f":"ישעיה","k":"בעל פני משה","b":"אב\"ד במזיבוז, ר\"מ בפרמישלא. דודו - ר נפתלי בעל סמיכת חכמים."},{"i":26099,"n":"כץ, משה מרדומישל","f":"דוד צבי","b":"רב ברדומישל על מקום אביו, קלן-תרצז, שוב ברדומישל-תרצח. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":26100,"n":"כץ, משה מרדומישלא","b":"מתלמידי החוזה מלובלין והנועם אלימלך.","s":"וונדר-גליציה ח\"ג"},{"i":26101,"n":"כץ, משה פנחס מקינצק","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","s":"אוצר כתבי עת-לוין"},{"i":26102,"n":"כץ, משה קאפיל מרומנאווקע","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח.","s":"אוצר כתבי עת-לוין"},{"i":26103,"n":"כץ, משלם פיבל מגריידינג","b":"אב\"ד גריידינג-תרכה.","s":"וונדר-גליציה ח\"ג"},{"i":26104,"n":"כץ, נחמיה מארה\"ב","f":"יעקב משה קסטנביץ","bt":"תרסה","bp":"ליובאן-פלך מינסק","b":"תלמיד ישיבת סלוצק, נסמך מאת: ר אליעזר זילבר מסינסינטי, ר שמעון זיויץ, ר חיים הירש רובינשטין, ר שמעון יצחק פינקלשטין. חתן ר יצחק משה סילברמן מטולדו-ארה\"ב. היגר לארה\"ב וכיהן כרב בטולדו, ועוד. חבר אגודת הרבנים באמריקה, תנועת המזרחי, פעיל צבור.","s":"אנשי שם-אמריקה"},{"i":26105,"n":"כץ, נחמן מאורלי","f":"בנימין בישקא מאורלי","dt":"תקעה","b":"רב באורלי(=אורלע). נכדו הו\"ל מתורתו ומתורת אחיו - ר שבתי משנאדאווה ואורלי בשם \"שבת אחים\". נספד ע\"י ר משה זאב מביאליסטוק בספרו \"אגודת אזוב\".","s":"מוריה 21-י-יב"},{"i":26106,"n":"כץ, נחמן מבריסק","f":"שלמה","b":"מחכמי בריסק, חתם-שצט על תקנות.","s":"בריסק-עיר תהלה"},{"i":26107,"n":"כץ, נפתלי הרץ","b":"תשובה אליו ממהר\"ם פדובה - שכינהו \"אהובי עמיתי ...\"","s":"איטליה גירונדי-נ כא"},{"i":26108,"n":"כץ, נפתלי הרץ מזאמושט","k":"בעל נפתלי אילה שלוחה","b":"רב בזאמוטשט-ת\"מ","s":"אוצר הרבנים 16216"},{"i":26109,"n":"כץ, נפתלי מאוסטרהא - הזקן","b":"חתן ר יהונתן מפינסק. ר\"מ בגלוגא, אוסטרהא-תקיד. תלמידו - ר אליעזר הלוי הביא מחדושיו בספרו \"עדות ביהוסף\".","s":"אוצר הרבנים 16123; איטליה גירונדי-נ ח"},{"i":26110,"n":"כץ, נפתלי מאוסטרהא ופוזנא הנכד","f":"יצחק מפרג ולובלין","k":"בעל סמיכת חכמים","dt":"תעט - כד שבט","dp":"קושטא","b":"נכד ר נפתלי כץ מלובלין, נינו של המהר\"ל. חתן ר שמואל שמלקא בן מאיר ז\"ק מאוסטרהא. היה שבוי בידי הטטרים ונפדה. רב בסטעפן על מקום אביו. ר\"מ באוסטרהא ובנו ר בצלאל על מקומו אחריו, רב בפוזנא-תנא, פפד\"מ-תסד, אוסטרהא-תעד - ישב אצל בנו ר בצלאל. נתקבל ראב\"ד צפת, עלה לארץ-תעח דרך קושטא ונפטר שם טרם הגיעו לארץ. הסכים על ספרים רבים. עוד מבניו: ר פנחס יצחק מפולדא, מרדכי מברודי ופוזנן, ר שמואל שמלקא מברסלא, ר שאלתיאל. חתניו: ר יעקב בן אליהו מפוזנא וטיקטין, ר סעדיה ישעיה קצנלנבוגן ממזריטש, ר זאב וולף מירלש בן משולם מירלש - אב\"ד המבורג, ר יהודה ליב אשקלס בן גבריאל מניקלשבורג שנפטר צעיר הוא ואשתו - והניחו בן ר חיים ור נפתלי אמצו לבן. חיבר גם \"ים כנרת\", \"בית רחל\", \"צוואת רבי נפתלי\", ועוד. ר נפתלי נאסר בפפד\"מ-תעא בגלל שריפה שהחלה בביתו והתפשטה בכל רחוב היהודים - ושוחרר - היו שריננו על הרב בענין זה. היה מהלוחמים בשבתאות ושותף לחרם על נחמיה חיון. ר מאיר אליעזר רפפורט-הורטשטין - שהיה מצאצאיו חיבר \"שלשלת הזהב\" לתולדותיו. (לפי רוזניס נפטר ב-כד אלול)","s":"אוצר הרבנים 16121; אוסטרהא כא; רבני פרנקפורט; מצבות קדש-לבוב; רוזניס-תורכיה-ה"},{"i":26111,"n":"כץ, נפתלי מיאס","dt":"תקסט - טו אדר","b":"רב ביאס","s":"אוצר הרבנים 16124"},{"i":26112,"n":"כץ, נפתלי מפרג ולובלין - הזקן","f":"יצחק בן שמשון מפרג","k":"בעל פירות גינוסר","dt":"תי - ה תשרי","dp":"לובלין","b":"נכד המהר\"ל מפרג. דרשן בפרג, רב בפרוסטיץ(=פרוסניץ), ניקלשבורג, פינסק, לובלין - בזמן ר השל-שכיהן כראש ישיבה. היה בקשר עם בעל הט\"ז שהביא ממנו בספרו, תשובות ממנו ב\"חוט השני\". בניו - ר יצחק מפרג וסטפין, ר יהודה, ר פנחס מפולדא, ר מרדכי מברודא, ונכדו - ר נפתלי בעל סמיכת חכמים. חתנו - ר שמואל זנויל מזולקוא, אחיו - ר חיים הכהן מפרג ופפד\"מ.","s":"אוצר הרבנים 16118; אוסטרהא; בית העלמין בוילנא-קלויזנר"},{"i":26113,"n":"כץ, נתן נטע ליב מפוניבז","b":"שמש ב\"קלויז גליקל\" בפוניבז. היה תלמיד חכם שסיים 200 פעם את הש\"ס. עלה לתל אביב.","s":"ליטא"},{"i":26114,"n":"כץ, נתן נטע מבריסק","f":"ישעיה כץ","b":"רב בבריסק דליטא-ת\"צ","s":"אוצר הרבנים 16431"},{"i":26115,"n":"כץ, נתן נטע מבריסק","f":"דוד","dp":"בריסק","b":"דיין בבריסק-שנות ה-תק-תר.","s":"בריסק-עיר תהלה"},{"i":26116,"n":"כץ, עמרם מלעווא","f":"אברהם אליהו משה כץ","b":"רב בלעווא-תר\"נ","s":"אוצר הרבנים 16758"},{"i":26117,"n":"כץ, עקיבא הכהן מאויבן","f":"יצחק(10722)","dt":"רנו?","b":"חתן ר אברהם קצנלנבוגן מאויבן. חותנו של ר שבתי שפטל הורביץ. היה שולחני המלך מטיאש באויבן ונקרא נשיא היהודים. נאלץ לעבור מהונגריה לבוהמיה והתישב בפרג. יסד ישיבה גדולה ולימד בה - בימי ר יעקב פולק. ניצל מעלילה גם בפרג. עלה לדוכן עם 12 בניו וחתניו הכהנים. מבניו: ר גרשון אבי משפחת הגרשוני, גרשם אבי משפחת גרשם - יסד דפוס בפרג, ועוד. (לדעת ר יוסף סמבורי -ר יצחק אביו - ממגורשי גאלאטה שבקושטא, בנו של ר עקיבא כץ משלוניקי - ממגורשי ספרד, לדעת ר\"מ וייץ - כל זה אינו נכון). (בעיר וילנא מביא שהיו לו 12 בנים ו-13 חתנים והיה עולה לדוכן ואומר כ\"ה תברכו - ולעומת זאת מביא שאותו הסיפור מסופר על ר אליעזר בן שמחה הכהן - המליץ א-12.) אחיו - ר חיים מפרג.","s":"וונדר-גליציה ח\"ו; אוצר הרבנים 16783; עיר וילנא ח\"א; %"},{"i":26118,"n":"כץ, פאלק מגלאטו בהמן","b":"רב בגלאטו-בהמן-תק\"ס","s":"אוצר הרבנים 16807"},{"i":26119,"n":"כץ, פנחס הכהן מפולדא - א","f":"נפתלי מפרג ולובלין","b":"רב בפולדא. אחיהם של ר יהודה, ר יצחק מסטפין, ר חיים מפוזנא, ר מרדכי מברודא. (אולי הוא בלבול עם ר פנחס שהיה בנו של ר נפתלי בעל סמיכת חכמים)","s":"ברוורמן-אנשי שם"},{"i":26120,"n":"כץ, פנחס חיים מארדד(=ערדעד)","f":"יואל מארדד","bt":"תרעו","dt":"תש..","b":"חתן ר יצחק צבי ליבוביץ מצ'אפ. רב בארדד אצל אביו. נספה בשואה.","s":"טרנסילבניה; החת\"ס ותלמידיו"},{"i":26121,"n":"כץ, פנחס יהודה מקיראי דרוץ","f":"אליהו מראסלוביץ","bt":"תרמט","dt":"תרפג - י אייר","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט, ר שמואל רוזנברג באונסדורף, ור יהודה גרינוולד בסטמר. חתן ר ישכר דב פרידמן מקיראי-דארוץ. דיין בכפר אלשו-סופור ליד טשאנד. רב בקיראי-דארוץ-תרפב על מקום חותנו שעבר לקרולה. נפטר צעיר.","s":"טרנסילבניה"},{"i":26122,"n":"כץ, פנחס יצחק הכהן מפולדא","f":"נפתלי","b":"רב בפולדא, קרזמיר-תצ. הסכים על \"דמשק אליעזר\". בנו ר שמשון הכהן.","s":"אוצר הרבנים 17009; אוסטרהא כא-ד"},{"i":26123,"n":"כץ, פנחס מסטניסלב","b":"דיין בסטניסלב לפני השואה.","s":"וונדר-גליציה ח\"ג"},{"i":26124,"n":"כץ, פנחס מרדומישל","f":"מאיר","b":"רב ברדומישל על מקום זקנו - ר דוד מגיד, בנו ר דוד צבי על מקומו אחריו.","s":"וונדר-גליציה ח\"ג"},{"i":26125,"n":"כץ, פסח יהודה מסעקעלהיד","f":"שבתי","bt":"תקצא","dt":"תרנה - ח אדר","b":"תלמיד הכת\"ס, רב באלמאשד, סעקעלהיד והגליל-תרכח.","s":"אוצר הרבנים 17042; החת\"ס ותלמידיו"},{"i":26126,"n":"כץ, פסח מלויצק","f":"תנחום כץ","b":"רב בלאצק(=לוצק)-שנת ת'. בנו - ר משה מסלוצק ולוצק.","s":"אוצר הרבנים 17034"},{"i":26127,"n":"כץ, צבי הירש","f":"יוסף","k":"בעל עטרת צבי","b":"רב - שנות ה-ש'-ת'. חיבר גם \"נחלת צבי\" על השו\"ע - קראקא תו.","s":"פין-כנסת ישראל"},{"i":26128,"n":"כץ, צבי הירש מזולקוא","f":"יעקב יחיאל","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה.","s":"בובר-זולקוא"},{"i":26129,"n":"כץ, צבי הירש מלבוב","f":"אברהם","b":"ספרא ודיינא בלבוב בזמן ר חיים רפפורט. חתם-תקד בפנקס הקהלה, חתם-תקיא עם ר אריה ליב רפפורט, ר יוסף בן מנחם מאניש סגל מלבוב, ועוד.","s":"בובר-לבוב"},{"i":26130,"n":"כץ, צבי הירש מצפת","b":"גבאי בקהלת הפרושים בצפת-תקעה יחד עם ר ישראל משקלוב.","s":"פרומקין-תח\"י"},{"i":26131,"n":"כץ, קויפמן מזולצבך","b":"רב בזולצבך-תק\"מ","s":"אוצר הרבנים 17596"},{"i":26132,"n":"כץ, ראובן מסטאויסק וארה\"ב","b":"רב בסטאויסק, עבר לארה\"ב וכיהן כרב בביאן-נידזאדזשע-תרפד."},{"i":26133,"n":"כץ, ראובן מפרג","k":"בעל ילקוט ראובני","r":"אדמו\"ר הראשון מסקוירא","dt":"תלג - יז ניסן","b":"מקובל,דרשן,סופר,מגדולי חכמי פרג","s":"אוצר הרבנים 17704","bk":[["ילקוט הראובני",""]]},{"i":26134,"n":"כץ, שאול מזידיטשוב","b":"רב בזידיטשוב-תרם.","s":"וונדר-גליציה ח\"ג"},{"i":26135,"n":"כץ, שאלתיאל","f":"נפתלי","s":"בובר-לבוב"},{"i":26136,"n":"כץ, שבתי מאורלא ושנאדאווה","f":"בנימין בישקא מאורלי","k":"בעל שבת אחים","dt":"תקפ - ו אלול","b":"רב בשנאדאווה, אורלע(=אורלי). נכד אחיו הו\"ל מתורתו ומתורת אחיו - ר נחמן מאורלי(=אורלא) בשם \"שבת אחים\" וילנא תקצג. בנו - ר ישראל.","s":"אוצר הרבנים 18071; מוריה 21-י-יב"},{"i":26137,"n":"כץ, שבתי מלעוורדן","dt":"תקס","b":"רב בלעווערדען","s":"אוצר הרבנים 18070"},{"i":26138,"n":"כץ, שלום שכנא מקראקא","f":"אברהם חיים","k":"בעל משפט שלום","dt":"תקצט - ב סיון","b":"דיין בקראקא. חיבר \"שלמי נזיר\" קראקא תקפא.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 18269"},{"i":26139,"n":"כץ, שלמה (שמואל) מסובאסלו","f":"משה","bt":"תריח","dt":"תרף - בערך","b":"תלמיד ר יואל אונגואר מפאקש בעל \"תשובת ריב\"א\". חתן ר אברהם אייבניץ קרפלס מגירבא בעל \"אהל אברהם\", ובזיוו\"ש חתן ר יעקב צבי ויסמן מסובאסלו. רב בגורבע-תרמא, סובאסלוי(=סאביסלוי)-תרנא על מקום חותנו. נסמך מאת: ר אהרן פריער בעל שו\"ת מהרא\"ף, ר פנחס קליין מסולעש. בנו - ר יעקב צבי בעל \"לקט הקמח החדש\" על מקומו אחריו-תרף.","s":"אוצר הרבנים 18480; אהלי שם"},{"i":26140,"n":"כץ, שלמה דב מנימוז'ה","f":"אהרן גד מנימוז'ה","dt":"תש..","b":"רב בנימוז'ה על מקום אביו-תשא. נספה בשואה.","s":"טרנסילבניה"},{"i":26141,"n":"כץ, שלמה זלמן מגרוסורדין ונ\"י","f":"יונתן בנימין","k":"בעל שב גיטין","bt":"תרנב","bp":"צ'נגר","b":"אחיו של ר אשר אנשיל מסערדאהלי. תלמיד \"ערוגת הבשם\" בחוסט, ור שמואל רוזנברג באונסדורף. חתן ר פנחס צימטבוים מגרוסורדין, וכיהן כר\"מ בישיבת \"בית שלמה\" בגרוסורדין. היגר לארה\"ב-תרצח וכיהן כרב בניו יורק-תרצה.","s":"אוצר הרבנים 18764; אמריקה; טרנסילבניה; אנשי שם-אמריקה"},{"i":26142,"n":"כץ, שלמה זלמן מלבוב","f":"שמואל","dt":"תיג - ב חשון","b":"רב בלבוב. (יש שרשמו שהיה חתן מהר\"ל מקראקא - ולדעת בובר בטעות). בנו - ר נתן הכהן ונכדו ר שלמה זלמן שחתם בפינטשוב.","s":"אוצר הרבנים 18765; מצבות קדש-לבוב; בובר-לבוב"},{"i":26143,"n":"כץ, שלמה מבריסק","f":"נתן","b":"מחכמי בריסק-שפו.","s":"בריסק-עיר תהלה"},{"i":26144,"n":"כץ, שלמה מזולקוא","f":"יוסף יוזפא בן הסמ\"ע","k":"בעל תפארת הקדש?","b":"נכד הסמ\"ע. מחכמי זולקוא, חתם-תמ על תקנת הקהל.","s":"אוצר הרבנים 18433; בובר-זולקוא"},{"i":26145,"n":"כץ, שלמה מפרוזנא","f":"ישראל","b":"אב\"ד בפרוזנא. הסכים-תקצב על \"אבות דרבי נתן\" לר אליהו בן אברהם מדליטיץ."},{"i":26146,"n":"כץ, שלמה מקראקא ושטקטשין","f":"זאב דוב כץ","dt":"תריח - יא אדר","b":"חריף,מרביץ תורה,רב בשטעקטשין,ראב\"ד בקרקא","s":"אוצר הרבנים 18479"},{"i":26147,"n":"כץ, שלמה משארוואר","dt":"תקמו - טו אב","b":"רב בשארוואר","s":"אוצר הרבנים 18478"},{"i":26148,"n":"כץ, שמואל הכהן מהעדיעס","f":"מנחם מהעדיעס","b":"תלמיד הכת\"ס, ור ישראל דוד יפה מרגליות מפעזינג.","s":"החת\"ס ותלמידיו"},{"i":26149,"n":"כץ, שמואל מאיר מצעהלים פרוסטיץ","f":"מנחם פרוסטיץ כץ מצעל","k":"בעל שם משמואל","bt":"תקץ","bp":"פרשבורג","dt":"תרלה - כט אב","dp":"צעהלים","b":"תלמיד הכת\"ס. מחכמי צעהלים. נפטר בצעירותו.","s":"החת\"ס ותלמידיו"},{"i":26150,"n":"כץ, שמואל מוינה ונציה ירושלים","f":"יוזפה כץ","k":"בעל לקט שמואל","b":"מקובל,סופר העיר בווינה,עבר לויניציאה בגירוש-ת\"ל,עלה לירושלים","s":"אוצר הרבנים 19211"},{"i":26151,"n":"כץ, שמואל מזשיבא","b":"חתן ר משה פרנקל מזשיבא. רב בזשיבא. מונטריאול.","s":"החת\"ס ותלמידיו"},{"i":26152,"n":"כץ, שמואל מנחם הלוי מפלנגאן","f":"חיים מפומפיאן-עונג ח","k":"המגיד מקורלנד","bt":"תרמח","bp":"ז'וסלי","dt":"תשיד - יב תמוז","dp":"תל אביב","b":"חתן הגביר ר פנחס מראזאליא. תלמיד ישיבית סלובודקה. רב בוילון, רוגאצ'וב, פלנגאן(=פולאנגן) (לא פלונגיאן) ובנו ר אהרן יצחק כץ על מקומו אחריו, אחרי השריפה הגדולה-תרצח דאג לשיקום העיר, עלה לארץ-תש, וכיהן כרב ודיין בתל אביב. חבוריו בהלכה נשרפו-תרצח. בנו אברהם איסר - נרצח ע\"י הערבים בחניתה במאורעות תרצו - וע\"ש נקרא ישוב בארץ.","s":"אוצר הרבנים 19597; ליטא; אהלי שם"},{"i":26153,"n":"כץ, שמואל מרדכי מבוריסלב","b":"נכד מהרם מלובלין. פוליען-ריסוקבה. חתן ר יחיאל מיכל היבנר מניזנוב-תרכט.","s":"וונדר-גליציה ח\"ג"},{"i":26154,"n":"כץ, שמואל שמלקא מברסלא","f":"נפתלי","b":"רב בברסלוי-תפד. הסכים על \"יפה מראה\". בנו ר חיים מגלוגא.","s":"אוצר הרבנים 19652; אוסטרהא כא"},{"i":26155,"n":"כץ, שמואל שרגא מאושפיצין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט.","s":"אוצר כתבי עת-לוין"},{"i":26156,"n":"כץ, שמעון מקובין","dt":"תרט - כ תמוז","b":"רב בקובין","s":"אוצר הרבנים 19875"},{"i":26157,"n":"כץ, שמעיה מסעמיהאל","b":"רב בסעמיהאל-תרכ\"ו","s":"אוצר הרבנים 19993"},{"i":26158,"n":"כץ, שמריה (שמרל) הכהן מלבוב","dt":"תסג - ד כסלו","dp":"לבוב","b":"מגיד בלבוב. נינתו - אשת בעל פני יהושע. נהרג במפולת בלבוב עם 36 נפשות מישראל.","s":"אוצר הרבנים 20017; מצבות קדש-לבוב; בובר-לבוב"},{"i":26159,"n":"כץ, שמריהו הלוי מויז'ון","f":"חיים מפומפיאן-עונג ח","bt":"תרלח","dt":"תרעט - אלול","b":"חתן ר אלעזר דון יחיא מלוצין בעל \"אבן שתיה\". אב\"ד ויז'ון-תרסג, ווישניוואלאצק-תרעו.","s":"אוצר הרבנים 20015; ליטא; אהלי שם"},{"i":26160,"n":"כץ, שמשון","f":"פנחס יצחק","b":"נכד ר נפתלי בעל \"סמיכת חכמים\". הניח חבור בכת\"י בשם \"מסכת שמשון\" ובו גם ליקוטים מאביו וזקנו.","s":"מתוך קטלוג"},{"i":26161,"n":"כץ, תנחום מקראקא","f":"יוסף","dt":"שעה - כז טבת","dp":"קראקא","b":"דיין בקראקא. אחיו - ר אהרן משה.","s":"אוצר הרבנים 20185; שם הגדולים השלישי; צונץ-קראקא"},{"i":26162,"n":"כץ-גולדמן, יוסף אלימלך מבסרמין","b":"דומ\"צ בבסרמין-תר\"מ","s":"אוצר הרבנים 8711"},{"i":26163,"n":"כץ-הלפרן, ישעיה משברשין","f":"אליעזר ליפמן הלפרן","b":"רב בשברשין-ת\"ק","s":"אוצר הרבנים 11720"},{"i":26164,"n":"כצמן, אשר","b":"תלמיד ר דוד הכהן רפפורט בעל 'מקדש דוד'. ר\"מ בישיבת 'תורה ודעת', חיבר מאמר לזכר רבו בקובץ 'אלה אזכרה'."},{"i":26165,"n":"כצמן, גרשון הכהן מפוחאביץ","k":"בעל הגיונות הגרשוני","b":"רב בפוחאוויץ, סן פרנציסקו.","s":"אמריקה"},{"i":26166,"n":"כצקלס, הלנה","k":"בעל די נאטור ארום או","bt":"1882","bp":"קובנא","b":"פעילה בבונד, מחנכת ועורכת תכנית להוראת מדעי הטבע. מורה בסמינר למורים של שמואל לוין בקובנא. ביקרה בארצות רבות ובהם בא\"י ותיארה את רשמיה במאמרים וחוברות. בזמן השואה היתה בסטלינגרד, ב-1944 חזרה לקובנא והתמסרה לחינוך יתומי שואה. חיברה גם \"פינלנד\", ועוד. תרגמה ספרי ילדים.","s":"ליטא"},{"i":26167,"n":"כרבשא, יוסף מפאס","b":"מחכמי פאס-שנות ה-ר', נזכר ב\"חוט המשולש\" לר\"ש צרור.","s":"מלכי רבנן"},{"i":26168,"n":"כרוב, חיים מלארסו","b":"גביר בלארסו, מכתב ממנו-תעא לר שלמה אברבנל-חתנו של ר יעקב די בוטון. משפחת כרוב נזכרת בספר בניהו על יחסי יהודי יון ויהודי איטליה.","s":"מתוך קטלוג"},{"i":26169,"n":"כרוב, יוסף מאיטליה","f":"אברהם","b":"רב באיטליה-של בזמן ר יחיאל טרבוט.","s":"איטליה גירונדי-י צו; אוצר הרבנים 8377"},{"i":26170,"n":"כרוב, שלמה מאגאדיר-מרוקו","b":"מחכמי אגדיר(=אגאדיר)-מרוקו, חתם-תצה על פס\"ד עם ר דוד בן אשר ן צור.","s":"מלכי רבנן"},{"i":26171,"n":"כרופ, שלמה מיעזרנה","k":"אדמור מיעז'רנה","b":"בן למשפחה פשוטה, ולפתע נתפרסם והמונים נהרו אליו.","s":"אלפסי"},{"i":26172,"n":"כרייף, אברהם ממכנאס","dt":"תקסה - טז אב","b":"מחכמי מכנאס. קינה לזכרו ב\"קול יעקב\".","s":"מלכי רבנן"},{"i":26173,"n":"כרייף, בנימין ממכנאס","f":"יחיא","k":"בעל גבול בנימין","b":"נכד-בן בתו ר משה בירדוגו-המשבי\"ר, חתן ר דוד ן חסין בעל \"תהלה לדוד\". מו\"ץ במכנאס-תקנח. תלמיד ר' רפאל בירדוגו, חתן המשורר, ר' דוד בן חסין, חיבר שו\"ת \"גבול בנימין\"","s":"ארזי הלבנון; מלכי רבנן"},{"i":26174,"n":"כרייף, יחיא ממכנאס","f":"יחיא","b":"נקרא על שם אביו. מחכמי מכנאס, חתם בהקדמת \"ראש משביר\"-תר.","s":"מלכי רבנן"},{"i":26175,"n":"כרייף, יחיא ממכנאס - הזקן","b":"מחכמי מכנאס. בנו - ר בנימין בעל \"גבול בנימין\".","s":"מלכי רבנן"},{"i":26176,"n":"כרייף, יחיא ממכנאס-הנכד","f":"בנימין","b":"מחכמי מכנאס-תקצט.","s":"מלכי רבנן"},{"i":26177,"n":"כרייף, משה מתונס","k":"בעל שיטות על הש\"ס","b":"תלמיד ר צמח צרפתי, ור יצחק למברוזו. למד ביחד עם ר דוד בונאן אב\"ד פורטוגזים בתונס. חיבר שיטה שהדפיסה חברו רד\"ב בעזרת הקאייד נסים שמאמא. מנכדיו - ר אברהם כהן יצחקי בעל \"משמרות כהונה\", ר משה שאלתיאל שסייעו בהדפסת ספרו.","s":"ארזי הלבנון"},{"i":26178,"n":"כרייף, שלם ממרוקו","f":"יהודה","b":"מחכמי מרוקו, חתם-תעז על פס\"ד עם ר יהודה הלוי.","s":"מלכי רבנן"},{"i":26179,"n":"כריסדה, עמרם מלוב","bt":"תק","dt":"תקע - בערך","b":"רב בלוב. הניח חדושים בכת\"י, והיו בידי ההיסטוריון - ישראל בלוב, ונזכר אצל ר גבריאל רוקח.","s":"מלכי חי\"ל-מרציאנו"},{"i":26180,"n":"כריסטינפולר מאיר","bt":"1740","dt":"ה'תקסה 1805","s":"היברובוקס","bk":[["יד המאיר",""]]},{"i":26181,"n":"כרמולי אליקים","bt":"1802","dt":"ה'תרלה 1875","s":"היברובוקס","bk":[["אגודת אגדות",""],["דברי הימים לבני יחייא",""],["העורבים ובני יונה",""],["חקקי אבן",""],["מבשרת ציון",""],["תולדות גדולי ישראל",""]]},{"i":26182,"n":"כרמי, אברהם","b":"רב ודיין-ת\"ק","s":"אוצר הרבנים 506; ארזי הלבנון"},{"i":26183,"n":"כרמי, יהודה דוד מקרפנטרץ","b":"רב בקארפינטרץ","s":"ארזי הלבנון"},{"i":26184,"n":"כרמי, יוסף","b":"מגדולי רבני איטליה-תקל\"ה","s":"אוצר הרבנים 8378"},{"i":26185,"n":"כרמי, יוסף ידידיה מאיטליה","k":"בעל כנף רננים","b":"מגדולי חכמי איטליה-ש\"ס","s":"אוצר הרבנים 8814"},{"i":26186,"n":"כרמי, מרדכי מקרפנטרץ","f":"אברהם","k":"בעל מאמר מרדכי","b":"רב בקרפנטרץ-תקלז, וחיבר \"מאמר מרדכי\" ובו השיג הרבה על החיד\"א, (שפגשו גם בקרפנטרץ וגם בליוורנו), ושהסכים על ספרו, למרות שלא עבר עליו. החיד\"א השיב לו בספרו \"מחזיק ברכה\", ר מרדכי חיבר \"דברי מרדכי\" כנגד \"מחזיק ברכה\". ר אברהם בלעיש מתונס שכיהן כרב בניצה-צרפת, השיב לר מרדכי ב\"יד אבישלום\".","s":"איטליה גירונדי-מ טז; מלכי רבנן; אוצר הרבנים 13874; ארזי הלבנון"},{"i":26187,"n":"כרמי, שלמה חיים מליוורנו","f":"אברהם כרמי","k":"בעל חשק שלמה","b":"מחכמי ליוורנו-תק, אחיו של ר מרדכי כרמי בעל \"מאמר מרדכי\" וכתב הקדמה לספר אחיו.","s":"אוצר הרבנים 18826; ארזי הלבנון"},{"i":26188,"n":"כרמייה, יצחק אהרן אדולף מצרפת","f":"משה","bt":"תקנו","bp":"ניס-צרפת","dt":"תרם - כט שבט","dp":"פריס","b":"ראש תנועת \"אליאנס\" בצרפת - שפעלה למען השכלה בקהלות המזרח, וחברת כי\"ח. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב.","s":"זכרון שלוניקי-132; אוצר כתבי עת-לוין; גאון-יהודי המזרח; פין-כנסת ישראל"},{"i":26189,"n":"כרמל, מנשה מקראקא","bt":"תקעב","dt":"תרמה","b":"רב בקראקא.","s":"וונדר-גליציה ח\"ג"},{"i":26190,"n":"כרמלי, ברוך מעזה","b":"רב בעזה-תך אצל ר יעקב נג'ארה.","s":"רוזניס-תורכיה-ד"},{"i":26191,"n":"כרסנתי, בוי יזו","b":"מחכמי מרוקו, מקובל","s":"ארזי הלבנון"},{"i":26192,"n":"כרסנתי, שלמה דון מליסבון","b":"רופא בליסבון, אחר הגירוש הגיע לתורכיה. ניסה לפשר במחלוקת באבילונה-אלבניה בין קהלת קשטיליה לקהלת פורטוגל.","s":"רוזניס-תורכיה-א"},{"i":26193,"n":"כרפס, יעקב משה","b":"גביר בקובנא, ועוסק בחסד והכנסת אורחים. ידידו של ר ישראל סלנט שהיה מתארח אצלו, וכן סייע לגדול ממינסק שהתגורר אצלו בהיותו בקובנא.","s":"הגדול ממינסק"},{"i":26194,"n":"כשדאי, צבי","k":"בעל קטעי זכרונות","bt":"1865","bp":"דובובה-פלך קיוב","dt":"1937","b":"סופר."},{"i":26195,"n":"כשר, מנחם מנדל מוארשא","k":"בעל תורה שלמה","b":"רב בוארשא. מראשי ישיבת מנישביץ בירושלים (ישיבה שהוחזקה בידי משפחת מנישביץ מארה\"ב). עורך \"דגל התורה\" וארשא תרפא. פרסם מאמרים ב\"בית תלמוד\" - ירושלים תרצב, \"כרם ציון\" - ירושלים תשכג - קובץ \"מדרש בני ציון\", \"המאור\" - תל אביב תרצה, \"סיני\" - ירושלים תרצז, \"תלפיות\" - נ\"י תשד.","s":"אוצר כתבי עת-לוין"},{"i":26196,"n":"כשר, שמעון","f":"מנחם מנדל מוארשא","k":"בעל סולמות לרום","bt":"תרעד","dt":"תשכח - ו תמוז","b":"משורר, עלה לארץ-תרפה.","s":"מתוך קטלוג"},{"i":26197,"n":"כתב יד פארמה די רוססי","s":"היברובוקס","bk":[["מחזור ספרדי לר\"\"ה ויום כפור משנת 1320",""]]},{"i":26198,"n":"כתבן, אבנר מסניאטין","k":"בעל אבל משה","bt":"תקצא","bp":"סניאטין","dt":"תרנח","b":"רב בסאניווץ, מיהאלן, פנטשיא, בראילה-תרכז, קריובה-ואלאכיה, רימניק-סרעט. חיבר \"אבל משה\" ראדוויץ תרמה.","s":"וונדר-גליציה ח\"ו; שם הגדולים השלישי"},{"i":26199,"n":"כתריאל יצחק","f":"ראובן אמסציסלאווער","dt":"תרמג - כד אדר","s":"אוצר הרבנים 12449"},{"i":26200,"n":"כתריאל מקושטא","f":"יקותיאל","k":"שלמה משאמאוו","b":"מדפיס אצל אברהם פרנקו תח.","s":"רוזניס-תורכיה-ד"},{"i":26201,"n":"כתריאל מקלוש","f":"יעקב","b":"רב בקלוש, סקאלא.","s":"וונדר-גליציה ח\"ג"},{"i":26202,"n":"כתריאל מקראקא","b":"רב בקראקא-שנז, נזכר בסדר הדורות.","s":"צונץ-קראקא"}];
